3\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"90.3079833984375\" x2=\"198.625\" y2=\"90.3079833984375\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"78.21720377604167\" x2=\"198.625\" y2=\"78.21720377604167\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"66.12642415364583\" x2=\"198.625\" y2=\"66.12642415364583\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"54.03564453125\" x2=\"198.625\" y2=\"54.03564453125\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"41.944864908854164\" x2=\"198.625\" y2=\"41.944864908854164\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"29.854085286458332\" x2=\"198.625\" y2=\"29.854085286458332\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"17.7633056640625\" x2=\"198.625\" y2=\"17.7633056640625\" stroke=\"#757576\" stroke-width=\"1px\"></line><line x1=\"0\" y1=\"5.672526041666666\" x2=\"198.625\" y2=\"5.672526041666666\" stroke=\"#757576\" stroke-width=\"1px\"></line></g></g><g fill=\"none\" font-size=\"10\" font-family=\"sans-serif\" text-anchor=\"middle\" transform=\"translate(0,198.625)\"><g opacity=\"1\" transform=\"translate(24.681559244791668,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">2</text></g><g opacity=\"1\" transform=\"translate(48.863118489583336,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">4</text></g><g opacity=\"1\" transform=\"translate(73.044677734375,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">6</text></g><g opacity=\"1\" transform=\"translate(97.22623697916667,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">8</text></g><g opacity=\"1\" transform=\"translate(121.40779622395834,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">10</text></g><g opacity=\"1\" transform=\"translate(145.58935546875,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">12</text></g><g opacity=\"1\" transform=\"translate(169.77091471354169,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">14</text></g><g opacity=\"1\" transform=\"translate(193.95247395833334,0)\"><line stroke=\"currentColor\" y2=\"6px\" y1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" y=\"8\" dy=\"0.71em\" style=\"font-family: Noto Serif; font-size: 15px\" x=\"0\">16</text></g><line x1=\"-15\" x2=\"198.625\" stroke=\"currentColor\" stroke-width=\"1.5px\"></line><line id=\"x-axis-marker-line\" x1=\"-15\" x2=\"198.625\" stroke=\"currentColor\" stroke-width=\"1.5px\" marker-end=\"url(#arrow)\"></line><text style=\"text-anchor: start; dominant-baseline: middle; font-family: Noto Serif; font-style: italic; fill: currentColor; font-size: 15px\" transform=\"translate(210.625,0)\">x</text></g><g fill=\"none\" font-size=\"10\" font-family=\"sans-serif\" text-anchor=\"end\" transform=\"translate(0,0)\"><g opacity=\"1\" transform=\"translate(0,174.94344075520834)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">2</text></g><g opacity=\"1\" transform=\"translate(0,150.76188151041666)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">4</text></g><g opacity=\"1\" transform=\"translate(0,126.580322265625)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">6</text></g><g opacity=\"1\" transform=\"translate(0,102.39876302083333)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">8</text></g><g opacity=\"1\" transform=\"translate(0,78.21720377604167)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">10</text></g><g opacity=\"1\" transform=\"translate(0,54.03564453125)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">12</text></g><g opacity=\"1\" transform=\"translate(0,29.854085286458332)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">14</text></g><g opacity=\"1\" transform=\"translate(0,5.672526041666666)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px\">16</text></g><line y1=\"213.625\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1.5px\"></line><line id=\"y-axis-marker-line\" y1=\"213.625\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1.5px\" marker-end=\"url(#arrow)\"></line><text style=\"text-anchor: middle; dominant-baseline: text-after-edge; font-family: Noto Serif; font-style: italic; fill: currentColor; font-size: 15px\" dy=\"0\" transform=\"translate(0,-12)\">y</text></g><text x=\"0\" y=\"198.625\" dx=\"-13.25px\" dy=\"13.5px\" fill=\"currentColor\" style=\"font-size: 15px; font-style: italic; font-family: Noto Serif\">O</text><path d=\"M0,41.445L198.621,77.558\" stroke=\"black\" stroke-width=\"2px\" fill=\"none\" stroke-dasharray=\"none\"></path><path d=\"M0,113.99L198.621,41.764\" stroke=\"black\" stroke-width=\"2px\" fill=\"none\" stroke-dasharray=\"none\"></path><circle cx=\"0\" cy=\"41.444864908854164\" r=\"4px\" fill=\"currentColor\"></circle><circle cx=\"0\" cy=\"113.98954264322917\" r=\"4px\" fill=\"currentColor\"></circle><circle cx=\"132.99857584635419\" cy=\"65.62642415364583\" r=\"4px\" fill=\"currentColor\"></circle></g><g transform=\"translate(237.015625, 254.625)\"><text transform=\"translate(0, 0)\" fill=\"currentColor\" style=\"font-family: Noto Serif; font-size: 15px\" text-anchor=\"middle\" dominant-baseline=\"hanging\">Years since 2010</text></g><g transform=\"translate(51.3515625, 104.3125)\"><text transform=\"translate(0, 0)\" fill=\"currentColor\" style=\"font-family: Noto Serif; font-size: 15px\" text-anchor=\"middle\" dominant-baseline=\"text-before-edge\">Number of</text><text transform=\"translate(0, 20)\" fill=\"currentColor\" style=\"font-family: Noto Serif; font-size: 15px\" text-anchor=\"middle\" dominant-baseline=\"text-before-edge\">participants</text><text transform=\"translate(0, 40)\" fill=\"currentColor\" style=\"font-family: Noto Serif; font-size: 15px\" text-anchor=\"middle\" dominant-baseline=\"text-before-edge\">(in thousands)</text></g></svg><div role=\"region\" aria-label=\"Long description for graph of a system of 2 lines\" class=\"sr-only\"><ul><li>For the first line in the system:\n<ul><li>The line slants gradually up from left to right.</li><li>The line passes through the following points:\n<ul><li>(0 comma 7)</li><li>(11 comma 11)</li></ul></li></ul></li><li>For the second line in the system:\n<ul><li>The line slants gradually down from left to right.</li><li>The line passes through the following points:\n<ul><li>(0 comma 13)</li><li>(11 comma 11)</li></ul></li></ul></li><li>The 2 lines intersect at 1 point.</li></ul></div></figure></p><p>The functions $f$ and $g$ model the number of participants, in thousands, in two different programs $x$ years since $2010$. The graphs of $y=f(x)$ and $y=g(x)$ are shown. Which of the following could represent functions $f$ and $g$?</p>","choices":[{"label":"A","text":"$f(x)=-\\frac{4}{11}x+13$\n$g(x)=\\frac{2}{11}x+7$"},{"label":"B","text":"$f(x)=-\\frac{4}{11}x+7$\n$g(x)=\\frac{2}{11}x+13$"},{"label":"C","text":"$f(x)=-\\frac{2}{11}x+13$\n$g(x)=\\frac{4}{11}x+7$"},{"label":"D","text":"$f(x)=-\\frac{2}{11}x+7$\n$g(x)=\\frac{4}{11}x+13$"}],"correct_answer":"C","explanation":"Choice C is correct. A line in the xy-plane that passes through the points $(x_1,y_1)$ and $(x_2,y_2)$ has slope $m$, where $m=\\frac{y_2-y_1}{x_2-x_1}$. The equation of the line can be written in the form $y=mx+b$, where $b$ is the y-intercept represented by $(0,b)$. One of the lines shown in the graph passes through the points $(0,7)$ and $(11,11)$. Substituting $0$ for $x_1$, $7$ for $y_1$, $11$ for $x_2$, and $11$ for $y_2$ in the equation $m=\\frac{y_2-y_1}{x_2-x_1}$ yields $m=\\frac{11-7}{11-0}$, or $m=\\frac{4}{11}$. Substituting $\\frac{4}{11}$ for $m$ and $7$ for $b$ in the equation $y=mx+b$ yields $y=\\frac{4}{11}x+7$. Therefore, an equation of this line is $y=\\frac{4}{11}x+7$. Similarly, the other line shown in the graph passes through the points $(0,13)$ and $(11,11)$. Substituting $0$ for $x_1$, $13$ for $y_1$, $11$ for $x_2$, and $11$ for $y_2$ in the equation $m=\\frac{y_2-y_1}{x_2-x_1}$ yields $m=\\frac{11-13}{11-0}$, or $m=\\frac{-2}{11}$. Substituting $\\frac{-2}{11}$ for $m$ and $13$ for $b$ in the equation $y=mx+b$ yields $y=\\frac{-2}{11}x+13$. Therefore, an equation of this line is $y=\\frac{-2}{11}x+13$. So, the functions $f$ and $g$ could be represented by $f(x)=\\frac{-2}{11}x+13$ and $g(x)=\\frac{4}{11}x+7$.\nChoice A is incorrect and may result from conceptual or calculation errors.\nChoice B is incorrect and may result from conceptual or calculation errors.\nChoice D is incorrect and may result from conceptual or calculation errors.","is_grid_in":false},{"source_id":"935f3403","section":"math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","passage":null,"passage_html":null,"question_text":"For a restaurant owner to purchase a pizza oven at a total price of $13,000$ dollars, a onetime down payment is required, and then fixed monthly payments are made for the remaining amount owed for the pizza oven. The equation $13,000=2,800+200t$ represents this situation, where $t$ is the number of fixed monthly payments that are made. Which of the following is the best interpretation of $200$ in this context?","question_text_html":null,"choices":[{"label":"A","text":"The amount, in dollars, of the down payment"},{"label":"B","text":"The amount, in dollars, of each fixed monthly payment"},{"label":"C","text":"The total amount, in dollars, paid for the pizza oven after $t$ fixed monthly payments"},{"label":"D","text":"The total number of fixed monthly payments"}],"correct_answer":"B","explanation":"Choice B is correct. For a restaurant owner to purchase a pizza oven at a total price of $13,000$ dollars, a onetime down payment is required, and then fixed monthly payments are made for the remaining amount owed for the pizza oven. It’s given that the equation $13,000=2,800+200t$ represents this situation, where $t$ is the number of fixed monthly payments that are made. In this equation, $2,800$ is a constant term, which represents the onetime down payment, in dollars, and $200$ is the coefficient of $t$. Multiplying $200$ by $t$ gives the total amount, in dollars, paid by the fixed monthly payments. Therefore, the best interpretation of $200$ in this context is the amount, in dollars, of each fixed monthly payment.\nChoice A is incorrect. This is the best interpretation of $2,800$, not $200$, in this context.\nChoice C is incorrect. This is the best interpretation of $13,000$, not $200$, in this context.\nChoice D is incorrect. This is the best interpretation of the variable $t$, not $200$, in this context.","is_grid_in":false},{"source_id":"0c490cd5","section":"math","domain":"Algebra","skill":"Linear functions","difficulty":"easy","passage":null,"passage_html":null,"question_text":"Sam has a flag with an area of $\\text{110}\\text{square}\\text{inches}(in^2)$. Sam plans to enlarge the flag by sewing on pieces of colored nylon, where each piece would increase the flag's area by $64in^2$. Which equation gives the flag's total area $y$, in square inches, after Sam sews on $x$ pieces of nylon?","question_text_html":null,"choices":[{"label":"A","text":"$y=64x$"},{"label":"B","text":"$y=64+110x$"},{"label":"C","text":"$y=110+64x$"},{"label":"D","text":"$y=174x$"}],"correct_answer":"C","explanation":"Choice C is correct. It's given that Sam has a flag with an area of $110\\text{square}\\text{inches}(\\text{in}^2)$ and that each piece of colored nylon Sam sews on increases the flag's area by $64\\text{in}^2$. If Sam sews on $x$ pieces of nylon and each piece increases the area by $64\\text{in}^2$, it follows that the expression $64x$ represents the total increase in area, in square inches, from sewing on $x$ pieces of nylon. Adding this increase in area, $64x\\text{in}^2$, to the original area of the flag, $110\\text{in}^2$, gives the total area of the flag. Therefore, the equation that gives the flag's total area $y$, in square inches, after Sam sews on $x$ pieces of nylon is $y=110+64x$.\nChoice A is incorrect. This equation represents the total area, in square inches, of $x$ pieces of colored nylon.\nChoice B is incorrect and may result from conceptual or calculation errors.\nChoice D is incorrect and may result from conceptual or calculation errors.","is_grid_in":false},{"source_id":"4722abd2","section":"math","domain":"Algebra","skill":"Linear equations in two variables","difficulty":"medium","passage":null,"passage_html":null,"question_text":"Line $p$ is defined by $2y+8x=11$. Line $r$ is perpendicular to line $p$ in the xy-plane. What is the slope of line $r$?","question_text_html":null,"choices":[{"label":"A","text":"$-4$"},{"label":"B","text":"$-\\frac{1}{4}$"},{"label":"C","text":"$\\frac{1}{4}$"},{"label":"D","text":"$4$"}],"correct_answer":"C","explanation":"Choice C is correct. It’s given that line $p$ is defined by the equation $2y+8x=11$. The equation can be written in slope-intercept form $y=mx+b$, where $m$ represents the slope of the line. Subtracting $8x$ from both sides of the equation $2y+8x=11$ yields $2y=-8x+11$. Dividing both sides of this equation by $2$ yields $y=-4x+\\frac{11}{2}$. Therefore, the slope of line $p$ in the xy-plane is $-4$. It's also given that line $p$ is perpendicular to line $r$. Perpendicular lines have slopes that are negative reciprocals of each other, so the slope of line $r$ is $-\\frac{1}{(-4)}=\\frac{1}{4}$.\nChoice A is incorrect. This is the slope of line $p$, not line $r$.\nChoice B is incorrect. This is the reciprocal, not the negative reciprocal, of the slope of line $p$.\nChoice D is incorrect. This is the negative, not the negative reciprocal, of the slope of line $p$.","is_grid_in":false},{"source_id":"2903668a","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"The interiors of many temples in the ancient Middle East needed to satisfy a precise set of acoustic demands: the sounds of chants and hymns should travel with clarity, while profound silences should be fully felt and appreciated. In a research paper, a student claims that the users of one such temple were aware of how the materials that were used within the structure could affect sound quality and that they deliberately applied this knowledge to influence how sound was experienced in the space.","passage_html":null,"question_text":"Which quotation from a work by a historian would most directly support the student’s claim?","question_text_html":null,"choices":[{"label":"A","text":"“Many researchers believe that the central chamber of the temple had a high ceiling, a feature that has since become essential to the acoustic design of modern concert halls.”"},{"label":"B","text":"“The innermost room of the temple was likely among the quietest spaces in the interior of the temple.”"},{"label":"C","text":"“The acoustic environment of the temple was best suited for music that eschewed ornamentation in favor of simple melodies, harmonies, and rhythms.”"},{"label":"D","text":"“During special occasions, curtains were placed inside the temple to minimize reverberation and confine the sound to designated locations.”"}],"correct_answer":"D","explanation":"Choice D is the best answer because it provides a quotation that would most directly support the student’s claim that the temple’s users were aware of how materials used in the temple affected sound and deliberately applied that knowledge to shape the sonic experience of people in the space. The quotation indicates that curtains would, at times, be installed specifically “to minimize reverberation and confine the sound,” thereby illustrating that the users of the temple had knowledge of the acoustic properties of materials within the temple (how curtains dampen sound) and employed this knowledge to affect the experience of sound within the space.\nChoice A is incorrect. Although the quotation describes a feature of the temple’s structure (the high ceiling), it makes no mention of the materials used, the materials’ acoustic properties, or temple users’ awareness of how materials impact sound quality. Choice B is incorrect because it doesn’t address any materials that were used in the temple, let alone their acoustic properties or temple users’ awareness of how materials impact sound quality. Choice C is incorrect because it doesn’t address any materials that were used in the temple, let alone their acoustic properties or temple users’ awareness of how materials impact sound quality.","is_grid_in":false},{"source_id":"ebe1eabd","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Although Eastern North Pacific (ENP) gray whales generally migrate between their wintering waters along the coast of Mexico and their foraging waters in the Arctic, a subset of this population—known as the Pacific Coast Feeding Group (PCFG)—forages along the coastlines of Northern California (USA) and British Columbia (Canada) instead. Interestingly, individuals in this subset reach smaller maximum sizes than other ENP whales do, despite having similar pre-maximum growth rates. Researchers hypothesize that this difference may be an adaptation to distinct resource opportunities in the PCFG foraging range.","passage_html":null,"question_text":"Which finding, if true, would most directly support the researchers’ claim regarding the size of PCFG whales?","question_text_html":null,"choices":[{"label":"A","text":"The average body size of PCFG whales observed along the coasts of Northern California and British Columbia has remained relatively steady in recent decades, while the average body size of ENP whales in the main group has slightly decreased."},{"label":"B","text":"When present along the coasts of Northern California and British Columbia, PCFG whales tend to forage in rocky kelp beds at shallow depths inaccessible to whales as large as those in the ENP main group."},{"label":"C","text":"When foraging along the coasts of Northern California and British Columbia, PCFG whales are in closer proximity to major ports and urban populations than ENP whales in the main group are when foraging in Arctic waters."},{"label":"D","text":"Certain crustacean prey species available along the coasts of Northern California and British Columbia where PCFG whales tend to forage are not available in the Arctic waters where ENP whales in the main group forage."}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a finding that, if true, would most directly support the researchers’ hypothesis that the smaller maximum size of PCFG whales is an adaptation to resource opportunities particular to their foraging range. The text explains that PCFG whales, a subgroup of ENP gray whales, forage along the coasts of Northern California and British Columbia rather than in the Arctic, where the main ENP group forages. The text goes on to state that PCFG whales reach smaller maximum sizes than other ENP gray whales despite having similar pre-maximum growth rates. If PCFG whales tend to forage in shallow, rocky kelp beds that whales as large as those in the main group cannot access, that would indicate that smaller body size confers a direct advantage in this foraging range—namely, access to a food source that larger whales cannot reach.\nChoice A is incorrect because a finding describing recent trends in average body size for both groups of whales wouldn’t address whether the smaller maximum size of PCFG whales reflects an adaptation to their foraging environment. Recent stability or change in average size doesn’t speak to why the size difference between PCFG whales and the main ENP group exists. Choice C is incorrect because a finding about PCFG whales’ proximity to ports and urban populations wouldn’t address the resources available to PCFG whales or the relationship between body size and foraging. Proximity to human activity is irrelevant to a hypothesis about body size being an adaptation to resource opportunities. Choice D is incorrect. Although a finding about a certain prey species being available in the PCFG whales’ foraging waters but not in the main group of ENP whales’ foraging waters would establish that the PCFG foraging range offers distinct prey species, it wouldn’t connect the availability of those prey species to body size in a way that would explain the PCFG whales’ smaller size. Without indicating that the available prey in the PCFG range favors smaller whales, the finding falls short of supporting the hypothesis that smaller size is an adaptation to resource opportunities.","is_grid_in":false},{"source_id":"7575e417","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Economists have demonstrated that herding—in which individuals converge on the same action by imitating the economic decisions of one or more peers—occurs among investors. Investigating whether herding also occurs among nations in matters of economic policy, Maru Etta-Nkwelle examined changes in the foreign currency reserves of emerging economies in various world regions in the years following the widespread financial crisis of 1997. Etta-Nkwelle posited that herding would manifest in regional peer countries converging on the same foreign currency accumulation rate regardless of each country’s observable circumstances. She found that Asian countries showed evidence of herding but African countries did not.","passage_html":null,"question_text":"Based on the text, which finding, if true, would best account for the discrepancy Etta-Nkwelle observed?","question_text_html":null,"choices":[{"label":"A","text":"The majority of the currency held in reserves by the African countries was foreign currency, whereas the majority of the currency held in reserves by the Asian countries was domestic currency."},{"label":"B","text":"Most of the African countries belonged to international economic unions that set individual foreign-currency accumulation policies for each member, whereas the Asian countries were largely free to set their own policies."},{"label":"C","text":"The 1997 financial crisis resulted in immediate declines in many of the African countries’ foreign currency reserves, whereas the crisis had few short-term effects on the foreign currency reserves of most of the Asian countries."},{"label":"D","text":"The African countries tended to accumulate a variety of foreign currencies for their reserves, whereas the Asian countries tended to favor a single foreign currency for their reserves."}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a finding that, if true, would best account for the discrepancy Etta-Nkwelle observed: Asian countries showed evidence of herding (converging on the same foreign currency accumulation rate as their regional peers), while African countries did not. The text defines herding as individuals converging on the same action by imitating their peers, which implies that the individuals choose to do so rather than being compelled to follow a particular course of action. This choice indicates that most of the African countries belonged to economic unions that dictated such monetary policies, whereas Asian countries were free to choose, and the similarity among the Asian countries suggests that herding can account for that similarity. The finding thus identifies a relevant difference between the two regions that accounts for the discrepancy.\nChoice A is incorrect. Although this choice is related to reserves of foreign currency, the fact that African and Asian countries had different mixes of foreign and domestic currency reserves does not address the rate of foreign currency accumulation or whether herding is a contributing factor determining the rate of accumulation. Choice C is incorrect. This choice does not address currency accumulation. And although it describes differences in the currency reserves of African and Asian countries shortly after the 1997 financial crisis, it does not address the rate of foreign currency accumulation nor how similar the nations were in this regard to their neighboring countries. Choice D is incorrect. Although this choice discusses the variety of foreign currencies accumulated by African countries as compared with Asian countries, it does not discuss the rate of foreign currency accumulation nor whether herding is a factor determining the rate of accumulation.","is_grid_in":false},{"source_id":"d6e97054","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"easy","passage":"Four Studies of Food Choices in Various Contexts\nLocationFood choices related to...Study populationNumber of participants\nCanadasportsadults17\nUnited Statesschoolchildren44\nIndiacommunityadolescents and adults94\nGhana and Kenyafood shopsadolescents142\nThe table shows information from four studies about food choices people make in different contexts. According to the table, the study with the smallest number of participants involved only adults, and the study with the greatest number of participants involved ______","passage_html":"<p><figure><table><caption><p>Four Studies of Food Choices in Various Contexts</p></caption><thead><tr><th scope=\"col\">Location</th><th scope=\"col\">Food choices related to...</th><th scope=\"col\">Study population</th><th scope=\"col\">Number of participants</th></tr></thead><tbody><tr><th scope=\"row\">Canada</th><td>sports</td><td>adults</td><td>17</td></tr><tr><th scope=\"row\">United States</th><td>school</td><td>children</td><td>44</td></tr><tr><th scope=\"row\">India</th><td>community</td><td>adolescents and adults</td><td>94</td></tr><tr><th scope=\"row\">Ghana and Kenya</th><td>food shops</td><td>adolescents</td><td>142</td></tr></tbody></table></figure></p><p>The table shows information from four studies about food choices people make in different contexts. According to the table, the study with the smallest number of participants involved only adults, and the study with the greatest number of participants involved <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","question_text":"Which choice most effectively uses data from the table to complete the text?","question_text_html":null,"choices":[{"label":"A","text":"only children."},{"label":"B","text":"both adolescents and adults."},{"label":"C","text":"only adolescents."},{"label":"D","text":"only adults."}],"correct_answer":"C","explanation":"Choice C is the best answer because it most effectively uses data from the table to complete the text’s comparison of the studies about food choices. The table shows information from four studies about food choices, including each study’s location, the context of the food choices examined, the study population, and the number of participants. According to the table, the study with the greatest number of participants (142) was conducted in Ghana and Kenya and involved only adolescents.\nChoice A is incorrect because the table indicates that the study that involved only children was conducted in the United States and had 44 participants—not the greatest number of participants. According to the table, the study with the greatest number of participants (142) involved only adolescents. Choice B is incorrect because the table indicates that the study population that consisted of both adolescents and adults was the India study, which had 94 participants—not the greatest number of participants. According to the table, the study with the greatest number of participants (142) involved only adolescents. Choice D is incorrect because, according to the table and the text, the study that involved only adults was conducted in Canada and had 17 participants—the smallest, not the greatest, number of participants in the table.","is_grid_in":false},{"source_id":"b0b40727","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"medium","passage":"Studies have demonstrated that positive feedback enhances real-world exercise performance and exercisers’ psychological experience of physical activity. Nicole Trewick and team tested their prediction that positive feedback would produce analogous results among participants cycling on a stationary bike in a virtual reality environment. After monitoring participants’ pedaling rate and heart rate to determine the effects on their physical endurance (e.g., their ability to sustain a certain target pedaling and heart rate) of feedback (positive, negative, or neutral) delivered at regular intervals, the researchers used participants’ questionnaire responses to assess their psychological experience of the task.","passage_html":null,"question_text":"Assuming participants had similar baseline fitness levels, which finding from the study, if true, would most strongly suggest that positive feedback had the predicted psychological effect but not the predicted physical effect?","question_text_html":null,"choices":[{"label":"A","text":"Compared with participants who received positive feedback, participants who received neutral feedback reported lower enjoyment of the activity on average but maintained their heart and pedaling rates for longer durations than participants who received negative feedback."},{"label":"B","text":"Compared with participants who received positive or neutral feedback, participants who received negative feedback reported lower enjoyment of the activity on average but maintained their heart and pedaling rates for longer durations."},{"label":"C","text":"Compared with participants who received negative feedback, participants who received neutral feedback reported similar levels of enjoyment of the activity on average but maintained their heart and pedaling rates for shorter durations than participants who received positive feedback."},{"label":"D","text":"Compared with participants who received negative or neutral feedback, participants who received positive feedback reported greater enjoyment of the activity on average but maintained their heart and pedaling rates for approximately similar durations."}],"correct_answer":"D","explanation":"Choice D is the best answer because it presents a finding that, if true, would most strongly suggest that positive feedback had the psychological effect Trewick and her team predicted but not the predicted physical effect. The text explains that Trewick and team predicted positive feedback would, in a virtual reality environment, replicate two real-world results: an enhanced psychological experience (higher enjoyment) and improved physical endurance (longer maintenance of target heart and pedaling rates). If participants who received positive feedback reported greater enjoyment than those who received negative or neutral feedback, that would indicate that the predicted psychological effect occurred. At the same time, if those participants maintained their heart and pedaling rates for approximately the same durations as participants in the other groups, that would indicate that the predicted physical effect did not occur, since positive feedback didn’t produce longer maintenance of target heart and pedaling rates. Together, these results would indicate that positive feedback produced the predicted psychological effect but not the predicted physical effect.\nChoice A is incorrect. Reported enjoyment being greater with positive feedback than with neutral feedback would be evidence of the predicted positive effect of positive feedback on participants’ psychological experience, but the fact that participants had greater endurance with neutral feedback than with negative feedback wouldn’t reveal anything about how endurance was affected by positive feedback, and thus wouldn’t show that positive feedback didn’t have the predicted physical effect. Choice B is incorrect. A finding that participants who received negative feedback reported lower enjoyment than participants who received positive or neutral feedback did would show that enjoyment was lowered by negative feedback but wouldn’t confirm that enjoyment was greater with positive feedback than with neutral feedback, which a finding would need to do to demonstrate that positive feedback enhanced enjoyment as predicted. Further, the fact that participants who received negative feedback had greater endurance than those who received positive or neutral feedback wouldn’t reveal whether positive feedback had an effect on endurance, either positive or negative. Choice C is incorrect because endurance being greater with positive feedback than with neutral feedback would show that positive feedback did have the predicted physical effect (enhancing endurance). Further, reported enjoyment being similar with neutral feedback and negative feedback wouldn’t reveal anything about how enjoyment was affected by positive feedback, and thus wouldn’t show that positive feedback had the predicted psychological effect.","is_grid_in":false},{"source_id":"58817765","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"Some geologists have proposed designating the period from 1950 to the present as a new geological epoch (the Anthropocene) characterized by human impact on Earth, but they have struggled to identify reliable stratigraphic markers of the epoch’s onset. Inta Dimante-Deimantovica and a research team investigated whether the initial appearance of primary microplastics—invented and mass-produced for industrial and other purposes, beginning around the middle of the twentieth century—in sedimentary layers could serve this role. The researchers analyzed European lake sediment profiles from the late eighteenth century to the present. Microplastics were present in all layers, likely because certain microplastic shapes enabled rapid downward migration. The researchers therefore concluded that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"the lowest sedimentary layer in which microplastics are found cannot be treated as indicative of the chronological beginning of the Anthropocene."},{"label":"B","text":"the presence of microplastics in sediment dating to the late eighteenth century casts doubt on the appropriateness of designating 1950 as the onset of the Anthropocene."},{"label":"C","text":"microplastics are not prevalent enough in sediment to serve as a reliable sign of the human impact characteristic of the Anthropocene."},{"label":"D","text":"using the earliest presence of microplastics as a stratigraphic marker of the beginning of the Anthropocene is likely to be viable in some locations but is not viable in Europe."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of microplastics as a proposed stratigraphic marker for the onset of the Anthropocene. The text indicates that although primary microplastics (used for industrial and other purposes) were invented and mass-produced beginning only around the mid-twentieth century, researchers found microplastics throughout European lake sediment profiles dating from the late eighteenth century to the present. According to the text, microplastics were in all layers of sediment likely because microplastics of certain shapes can rapidly migrate downward—that is, they can move into sedimentary layers that predate their manufacture. Since it can’t be assumed that the date of a layer in which microplastics are found indicates when the microplastics were first deposited, it follows that the lowest sedimentary layer containing microplastics can’t be treated as indicative of the chronological beginning of the Anthropocene.\nChoice B is incorrect. The text explains that microplastics appeared in layers of sediment long predating 1950 likely because certain shapes allowed them to rapidly migrate downward—that is, the particles physically moved into older layers. This finding doesn’t cast doubt on the appropriateness of considering 1950 as the onset of the Anthropocene; it doesn’t suggest a flaw in thinking that humans’ impact on Earth shifted around 1950 but simply suggests that the position of microplastics in sediment isn’t useful as an indicator of such a shift. Choice C is incorrect because the issue presented in the text isn’t a lack of prevalence of microplastics (and though no quantity is indicated, microplastics were found across all the layers) but rather the inability to determine when microplastics were originally deposited, since the particles can migrate rapidly into older sediment layers. Choice D is incorrect because the text indicates that the likely cause of microplastics being present in all layers of the sediment profiles is a property of microplastic particles themselves (certain shapes allowing them to rapidly move downward into older layers), not a characteristic of European lake sediment or anything else specific to Europe. There’s no reason to think the issue of particle migration wouldn’t occur in other locations.","is_grid_in":false},{"source_id":"8e6a96f5","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"Duckweed is a small freshwater plant that is often exposed to zinc pollution. Sofia Vámos and colleagues collected samples of four duckweed ecotypes (genetically and geographically distinct populations within a species), along with water from each ecotype’s habitat. Hypothesizing that each ecotype is adapted to its local conditions in ways that bolster its growth and resistance to pollutants, the researchers grew each ecotype in all four water samples and with three levels of zinc (none, low, high). (The researchers did not replicate local differences in light or temperature.) They found that the ecotypes grew equally well in all four water samples and that adding zinc consistently enhanced growth, regardless of concentration, suggesting that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"while the ecotypes are genetically and geographically distinct, those differences do not represent adaptations to local environmental conditions."},{"label":"B","text":"there may not be significant differences in the water that each ecotype inhabits, but there are significant differences in each ecotype’s resistance to zinc pollution."},{"label":"C","text":"if each ecotype is indeed locally adapted as the researchers hypothesized, those adaptations are to other environmental conditions than the water each ecotype inhabits."},{"label":"D","text":"although the researchers’ hypothesis does not appear to be supported, this may be because the levels of zinc exposure the plants in the experiment received did not match their exposure in their natural environments."}],"correct_answer":"C","explanation":"Choice C is the best answer because it most logically completes the text’s discussion of Vámos and colleagues’ experiment with four duckweed ecotypes. According to the text, the researchers hypothesized that each ecotype is adapted to its local habitat in ways that help it grow more effectively and better tolerate pollutants. To test this, they grew each ecotype in water collected from all four habitats and exposed them to three different zinc levels. If the hypothesis were correct, each ecotype would be expected to thrive more in water from its own habitat than in the other waters and to respond to zinc levels differently depending on the level of zinc pollution in its home environment. However, the results showed that every ecotype grew just as well in every water sample, and that zinc boosted growth the same way across all ecotypes no matter the concentration. In other words, the experiment found no evidence that these ecotypes have specifically adapted to their local water or their local zinc exposure. It follows, then, that if each ecotype is actually locally adapted, it is adapted not to the water conditions in its habitat but to other environmental factors—such as local light or temperature levels, which the text notes the researchers didn’t account for in their experiment.\nChoice A is incorrect because the findings presented in the text suggest only that the ecotypes’ genetic and geographic differences don’t represent adaptations to local water conditions and zinc levels, not that the differences don’t represent adaptations to any local environmental conditions. Indeed, the text notes that the researchers didn’t account for light or temperature levels in each habitat, suggesting the possibility that the ecotypes are adapted to those or other local environmental factors. Choice B is incorrect because it contradicts the findings presented in the text. The text states that zinc consistently enhanced growth regardless of concentration, meaning the ecotypes all responded similarly to zinc. This uniform response indicates there aren’t significant differences in their resistance to zinc pollution. Choice D is incorrect because the findings presented in the text don’t demonstrate that the researchers’ hypothesis of local adaptation isn’t supported. That the ecotypes grew equally well in all of the water samples and equally benefited from added zinc at all levels, regardless of zinc levels in their natural environments, suggests only that the ecotypes aren’t adapted to their local water conditions and zinc levels; these findings don’t rule out the possibility that the ecotypes are adapted to other local factors in their habitats, such as light or temperature (which the text notes the researchers didn’t examine).","is_grid_in":false},{"source_id":"c6d7dc78","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"easy","passage":"Stores often play background music to create a pleasant shopping experience. Based on a survey, Amir Manzoor found that such music was linked to reduced enjoyment among customers. Manzoor thinks that one explanation for this result is that the surveyed customers may have wanted to finish their shopping as quickly as possible. They therefore weren’t focused on enjoying the experience. It’s possible that background music could improve the experience of other customers whose main goal is to have a good time while they shop.","passage_html":null,"question_text":"Based on the text, which research question was Manzoor’s study most likely intended to answer?","question_text_html":null,"choices":[{"label":"A","text":"Does the volume of a store’s background music affect how much time customers spend in the store?"},{"label":"B","text":"How does the use of background music in stores affect customers’ shopping experience?"},{"label":"C","text":"Do customers spend more money when shopping for music in stores or online?"},{"label":"D","text":"What genres of music do customers prefer to listen to while they are shopping?"}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a research question that is clearly addressed by Manzoor’s study as described in the text. The text indicates that Manzoor surveyed customers and found that background music was linked to reduced enjoyment while shopping. Manzoor then explains this result in terms of the music interfering with customers’ main goal (finishing their shopping as quickly as possible), speculating that background music might improve the experience of customers with different shopping goals. Throughout the text, the focus is on the relationship between background music and customers’ shopping experience, suggesting that Manzoor’s study was designed to answer how background music affects that experience.\nChoice A is incorrect because the text doesn’t mention the volume of background music or how much time customers spend in a store. Instead, the text focuses on whether background music is linked to customer enjoyment of the shopping experience. Choice C is incorrect because the text doesn’t address how much money customers spend or compare in-store and online purchasing. Rather, the text discusses background music played during shopping, not music as a product to be purchased. Choice D is incorrect because the text doesn’t discuss different genres of music or customers’ preferences for particular genres. Instead, the text addresses background music in general and its link to customer enjoyment.","is_grid_in":false},{"source_id":"3a489e1e","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Born in Chile in 1917, artist and ethnomusicologist Violeta Parra was a pioneer in the nueva canción chilena (Chilean New Song) movement that emerged in the late 1950s and then spread throughout Latin America, Portugal, and Spain as nueva canción. Parra traveled all over Chile compiling extensive records of authentic folk music as well as recipes, proverbs, and other facets of cultural history. These records formed the foundation for the early movement’s revival of traditional Chilean folk forms in new songs that represented modern realities of the working class and strongly advocated for social change. As the movement spread beyond Chile, the breadth of musical traditions incorporated into its foundation also expanded.","passage_html":null,"question_text":"Which detail about songs associated with nueva canción, if true, would best illustrate the underlined claim?","question_text_html":null,"choices":[{"label":"A","text":"Many feature political commentary addressing contemporary issues that stemmed from shared experiences of European colonization in Latin American countries."},{"label":"B","text":"Many demonstrate the stylistic influence of corrido, a genre of narrative songs from Mexico that had come to be characterized by political themes in the early 1800s."},{"label":"C","text":"Many were written with parts meant to be played on the quena, a traditional flute used across Andean countries, including Chile."},{"label":"D","text":"Many were produced by Argentinian artists in the late 1950s, with others by artists in additional Latin American countries first emerging soon after."}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a detail that, if true, would most effectively illustrate the underlined claim that as nueva canción spread beyond Chile, the breadth of musical traditions incorporated into its foundation also expanded. The text explains that the movement was initially founded on traditional Chilean folk forms compiled by Parra, so if many nueva canción songs demonstrate the stylistic influence of corrido—a Mexican narrative song genre—that would show that a musical tradition originating outside Chile became part of the movement’s foundation, directly illustrating the text’s claim about how the breadth of nueva canción expanded.\nChoice A is incorrect because the finding addresses lyrical content—political commentary on issues stemming from European colonization—rather than musical traditions. Even if nueva canción songs across different countries share political themes, that doesn’t indicate that new musical forms or styles were incorporated into the movement’s foundation. Thematic content is distinct from the musical traditions that songs draw on stylistically. Choice C is incorrect because the quena is described as a “traditional flute used across Andean countries, including Chile,” meaning it’s part of the Chilean folk tradition that underpinned nueva canción at its origin. Use of the quena therefore wouldn’t illustrate the incorporation of musical traditions beyond those that founded the early movement in Chile. Choice D is incorrect because the finding establishes only that artists in additional Latin American countries produced nueva canción songs, not that those artists incorporated musical traditions from their own countries into the movement. Artists in other countries could still have been drawing on the same Chilean folk forms that originally founded the movement, so geographic spread alone doesn’t illustrate an expansion of musical traditions.","is_grid_in":false},{"source_id":"640b60c2","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"medium","passage":"Archaeologists have observed similarities in the tools, such as bidirectional blades, uncovered at the Neolithic-period Mesopotamian settlement of Çayönü Tepesi and those uncovered at roughly contemporaneous settlements elsewhere in Southwest Asia, including those in the South Levant, Central Anatolia, and Central Zagros. Although similarities in tools could be attributed to imitative behavior or trade, Nefize Ezgi Altınışık et al. found evidence of genetic affinity among the populations of Çayönü Tepesi, Central Anatolia, the South Levant, and—to a lesser extent—Central Zagros.","passage_html":null,"question_text":"Information in the text best supports which statement about the finding made by Altınışık et al.?","question_text_html":null,"choices":[{"label":"A","text":"It implies that people and tools likely arrived in Çayönü Tepesi from settlements in Central Anatolia and the South Levant at an earlier time than they did from settlements in Central Zagros."},{"label":"B","text":"It raises the possibility that similarities in the design of tools found at Neolithic settlements in Southwest Asia emerged due to population blending between those settlements."},{"label":"C","text":"It suggests that in the Neolithic period, people in the South Levant and Central Anatolia imitated tool designs originating in Çayönü Tepesi more frequently than people in Central Zagros did."},{"label":"D","text":"It helps explain why contemporaneous Neolithic peoples in Southwest Asia had similar tools but lacked other obvious cultural similarities."}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a statement about Altınışık et al.’s finding that is supported by the text. The text notes that tool similarities across Neolithic settlements could be attributed to imitative behavior or trade. However, Altınışık et al. found evidence of genetic affinity (that is, genetic relatedness) among the populations of these settlements. Genetic relatedness among populations with similar tools raises an alternative possibility: the tool similarities may have emerged through population blending rather than through imitation or trade alone. Thus, the finding raises the possibility that tool design similarities resulted from population blending.\nChoice A is incorrect because the text doesn’t address the timing or direction of migration between settlements. Although lesser genetic affinity with Central Zagros could reflect various historical patterns, the text presents genetic relatedness as evidence of population intermixing, not as evidence about when people or tools arrived at particular locations. Choice C is incorrect because the text doesn’t indicate that tools originated specifically at Çayönü Tepesi or that other settlements imitated its designs. Although the text notes that genetic affinity with Central Zagros was found “to a lesser extent,” this describes degrees of genetic relatedness, not the frequency of tool imitation. Instead, the text presents tool similarities as a shared phenomenon across settlements. Choice D is incorrect because the text doesn’t discuss a lack of cultural similarities among Neolithic peoples in Southwest Asia. Rather, the text focuses solely on tool similarities and genetic affinity without addressing other cultural parallels or differences.","is_grid_in":false},{"source_id":"2b252bbd","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"Within higher education, studying philosophy requires that students be conversant with the field’s foundational texts and historical figures. By contrast, doing philosophy within or beyond the academy demands the creative, self-directed application of acquired expertise to enduring questions about the nature of existence and knowledge. While both approaches engage with influential figures, those who do philosophy treat such figures as vital interlocutors who facilitate new insights rather than as ossified authorities who, though relevant to the present, primarily represent the discipline’s past.","passage_html":null,"question_text":"Based on the text, which choice best describes the relationship between doing philosophy and studying philosophy?","question_text_html":null,"choices":[{"label":"A","text":"Doing philosophy helps students formulate concrete solutions to practical issues, whereas studying philosophy prioritizes engagement with historical arguments in the field."},{"label":"B","text":"Doing philosophy involves developing novel ideas through imagined dialogue with past philosophers based on knowledge of those philosophers’ views acquired by studying philosophy."},{"label":"C","text":"Doing philosophy requires students to challenge the ideas articulated by past philosophers, especially when these ideas are broadly accepted by other people studying philosophy."},{"label":"D","text":"Doing philosophy represents a departure from the norms that govern scholarly inquiry, whereas studying philosophy requires conforming to these norms."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most accurately describes the relationship between doing philosophy and studying philosophy as presented in the text. According to the text, studying philosophy requires being familiar with foundational texts and historical figures, while doing philosophy demands “the creative, self-directed application of acquired expertise”—a phrase implying that doing philosophy builds on knowledge gained through study. The text adds that those who do philosophy treat influential figures as “vital interlocutors who facilitate new insights” (that is, as dialogue partners whose ideas help generate new thinking). In other words, doing philosophy involves developing novel ideas through engagement with the ideas of past philosophers, knowledge of which can be acquired only by studying philosophy.\nChoice A is incorrect. While the text does state that studying philosophy requires engagement with historical texts and figures, the text describes doing philosophy as addressing “enduring questions about the nature of existence and knowledge,” which are abstract philosophical questions, not practical issues. Rather than formulating concrete solutions, doing philosophy involves the creative application of expertise to these broad, enduring questions. Choice C is incorrect because the text doesn’t characterize doing philosophy as requiring students to challenge past philosophers’ ideas. Instead, the text suggests that those who do philosophy engage creatively with historical figures, which can, but doesn’t necessarily entail, opposition. Additionally, the text doesn’t claim that the ideas of past philosophers are broadly accepted by those studying philosophy. Choice D is incorrect because the text doesn’t discuss norms of scholarly inquiry or characterize either approach in terms of conforming to or departing from such norms. Rather, the text notes that doing philosophy can occur “within or beyond the academy,” which suggests compatibility with scholarly settings rather than an inevitable departure from them.","is_grid_in":false},{"source_id":"8e22efd9","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Having demonstrated that the power conversion efficiency of new perovskite photovoltaic cells is nearly indistinguishable from that of cells recycled multiple times, Xun Xiao and colleagues evaluated the levelized cost of electricity (LCOE)—a measure of cost per produced electricity unit that incorporates materials acquisition costs as well as operating costs—for power plants utilizing each type of cell. With a modeled 15-year cell lifetime, the LCOE of plants using new cells was 4.99 cents per kilowatt-hour, whereas that of plants using cells recycled three times was 4.05 cents per kilowatt-hour. Moreover, the LCOE differential grew from 18.8% to 31.3% when the modeled cell lifetime was reduced by two-thirds.","passage_html":null,"question_text":"Based on the text, which choice, if true, most coherently and directly accounts for the observation presented in the underlined sentence?","question_text_html":null,"choices":[{"label":"A","text":"Cells can be recycled multiple times without a significant decrease in power conversion efficiency, and thus recycling cells more frequently does not change the LCOE for plants using recycled cells."},{"label":"B","text":"Although potentially less expensive than producing new cells, recycling cells does incur costs, and thus reducing cell lifetimes entails greater cumulative costs."},{"label":"C","text":"Securing new cell materials is more expensive than recycling cell materials, and thus more frequent cell replacement entails greater disparity in cumulative costs."},{"label":"D","text":"As the modeled cell lifetime decreases, plant operating costs increase, and thus the LCOE for plants using new cells diverges from that of plants using recycled cells."}],"correct_answer":"C","explanation":"Choice C is the best answer because it presents information that, if true, would coherently and directly account for the researchers’ observation about the LCOE differential between plants using new cells and plants using recycled cells. The text explains that the researchers found that the LCOE—a cost-per-unit electricity measure that includes the cost of acquiring the materials—is higher for plants using new cells than for plants using cells recycled three times, with the gap between them growing from 18.8% to 31.3% when the researchers reduced the modeled cell lifetime by two-thirds (that is, from 15 years to 5 years). If obtaining new cell materials were more expensive than recycling preexisting cell materials, then plants using new cells would incur greater materials costs than plants using recycled cells when cells need to be replaced, and the greater frequency of cell replacement entailed by a shorter cell lifetime would force plants using new cells to incur that greater cost more often—widening the gap between those plants and plants using recycled cells.\nChoice A is incorrect because the information that efficiencies are similar between new and recycled cells (which the text already establishes) and that frequency of recycling doesn’t affect the LCOE for plants using recycled cells wouldn’t address the effect of shorter cell lifetimes on the LCOE of plants using new cells. Information about that effect would be needed to account for the observation that the gap between the LCOEs for the two types of plants widens when cell lifetimes are shortened. Choice B is incorrect. Although the choice does point to the possibility of a scenario that could explain the growth in the LCOE differential (“potentially less expensive than producing new cells”), it presents that information as a concession (“although”) to its central assertion, which is that the cumulative costs would increase if cells had to be replaced more frequently than on the original 15-year timeline. This choice doesn’t indicate whether the increased cumulative costs in question are those of recycled-cell plants or both types of plants; either way, an increase in cumulative costs isn’t a coherent or direct explanation for why the difference in costs between new-cell plants and recycled-cell plants increases when the cell lifetime is reduced by two-thirds. A coherent and direct explanation for growth in the cost difference between the two types of plants must focus on a disparate effect on the plants’ costs; choice B, however, presents information that could be but is not necessarily relevant to a disparate effect and then doesn’t draw the relevant conclusion from it, instead drawing a conclusion about cumulative costs that doesn’t entail a growing differential. Choice D is incorrect because even if plant operating costs increase as cell lifetime decreases, that would be true for plants using new cells and for plants using recycled cells and thus wouldn’t be responsible for a divergence; therefore, the finding wouldn’t coherently and directly explain the observation that the gap between the LCOEs of the two types of plants widens as cell lifetimes are reduced.","is_grid_in":false},{"source_id":"09d942c6","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"A social species, chickens will cry out to one another in warning if they sense a hawk or other predator nearby. But if alone, a chicken will remain silent so as not to attract the predator’s attention. Sonja Hillemacher decided to use this behavior to determine whether individual chickens possess a capacity to recognize themselves visually when reflected in a mirror (a common standard for animal intelligence). In the first condition of her study, the subject could see its reflection, but no other chickens were present. In a second condition, another chicken was visible to the subject. Hillemacher presented an image of a hawk to the subject in both conditions, reasoning that if chickens lacked a capacity for visual self-recognition, then ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"neither study condition would elicit an audible response from the subject."},{"label":"B","text":"the subject likely would cry out a warning in both study conditions."},{"label":"C","text":"only the first study condition would elicit an audible response from the subject."},{"label":"D","text":"the subject would fail to distinguish its reflection from the image of the hawk."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of Hillemacher’s study of visual self-recognition in chickens. According to the text, when a predator is nearby, chickens cry out in warning if another chicken is present but remain silent if alone to avoid attracting the predator’s attention. The text explains that Hillemacher set up one condition in which a subject was alone and could see its reflection in a mirror and another condition in which the subject could see another chicken, and then presented an image of a hawk (a predator). It follows that if chickens aren’t capable of recognizing themselves visually in a mirror, the subject likely would cry out a warning in both conditions; in the first condition because it would perceive its reflection as another chicken—that is, it would think another chicken is present—and in the second condition because it would see that another chicken is actually present.\nChoice A is incorrect because the text suggests that regardless of chickens’ ability to visually recognize themselves in mirrors, the subject in the second condition would cry out a warning because another chicken is actually present. Further, if chickens do lack visual self-recognition, the subject in the first condition likely would also cry out because it would think its reflection is another chicken. Choice C is incorrect. The text does suggest that if chickens lack the ability to visually recognize themselves in mirrors, the subject would cry out a warning in the first condition because it would think its reflection is another chicken. However, the text also indicates that regardless of their capacity of self-recognition, chickens cry out a warning when other chickens are present, and another chicken is present in the second condition. Therefore, both conditions—not just the first one—likely would elicit an audible response from the subject. Choice D is incorrect because the text indicates that the study was focused on determining whether chickens recognize themselves visually in a mirror or instead perceive their reflections as other chickens; there’s no suggestion that a lack of self-recognition would cause a chicken to confuse its reflection with the image of a hawk.","is_grid_in":false},{"source_id":"411739db","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"medium","passage":"Readers sometimes divide the works of twentieth-century English author Evelyn Waugh into two periods: one consisting of his early satirical novels and the other consisting of his later, more serious—even ponderous—books. Critic Seamus Perry, however, challenges that strict division. Perry argues that Waugh’s writing didn’t change over time as much as some readers have suggested. For instance, Perry contends that some of Waugh’s earliest works, notably his biography of artist Dante Gabriel Rossetti, exhibit the earnest romanticism that would characterize Waugh’s later fiction.","passage_html":null,"question_text":"Based on the text, which statement about Waugh’s works would Perry most likely agree with?","question_text_html":null,"choices":[{"label":"A","text":"Waugh’s works can appropriately be separated into two periods by their subject matter and tone."},{"label":"B","text":"Regardless of when they were written, Waugh’s works have important similarities that transcend their differences."},{"label":"C","text":"The earliest of Waugh’s works exhibit a satirical tone, even if that tone is more apparent in Waugh’s later works."},{"label":"D","text":"Over time, Waugh’s works became less humorous and more focused on weightier topics."}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a statement that is consistent with Perry’s position as described in the text. The text explains that although Waugh’s works are sometimes divided into an early period typified by satirical novels and a later period consisting of “more serious” works, Perry “challenges that strict division” and argues that Waugh’s writing “didn’t change over time as much as some readers have suggested.” As evidence, Perry notes that Waugh’s biography of Dante Gabriel Rossetti and other early works show the “earnest romanticism” associated with Waugh’s later fiction, suggesting continuity across the two periods and also across genres. It is therefore likely that Perry would agree that Waugh’s works have important similarities that transcend their differences, regardless of when they were written.\nChoice A is incorrect because the text states that Perry challenges the “strict division” of Waugh’s works into two periods typified by their subject matter and tone. Perry therefore would likely disagree that such separation is appropriate; instead, he argues that Waugh’s writing shows more continuity across time than this division suggests. Choice C is incorrect because it mischaracterizes the similarity that Perry notes in Waugh’s earlier and later works. Perry contends that Waugh’s early works exhibit the “earnest romanticism” of his later fiction, not that the early works’ satirical tone appears more prominently later. Although the text mentions that Waugh’s earlier works are often satirical, Perry’s argument doesn’t emphasize this trait or trace its development over time. Choice D is incorrect because it reflects the periodization of Waugh’s works that Perry is challenging. The text indicates that Perry argues against the idea that Waugh’s writing changed dramatically over the course of his career, and Perry specifically emphasizes a point of similarity between Waugh’s earlier and later works. Given this stance, it’s unlikely that Perry would agree that Waugh’s works became less humorous and more serious over time.","is_grid_in":false},{"source_id":"c5cba39c","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"In episodes of high heat, corals expel symbiotic zooxanthellae from their tissues, leading to coral bleaching and heightened coral mortality. Some researchers have proposed a mitigation strategy of identifying, rearing, and disseminating corals that have evolved strong resistance to heat, but as Nia S. Walker et al. note, if genes conferring such resistance were exclusively advantageous, they should have already propagated through coral populations. Indeed, Walker et al. show that strongly heat-resistant corals display much less growth after heat stress than do moderately heat-resistant corals.","passage_html":null,"question_text":"Based on the text, Walker et al. would most likely agree with which statement about the strategy some researchers have proposed?","question_text_html":null,"choices":[{"label":"A","text":"It would involve promoting a trait that protects corals against high heat but that is associated with reduced thriving after episodes of high heat."},{"label":"B","text":"It would favor a trait that is advantageous now but would be disadvantageous if episodes of high heat become as infrequent as has been predicted."},{"label":"C","text":"It would benefit corals that are frequently exposed to episodes of high heat but would harm corals that are frequently exposed to episodes of moderate heat."},{"label":"D","text":"It would require manipulating a trait that is poorly understood and that may be linked to increased coral mortality during episodes of high heat."}],"correct_answer":"A","explanation":"Choice A is the best answer because it presents a statement about the proposed strategy that is consistent with Walker et al.’s position. The strategy involves identifying and disseminating corals with strong heat resistance as a means of mitigating coral mortality during episodes of high heat. According to the text, Walker et al. note that if this trait were “exclusively advantageous,” it would have already spread throughout coral populations—implying that the trait carries some evolutionary cost. The text then provides evidence of this cost: Walker et al. have found that strongly heat-resistant corals display much less growth after heat stress (indicative of reduced thriving) than do moderately heat-resistant corals. Given the apparent trade-off between strong heat resistance and growth after heat stress, Walker et al. would be likely to agree that the strategy entails promoting a trait that protects against high heat but is associated with reduced thriving afterward.\nChoice B is incorrect because the text doesn’t suggest that episodes of high heat are predicted to become infrequent. Also, the text establishes that Walker et al. found that the trait of high heat tolerance is associated with a significant trade-off—reduced growth after heat stress. Given the cost that accompanies strong heat resistance, Walker et al. wouldn’t be likely to agree that the trait is advantageous now. Choice C is incorrect because the text doesn’t discuss the effects of moderate heat on corals or distinguish between corals that are exposed to different levels of heat. The text also doesn’t address the frequency of corals’ exposure to heat. Therefore, there is no basis for concluding that Walker et al. would agree that the strategy benefits corals that are frequently exposed to high heat but harms those that are frequently exposed to moderate heat. Choice D is incorrect because the text doesn’t indicate that heat resistance in corals is poorly understood. On the contrary, Walker et al. present a specific finding about this trait, linking reduced growth after heat stress to strong heat resistance. In addition, the text indicates that strong heat resistance protects corals during episodes of high heat; while their research shows that heat resistance is linked to reduced growth after such episodes, Walker et al. likely wouldn’t agree that it is linked to increased coral mortality during such episodes.","is_grid_in":false},{"source_id":"5bcee487","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"medium","passage":"Pablo Picasso famously subverted the norms of traditional painting: in his cubist paintings he refused to let his expression be constrained, fragmenting objects and figures to present multiple perspectives simultaneously. Though less widely known, Picasso—who once lamented that writers of his time had “limited themselves to moving around words somewhat while respecting the syntax”—also wrote poetry that defied conventional grammar, semantic relationships, and text structure. Thus, the paintings and poems are linked in that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"the poems present many of the same subjects as the paintings but with different thematic approaches."},{"label":"B","text":"the poems are intended to be understood as explanations of the artistic inclinations reflected in the paintings."},{"label":"C","text":"both types of work are characterized by the simultaneous representation of multiple points of view that Picasso is known for."},{"label":"D","text":"both exhibit Picasso’s prioritization of creative expression over the standard rules of the art forms."}],"correct_answer":"D","explanation":"Choice D is the best answer because it most logically completes the text’s discussion of the link between Picasso’s cubist paintings and his poetry. The text states that Picasso subverted, or intentionally went against, the norms of traditional painting; rather than following conventional rules about how paintings should look, he fragmented objects and figures to present multiple perspectives at the same time. The text explains that similarly, Picasso wrote poetry that defied conventions of grammar, semantics, and structure. Because Picasso subverted the conventions of both painting and written language in favor of unconstrained expression, it is reasonable to conclude that his paintings and poems are linked by their demonstration of his prioritization of creative expression over the standard rules of the art forms.\nChoice A is incorrect because the text doesn’t give any information about the subjects or themes of either Picasso’s paintings or his poems; it indicates only that Picasso didn’t adhere to the norms of either art form. Choice B is incorrect. Although the text explains that the forms of Picasso’s paintings and his poems demonstrate his inclination to not be constrained by convention, it doesn’t discuss any of the ideas expressed in his poems; there’s no indication that Picasso intended his poems to be understood as explanations of anything reflected in his paintings. Choice C is incorrect. The text mentions the simultaneous representation of multiple points of view as a characteristic of Picasso’s cubist paintings but doesn’t indicate that his poems had the same characteristic; the text doesn’t address perspective in Picasso’s poems at all.","is_grid_in":false},{"source_id":"5f16d809","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"In classical Greek and Roman mythology, female characters are typically cast as either villains lacking in psychological depth or passive victims who are marginal to these stories, which usually focus on the exploits of male characters. Recently, a subgenre has emerged in which writers reimagine these stories from the perspectives of their female characters, giving them agency and complex motivations. Purists argue that such efforts represent a distinctively modern tendency to impose our own values on past civilizations, obscuring those civilizations’ beliefs. Defenders of the subgenre counter that reimaginings of the myths for new cultural contexts are almost as old as the myths themselves, suggesting that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"bringing female perspectives to the forefront is not indicative of a novel attitude regarding fidelity to Greek and Roman myths’ ideologies."},{"label":"B","text":"modern writers’ foregrounding of female characters is chiefly motivated by a desire to counterbalance the primacy of male perspectives among earlier adaptations of Greek and Roman myths."},{"label":"C","text":"purists are overlooking a long tradition of adapting Greek and Roman myths to focus on female characters."},{"label":"D","text":"the complex motivations given to female characters in modern retellings of Greek and Roman myths reflect a recent shift toward psychological depth in fictional representation."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of a literary subgenre that reimagines Greek and Roman myths in a more modern cultural context—namely, the greater visibility and psychological depth of female characters. According to the text, purists object that this subgenre imposes modern values on past civilizations, while the subgenre’s defenders argue that reimagining old myths for new cultural contexts is “almost as old as the myths themselves.” If this argument in defense of the subgenre is accurate, then bringing female perspectives to the forefront of myth is reflective of a long-established attitude regarding writers’ freedom to recontextualize the ideologies of Greek and Roman myths instead of remaining absolutely faithful to them.\nChoice B is incorrect because the text suggests that modern writers who foreground female characters in their adaptations of Greek and Roman myths are motivated by a desire to counterbalance the primacy of male perspectives in the myths themselves, not in earlier adaptations of those myths. The text doesn’t indicate that the modern writers are responding to earlier adaptations and only discusses those adaptations in the context of the argument that recontextualizing Greek and Roman myths is a very old practice. Choice C is incorrect because the defenders’ claim concerns the general practice of reimagining myths for new cultural contexts, not specifically a tradition of focusing on female characters. The text doesn’t indicate that earlier reimaginings centered on female characters, so it wouldn’t be logical to conclude that purists are overlooking a long tradition of adapting myths to focus on female characters specifically. Choice D is incorrect. While the text supports the claim that the modern retellings of Greek and Roman myths have given complex motivations to the female characters, it doesn’t associate this development with a trend toward the portrayal of greater psychological depth in fiction more broadly or claim that such a trend exists. Moreover, the claim that there is an association wouldn’t follow logically from the last sentence of the text, which asserts that reimagining myths in new cultural contexts is an established practice.","is_grid_in":false},{"source_id":"7bdf094b","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"Sir Gawain and the Green Knight is a circa 1400 poem written in Middle English—an archaic form of the English spoken today. Over the last several centuries, the English language has undergone such transformations in vocabulary, spelling, and grammar that most readers now rely on translations to read Sir Gawain. In the introduction to his 2007 translation, Simon Armitage remarks that the sonic patterns of the poem, which was written in alliterative verse (a verse form featuring extensive repetition of initial consonant sounds), are essential to its structure. Because many Modern English words begin with different sounds than their Middle English equivalents do, a strictly literal translation of Sir Gawain would therefore likely ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"preserve much of the original text’s meaning at the expense of other qualities that are also integral to the experience of reading the poem."},{"label":"B","text":"appeal more to modern readers than would translations like Armitage’s that instead prioritize the original text’s sonic and structural qualities."},{"label":"C","text":"be more faithful to the original intentions of the poem than most strictly literal translations of alliterative Middle English poems are to their originals."},{"label":"D","text":"be preferable to modern readers who are primarily interested in learning what the poem reveals about historical conditions during the time it was originally written."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of translating Sir Gawain and the Green Knight. The text states that the poem was written in alliterative verse, a form that features extensive repetition of initial consonant sounds, and that, according to Armitage, the patterns of sound in the poem are essential to the poem’s structure. The text also notes that many Modern English words begin with different sounds than their Middle English equivalents (that is, the words with the same meanings) do. This means that if a translator were to render the poem’s Middle English words into their direct Modern English equivalents, the initial consonant sounds of many words would change and the original alliterative patterns wouldn’t hold. It follows, then, that a strictly literal (word for word) translation would preserve much of the original text’s meaning at the expense of sonic and structural qualities that are also integral to the experience of reading the poem.\nChoice B is incorrect because the text doesn’t address modern readers’ preferences among translation approaches. Although the text implies that Armitage may have prioritized the sonic patterns and structure of the original poem in his translation, it doesn’t give any indication that this approach would be less appealing to modern readers than an approach that directly translates the words but loses the original patterns of sounds in the poem. Choice C is incorrect. The text actually suggests that a strictly literal Modern English translation of Sir Gawain and the Green Knight wouldn’t be especially faithful to the original intentions of the poem because the Modern English words would change the sonic patterns Armitage notes are essential to the alliterative poem’s structure—that is, such a translation would change patterns of sound that are a fundamental part of the original poem’s composition. Moreover, there’s no reason to think that a strictly literal translation of that poem would be more faithful to the original intentions than literal translations of other alliterative Middle English poems would be, since they would presumably all face the issue of a change in the patterns of sounds. Choice D is incorrect because the end of the text makes a point about sounds, not meaning. Modern readers interested in gathering historical information from the poem might prefer a strictly literal translation (one that directly translates the words without making additional changes), but that idea doesn’t logically follow from the fact that many Modern English words start with different sounds than their Middle English counterparts; a change in the sounds wouldn’t have any effect on the information the poem conveys.","is_grid_in":false},{"source_id":"8d88740e","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"The following text is adapted from William Shakespeare’s 1597 play The Tragedy of King Richard III. Richard is reflecting on the recent arrest of his brother, the Duke of Clarence, on suspicion of treason against King Edward IV. Derby, Hastings, Buckingham, Rivers, Dorset, and Grey are also members of the English nobility.\nRICHARD: I do the wrong, and first begin to brawl.\nThe secret mischiefs that I set [flowing]\nI lay unto the grievous charge of others.\nClarence, whom I indeed have cast in darkness,\nI do beweep to many simple [gullible people],\nNamely, to Derby, Hastings, Buckingham;\nAnd tell them ’tis the Queen and her allies\nThat stir the King against the Duke my brother.\nNow they believe it, and withal whet me\nTo be revenged on Rivers, Dorset, Grey.","passage_html":null,"question_text":"Which choice best describes what happens in the text?","question_text_html":null,"choices":[{"label":"A","text":"Richard describes having wept as he informed Derby, Hastings, and Buckingham that the queen and her allies convinced the king to act against Clarence, and says that the earnestness of his grief caused them to accept his version of events."},{"label":"B","text":"Richard attributes Clarence’s troubles to both his own secret plotting and the distrust of Clarence that the queen and her allies Derby, Hastings, and Buckingham have planted in the king’s mind."},{"label":"C","text":"Richard indicates that he has pretended to be aggrieved about Clarence’s situation and has proclaimed it to be the fault of the queen and her allies, but in reality, he has caused the hostility the king feels toward Clarence."},{"label":"D","text":"Richard acknowledges that his mischievous nature has spurred him to commit misdeeds in the past, including instigating enmity between the king and Clarence, but he reports that he has hitherto not lost the trust of the queen and her allies."}],"correct_answer":"C","explanation":"Choice C is the best answer because it accurately describes what happens in the text. Richard admits he committed “the wrong” and blames others for his own “secret mischiefs.” He reveals that he has “cast [Clarence] in darkness” (that is, caused his imprisonment) but feigns grief—“I do beweep”—before “many simple [gullible people],” namely Derby, Hastings, and Buckingham. He tells them that the queen and her allies are the ones who turned the king against Clarence. Richard’s use of “beweep” and his labeling of his audience as gullible confirm that his grief is a performance. Thus, Richard pretends to be aggrieved and blames the queen while actually being responsible for Clarence’s predicament.\nChoice A is incorrect because it characterizes Richard’s grief as earnest, claiming that his sincere grief moved others to accept his claims. However, Richard admits his wrongdoing and calls his audience “simple [gullible people],” making clear that they were deceived by a calculated performance rather than persuaded by genuine emotion. Rather than being sincere, Richard’s weeping is part of a deliberate scheme to blame the queen and her allies for what he did. Choice B is incorrect because Richard does not attribute any portion of Clarence’s troubles to the queen; he reveals that he “cast [Clarence] in darkness” and merely tells others the queen is responsible. Additionally, Derby, Hastings, and Buckingham are not identified as the queen’s allies; rather, Rivers, Dorset, and Grey are implied to be the queen’s allies. Choice D is incorrect because the text does not address whether Richard has maintained the trust of the queen and her allies. Instead, Richard tells Derby, Hastings, and Buckingham that the queen is to blame for Clarence’s troubles, and they in turn urge him to seek revenge on Rivers, Dorset, and Grey, who are implied to be the queen’s allies. The speech focuses on Richard’s manipulation of others, not on his standing with the queen.","is_grid_in":false},{"source_id":"db57afa3","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"Whistler waves are low-frequency plasma waves that on Earth are typically generated by lightning. Numerous recordings of whistler waves on Venus have led many scientists to suggest that the planet’s atmosphere is host to extensive amounts of lightning, and, in fact, Venusian whistler waves have similar energy signatures to those of whistler waves generated by lightning on Earth. The majority of Venusian whistler wave data come from two spacecraft missions—the Pioneer Venus Orbiter (PVO) and the Venus Express (VEX)—which have included few observations of other phenomena consistent with lightning occurrences (such as flashes of light), leading other scientists to suggest that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"similarities in the energy signatures of Venusian and Earth whistler waves may reflect imprecisions in the PVO and VEX data."},{"label":"B","text":"the purported Venusian whistler waves must actually be some other type of atmospheric activity than whistler waves."},{"label":"C","text":"Venusian lightning has properties that make it unlikely to generate whistler waves."},{"label":"D","text":"there are geophysical characteristics of Venus not shared with Earth that promote the generation of whistler waves."}],"correct_answer":"D","explanation":"Choice D is the best answer because it most logically completes the text’s discussion of whistler waves on Venus and the question of their origin. The text explains that whistler waves are plasma waves and that on Earth they are generated by lightning. The text goes on to state that numerous recordings of whistler waves on Venus have led many scientists to suggest Venus hosts lightning. However, the text goes on to explain that data from the PVO and VEX missions have included little evidence of the other phenomena that would be expected if lightning were occurring in Venus’s atmosphere. Because there is a lack of additional evidence of lightning, it is reasonable to conclude that some scientists would be skeptical that lightning is the source of the whistler waves on Venus and would suggest unique geophysical characteristics of Venus as an alternative explanation for the waves’ generation.\nChoice A is incorrect because the text indicates that the other scientists are responding to the PVO and VEX data simply not showing additional evidence of lightning on Venus, not to flaws in the data. The text presents the similar energy signatures of Venusian and Earth whistler waves as an established observation and doesn’t suggest the PVO and VEX data are imprecise. Choice B is incorrect because the text presents the similar energy signatures of Venusian and Earth whistler waves as an established observation. The text indicates that the other scientists are concerned with the lack of corroborating evidence of lightning on Venus, suggesting not that they doubt that the waves are whistler waves but rather that they doubt that the waves are generated by lightning. Choice C is incorrect because the text indicates that the other scientists are responding to the data providing little corroborating evidence of lightning on Venus. This suggests that instead of making a suggestion about properties of Venusian lightning, the other scientists likely would suggest that there may not even be lightning on Venus.","is_grid_in":false},{"source_id":"8209f485","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"Across brown bears—omnivores with high dietary plasticity—there is wide variety in dietary mix, which may reflect genetics, local resource availability, or social learning (cubs stay with their mothers for two years or more). Evaluating these possibilities, Anne Hertel et al. analyzed 30 years of data on trophic position (indicative of dietary mix) for female brown bears. After separation, daughters, who tended to settle near their mothers, occupied the same trophic positions as their mothers for two years, but the correlation disappeared by year five. Trophic correlation with unrelated individuals in similar habitats was modest, while habitat-independent correlation with nonmaternal relatives (e.g., cousins) was no different than with unrelated individuals. These findings suggest that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"growing dissimilarity between mothers and their daughters with regard to dietary mix may reflect changes in the resources available in maternal habitats, though social learning could also contribute to the trend."},{"label":"B","text":"dietary mix among females may reflect a social learning effect that eventually diminishes, though environmental constraints cannot be ruled out as a contributing factor."},{"label":"C","text":"female dietary mix is best understood as changeable and contingent on fluctuating environmental conditions rather than as the result of social learning or genetic factors."},{"label":"D","text":"social learning and resource fluctuations may both play a role in dietary mix among females, at least temporarily, though genetic factors appear to make a significant contribution as well."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of Hertel et al.’s study of dietary mix variation among female brown bears. According to the text, the researchers evaluated genetics, local resource availability, and social learning as factors in female brown bears’ trophic position, or position in the food web. According to the text, daughters tended to settle near their mothers after separating and held the same trophic positions as the mothers for two years, but no longer did by the fifth year—a temporary similarity that may reflect a socially learned behavior that faded over time after separation. Additionally, the text states that the degree of similarity in trophic position between nonmaternal relatives (e.g., cousins) was the same as that between unrelated individuals, suggesting that genetics don’t significantly influence dietary mix, and the text also states that there was modest similarity in the trophic positions of unrelated individuals in similar habitats, suggesting that environmental conditions (which would include resource availability) may have some influence on dietary mix. Taken together, the findings suggest that while environmental constraints can’t be ruled out as a contributing factor, dietary mix among female brown bears may reflect a social learning effect that eventually diminishes.\nChoice A is incorrect because the text notes that daughters tended to settle near their mothers after separating—that is, that they often didn’t leave the maternal habitat. Therefore, changes in resource availability in the mothers’ habitats would likely have affected the daughters similarly instead of causing their dietary mix to differ from that of their mothers. Further, the form of social learning addressed by the text is that between mothers and daughters; although the daughters no longer held the same trophic position as their mothers five years after separating from them, the text doesn’t address the possibility that the daughters’ divergence from the dietary behaviors of their mothers is the result of learning from other bears or suggest that the daughters even interacted with other adult bears in a substantive way. Choice C is incorrect. Instead of suggesting that environmental conditions are the most important factor in dietary mix variation and that social learning isn’t a factor, the findings discussed in the text suggest that environmental conditions may have some effect (since there was modest similarity in dietary mix between unrelated bears in similar habitats, or similar environmental conditions) and that social learning may be a factor (since daughters held the same trophic positions as their mothers for two years after separating but not for five years, which may reflect daughters maintaining dietary behaviors they learned from their mothers but changing their behaviors over time). Choice D is incorrect because the findings presented in the text argue against, not for, genetics as a significant factor in variation in dietary mix. The text indicates that independent of their habitats, the degree of similarity in dietary mix between nonmaternal relatives, like cousins, was the same as that between unrelated individuals. This means that genetic relatedness didn’t have a detectable effect on dietary mix independent of shared habitat.","is_grid_in":false},{"source_id":"e65dfc41","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"medium","passage":"Given the immense scope of space, the search for extraterrestrial life is almost necessarily concentrated on the exoplanets deemed to have the most plausible chance of success—typically, atmosphere-bearing terrestrial planets orbiting within a certain range of their stars (termed the habitable zone). Claiming that Earth experienced a long transition from single-lid to plate tectonics that accelerated the emergence and evolution of complex organisms, researchers Robert J. Stern and Taras V. Gerya hold that consideration of tectonics, an often overlooked factor, could help further narrow the search for advanced extraterrestrial species.","passage_html":null,"question_text":"Based on the text, what do Stern and Gerya most likely believe about the development of complex life on exoplanets?","question_text_html":null,"choices":[{"label":"A","text":"It is more likely to occur on habitable zone planets with atmospheres and plate tectonics than on otherwise similar planets that lack plate tectonics."},{"label":"B","text":"It is more likely to occur if habitable zone planets with atmospheres transition from single-lid to plate tectonics late in their history than if they transition early in their history."},{"label":"C","text":"It is unlikely unless the transition from single-lid to plate tectonics occurs before the acquisition of a lasting atmosphere."},{"label":"D","text":"It is probably more dependent on the presence of plate tectonics than on orbital distance from a host star or the presence of an atmosphere."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most accurately describes what Stern and Gerya most likely believe about the development of complex life on exoplanets. The text indicates that the search for extraterrestrial life already focuses on atmosphere-bearing planets in the habitable zone because their conditions are best suited for complex organisms. Stern and Gerya claim that plate tectonics on Earth accelerated the emergence of complex organisms, and they therefore hold that tectonics could “help further narrow the search.” This phrase implies that plate tectonics should be added to the existing criteria. In other words, the text implies that among habitable zone planets with atmospheres, those that also have plate tectonics would be more likely to enable the development of complex life than otherwise similar planets lacking plate tectonics.\nChoice B is incorrect because the text doesn’t address whether the timing of the transition to plate tectonics—early versus late in a planet’s history—affects the likelihood of complex life. Although the text mentions that plate tectonics emerged on Earth after a “long transition” and that this process accelerated the development of complex life, it presents these details as context for why plate tectonics matter, not as a claim about when the transition would have needed to occur within the planet’s history. Choice C is incorrect because the text doesn’t discuss the timing of the acquisition of an atmosphere in relation to that of the transition to plate tectonics or explain why this would be relevant to the development of complex life. Rather, the text presents these as independent factors relevant to the search for extraterrestrial life. Choice D is incorrect because the text presents plate tectonics as an additional factor to consider alongside orbital distance from a host star and atmosphere, not as a more important one. Stern and Gerya propose that tectonics could “help further narrow the search,” which implies supplementing, rather than superseding, the existing criteria.","is_grid_in":false},{"source_id":"8c39592a","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"The following text is adapted from William Shakespeare’s 1598 play Henry IV, Part 1. King Henry is addressing several noblemen who are rumored to have been disloyal to him.\nKING HENRY: My blood hath been too cold and temperate,\nUnapt to stir at these indignities,\nAnd you have found me, for accordingly\nYou tread upon my patience; but be sure\nI will from henceforth rather be myself,\nMighty and to be fear’d, than my [disposition],\nWhich hath been smooth as oil, soft as young down,\nAnd therefore lost that title of respect\nWhich the proud soul ne’er pays but to the proud.","passage_html":null,"question_text":"Which statement best describes how King Henry presents himself in the text?","question_text_html":null,"choices":[{"label":"A","text":"He declares that he has judged the noblemen’s conduct in an impartial manner, and that despite their attempts to regain his trust through professions of submissiveness, they have irrevocably lost his respect."},{"label":"B","text":"He acknowledges to the noblemen that his tolerance of their conduct has undermined their respect for him, and he resolves to display his genuine nature, which is more forceful and compels deference."},{"label":"C","text":"He defends his calm disposition, which he sees as fundamental to his personality, and vows to maintain his tranquil demeanor even if it causes him to lose the respect of overly proud noblemen."},{"label":"D","text":"He concedes that he has treated the noblemen with indifference, which in part explains why they have defied him, but he asserts that their disrespectful behavior is primarily driven by their excessive pride."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most accurately describes King Henry’s self-presentation in the text. Henry states that his temperament has been “too cold and temperate, / Unapt to stir at these indignities” (that is, too calm and slow to react to insults), and he asserts that the noblemen have taken advantage of this: “accordingly / You tread upon my patience.” He then resolves to change, declaring he will “from henceforth rather be myself, / Mighty and to be fear’d,” since being lenient (“smooth as oil, soft as young down”) has caused him to lose “that title of respect / Which the proud soul ne’er pays but to the proud.” In other words, Henry recognizes that proud people like the noblemen respect only strength and resolves to show his more forceful, true nature.\nChoice A is incorrect because the text doesn’t describe Henry as having judged the noblemen impartially, nor does it mention any attempts by the noblemen to regain his trust through submissiveness. Rather, Henry describes the noblemen as taking advantage of his patience and declares he will adopt a more commanding demeanor in the future. Choice C is incorrect. Although Henry concedes that he has perhaps been too calm and mild, Henry does not defend or vow to maintain his calm disposition. On the contrary, he explicitly states he will “from henceforth rather be myself, / Mighty and to be fear’d,” resolving to abandon the mild manner that has cost him the respect of the noblemen. Choice D is incorrect because Henry characterizes his manner as patient and mild—“smooth as oil, soft as young down”—not indifferent. Indifference implies a lack of concern, whereas Henry describes himself as being overly lenient. Additionally, although the final lines mention “the proud soul,” the focus is not on the noblemen’s excessive pride but rather on how Henry’s apparent lack of pride has caused him to lose the noblemen’s respect.","is_grid_in":false},{"source_id":"10455a19","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"medium","passage":"In the early 1970s, art historian Michael Baxandall created an approach to viewing art called the “period eye,” which explains how to look at art through the lens of its historical period. Baxandall argued that it is critical that art historians understand and communicate the original social and cultural contexts of older works of art so that it is clear what the artists intended and how the pieces would have been understood by their original viewers. Since it was first introduced, Baxandall’s period eye has significantly influenced the practice of art history.","passage_html":null,"question_text":"Which statement, if true, would most strongly support the claim in the underlined sentence?","question_text_html":null,"choices":[{"label":"A","text":"Art historians working today have largely rejected the idea, common among Baxandall’s predecessors, that artists’ intentions should influence how artworks are interpreted."},{"label":"B","text":"For some historical periods, it is difficult for art historians to reconstruct how the original viewers of artworks understood what artists’ intentions for their works were."},{"label":"C","text":"Numerous art historians of the late twentieth century and twenty-first century have focused their scholarship on how various artworks were interpreted at the time of their creation."},{"label":"D","text":"Many art historians working before the 1970s produced detailed analyses of the social and cultural contexts of older artworks, though few extended that approach to artworks produced in their own lifetimes."}],"correct_answer":"C","explanation":"Choice C is the best answer because it presents a statement that, if true, would most strongly support the underlined claim that Baxandall’s period eye has significantly influenced the practice of art history since its introduction. The text explains that the period eye—an approach Baxandall introduced in the early 1970s—directs art historians to understand how artworks were originally understood by viewers from the same historical period in which the works were created. If numerous art historians working in the late twentieth and twenty-first centuries—that is, in the decades after Baxandall’s introduction of the approach—have focused on how artworks were interpreted at the time of their creation, their scholarship would correspond to the definition of period eye provided by the text, thereby supporting the claim that the period eye has been significantly influential.\nChoice A is incorrect because, as the text explains, Baxandall explicitly recommended examining the social and cultural contexts in which older artworks were produced in order to appreciate the artists’ intentions. Thus, a widespread rejection of artistic intention as an interpretive guide would weaken, not support, the claim that Baxandall influenced the practice of art history. Choice B is incorrect because this statement considers a limitation in applying the period eye approach—namely, the difficulty of reconstructing original viewers’ understanding for some historical periods—instead of addressing whether the approach has influenced the practice of art history. Choice D is incorrect because the statement describes the practice of art historians working before the 1970s, prior to Baxandall’s introduction of the period eye. Pre-1970s scholarship cannot demonstrate Baxandall’s influence on art history; if anything, it would suggest that some elements of his approach predated him, which has no bearing on whether his particular formulation has shaped the field since.","is_grid_in":false},{"source_id":"4ef17800","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Richard II is a play from the 1590s by William Shakespeare. Although King Richard has been vanquished by his cousin Henry Bolingbroke, he intimates that he is not entirely ready to show subservience to his cousin, saying, ______","passage_html":null,"question_text":"Which quotation from Richard II most effectively illustrates the claim?","question_text_html":null,"choices":[{"label":"A","text":"“I have no name, no title,— / No, not that name was given me at the font,— / But ’tis usurp’d:— Alack the heavy day, / That I have worn so many winters out, / And know not now what name to call myself!”"},{"label":"B","text":"“Alack, why am I sent for to a king, / Before I have shook off the regal thoughts / Wherewith I reign’d? I hardly yet have learn’d / To insinuate, flatter, bow, and bend my knee.”"},{"label":"C","text":"“Still my griefs are mine. / You may my glories and my state depose, / But not my griefs; still am I king of those.”"},{"label":"D","text":"“Am I both priest and clerk? Well then, amen. / God save the King! although I be not he; / And yet, amen, if heaven do think him me.”"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most effectively presents a quotation that illustrates the claim that Richard intimates he is not entirely ready to show subservience to Bolingbroke. The quotation conveys that Richard has not yet shaken off “the regal thoughts / Wherewith [he] reign’d”—that is, he still feels like a king—and that he has “hardly yet have learn’d / To insinuate, flatter, bow, and bend [his] knee,” directly listing acts of subservience he is not prepared to perform. By stating his unreadiness to behave subserviently while still inhabiting a regal mindset, Richard intimates exactly what the claim describes.\nChoice A is incorrect because this quotation centers on Richard’s anguish over the loss of his name and title; it expresses confusion about his identity rather than illustrating that he is not yet prepared to show subservience to Bolingbroke. Choice C is incorrect because in this quotation Richard claims that his griefs remain his own even after his “glories” and “state” have been deposed; it concerns ownership of his suffering and identity rather than any unreadiness to behave subserviently toward Bolingbroke. Choice D is incorrect because the quotation depicts Richard as willing to go along with the assertion of others that Bolingbroke is the rightful king, although God, who in this case serves as an objective arbiter, may have a different opinion on who the rightful king is (“if heaven do think him me”). So the quotation suggests that Richard is willing to behave subserviently even if he thinks he has been wronged; it does not suggest that he is at present unwilling to show subservience.","is_grid_in":false},{"source_id":"0992bd73","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"easy","passage":"Bar graph titled Percent of UK Survey Respondents Who Trust People At Least Somewhat. The horizontal axis is labeled Year of study. 3 data categories are shown. The vertical axis is labeled Respondents’ ratings, in percent. It ranges from 0 to 100 in increments of 20. Refer to long description.\nSocial scientists distinguish two different categories of social trust: bonding trust and bridging trust. Bonding trust refers to trust within already existing relationships (e.g., within a family), whereas bridging trust refers to trust between different groups, often involving interactions beyond one’s immediate social circle (e.g., meeting someone at a networking event). In order to evaluate these two aspects of social trust in the United Kingdom, researchers asked participants in 2005, 2018, and 2022 to rate the level of trust they felt for people they know personally and for people they are meeting for the first time. After analyzing the data from the survey responses, the researchers concluded that the level of bonding trust in the UK ______","passage_html":"<p><figure><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"400\" height=\"424.84\" viewBox=\"0 0 400 424.84\" role=\"img\" aria-label=\"Bar graph titled Percent of UK Survey Respondents Who Trust People At Least Somewhat. The horizontal axis is labeled Year of study. 3 data categories are shown. The vertical axis is labeled Respondents’ ratings, in percent. It ranges from 0 to 100 in increments of 20. Refer to long description.\"><g id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\"><defs><pattern id=\"bar4\" x=\"0\" y=\"0\" width=\"10\" height=\"100\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(50)\"><rect x=\"0\" y=\"0\" width=\"5\" height=\"100\" fill=\"#CDCDCD\"/><rect x=\"5\" y=\"0\" width=\"5\" height=\"100\" fill=\"#444444\"/></pattern></defs><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"87.328125\" y1=\"72\" x2=\"385\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"81.328125\" y1=\"72\" x2=\"93.328125\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(75.328125 78)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">100</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"87.328125\" y1=\"112\" x2=\"385\" y2=\"112\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"81.328125\" y1=\"112\" x2=\"93.328125\" y2=\"112\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(75.328125 118)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">80</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"87.328125\" y1=\"152\" x2=\"385\" y2=\"152\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"81.328125\" y1=\"152\" x2=\"93.328125\" y2=\"152\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(75.328125 158)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">60</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"87.328125\" y1=\"192\" x2=\"385\" y2=\"192\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"81.328125\" y1=\"192\" x2=\"93.328125\" y2=\"192\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(75.328125 198)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">40</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"87.328125\" y1=\"232\" x2=\"385\" y2=\"232\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"81.328125\" y1=\"232\" x2=\"93.328125\" y2=\"232\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(75.328125 238)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">20</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"87.328125\" y1=\"272\" x2=\"385\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"81.328125\" y1=\"272\" x2=\"93.328125\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(75.328125 278)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Respondents’ ratings (%)</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"87.328125\" y1=\"72\" x2=\"87.328125\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"117.0953125\" y=\"180\" height=\"92\" width=\"29.7671875\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"146.8625\" y=\"80\" height=\"192\" width=\"29.7671875\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(146.8625 291.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2005</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"206.39687500000002\" y=\"162\" height=\"110\" width=\"29.7671875\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"236.16406250000003\" y=\"78\" height=\"194\" width=\"29.7671875\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(236.16406250000003 291.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2018</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"295.6984375\" y=\"166\" height=\"106\" width=\"29.7671875\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"325.465625\" y=\"78\" height=\"194\" width=\"29.7671875\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(325.465625 291.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2022</text><text text-anchor=\"middle\" transform=\"translate(236.1640625 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Percent of UK Survey Respondents</text><text text-anchor=\"middle\" transform=\"translate(236.1640625 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Who Trust People At Least Somewhat</text><text text-anchor=\"middle\" transform=\"translate(236.1640625 325.67999999999995)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Year of study</text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"102.09008026123047\" y=\"342.84000000000003\" height=\"71\" width=\"210.81983947753906\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"109.09008026123047\" y=\"354.84000000000003\" height=\"12\" width=\"12\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(131.09008026123047 366.84000000000003)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> meet for the first time</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"109.09008026123047\" y=\"386.84000000000003\" height=\"12\" width=\"12\" fill=\"#333333\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(131.09008026123047 398.84000000000003)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> know personally</text></g></svg><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for bar graph titled Percent of UK Survey Respondents Who Trust People At Least Somewhat\"><ul><li>For each data category, the following bars are shown:<br/><ul><li>meet for the first time</li><li>know personally</li></ul></li><li>The Respondents’ ratings data for the 3 categories are as follows:<br/><ul><li>2005:<br/><ul><li>meet for the first time: 46%</li><li>know personally: 96%</li></ul></li><li>2018: <br/><ul><li>meet for the first time: 55%</li><li>know personally: 97%</li></ul></li><li>2022: <br/><ul><li>meet for the first time: 53%</li><li>know personally: 97%</li></ul></li></ul></li></ul></div></figure></p><p>Social scientists distinguish two different categories of social trust: bonding trust and bridging trust. Bonding trust refers to trust within already existing relationships (e.g., within a family), whereas bridging trust refers to trust between different groups, often involving interactions beyond one’s immediate social circle (e.g., meeting someone at a networking event). In order to evaluate these two aspects of social trust in the United Kingdom, researchers asked participants in 2005, 2018, and 2022 to rate the level of trust they felt for people they know personally and for people they are meeting for the first time. After analyzing the data from the survey responses, the researchers concluded that the level of bonding trust in the UK <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","question_text":"Which choice most effectively uses data from the graph to complete the statement?","question_text_html":null,"choices":[{"label":"A","text":"remained largely consistent from 2005 to 2022, whereas the level of bridging trust showed more variability from 2005 to 2022."},{"label":"B","text":"consistently grew from 2005 to 2022, whereas the level of bridging trust largely declined from 2005 to 2022."},{"label":"C","text":"was the same in 2018 as it was in 2022 but remained lower than the level of bridging trust in 2018 and 2022."},{"label":"D","text":"declined from 2005 to 2022 but remained higher than the level of bridging trust from 2005 to 2018."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most effectively uses data from the graph to complete the statement about the level of bonding trust in the UK. The text defines bonding trust as trust within already existing relationships and bridging trust as trust between different groups, often involving interactions beyond one’s immediate social circle, giving as an example meeting someone at a networking event, a type of event where people would typically make new acquaintances. The graph presents the percentage of UK survey respondents who indicated that they trust people at least somewhat in two categories—people they know personally (bonding trust) and people they are meeting for the first time (bridging trust)—in 2005, 2018, and 2022. According to the graph, the percentage representing bonding trust remained fairly consistent over the period, at approximately 96% in 2005, 97% in 2018, and 97% in 2022. By contrast, the percentage representing bridging trust showed more variability, rising from approximately 46% in 2005 to approximately 55% in 2018 before falling to approximately 53% in 2022.\nChoice B is incorrect because the graph shows that the percentage representing bonding trust didn’t consistently grow from 2005 to 2022; rather, it remained largely consistent at approximately 96%, 97%, and 97% in 2005, 2018, and 2022, respectively. Moreover, the graph shows that the percentage representing bridging trust didn’t largely decline from 2005 to 2022; rather, it rose from approximately 46% in 2005 to approximately 55% in 2018 before falling slightly to approximately 53% in 2022. Choice C is incorrect. While the graph indicates that the percentage representing bonding trust was approximately the same in 2018 and 2022 (approximately 97%), the graph also shows that bonding trust was substantially higher than, not lower than, bridging trust in both 2018 (approximately 55%) and 2022 (approximately 53%). Choice D is incorrect. While the graph does indicate that bonding trust remained higher than bridging trust from 2005 to 2018, the claim that bonding trust declined from 2005 to 2022 isn’t supported by the graph. The graph shows that the percentage representing bonding trust rose slightly from approximately 96% in 2005 to approximately 97% in both 2018 and 2022.","is_grid_in":false},{"source_id":"6abe5e3c","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"easy","passage":"Individuals with visual impairments who want to experience a solar eclipse may be able to make use of a device that converts light into sound. The device is made up of a microcontroller board and a light sensor that measures the brightness of light shining onto the device. It also has a component called a MIDI, which allows the device to play different sounds. The device plays a high-pitched flute sound in bright light, a neutral-pitched clarinet sound in mid-range light, and a soft clicking sound in low light. After a solar eclipse starts, the sun becomes more covered and the amount of light slowly reduces. Therefore, during a solar eclipse the device will ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"play a flute sound, then a clarinet sound, and then a clicking sound."},{"label":"B","text":"play a clicking sound, then a flute sound, and then a clarinet sound."},{"label":"C","text":"start with fast clarinet sounds that become steadily slower."},{"label":"D","text":"start with a soft flute sound that becomes steadily louder."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of a device that converts light into sound during a solar eclipse. The text states that the device plays different sounds based on the amount of light shining on it, producing a high-pitched flute sound in bright light, a neutral-pitched clarinet sound in mid-range light, and a soft clicking sound in low light. The text also indicates that during a solar eclipse, the sun becomes more covered and the amount of light slowly reduces from full brightness. Thus, because the eclipse begins with full sunlight that progressively decreases, the device would first play a flute sound (bright light), then a clarinet sound (mid-range light), and then a clicking sound (low light).\nChoice B is incorrect. Based on the text’s description of the sounds the device makes, if the device played clicking sounds, then a flute sound, and then a clarinet sound, the light would have to be going from low to bright to mid-range. But the text indicates that when a solar eclipse starts, the light is bright and then slowly reduces, meaning it would go from bright to mid-range light and then to low light. And even as the sun begins to be less covered again, which isn’t discussed in the text, there’s no reason to think the light would jump from low to bright and then back to mid-range. Choice C is incorrect because the text indicates only that the device plays a distinct sound (flute, clarinet, or clicking) for each of the three levels of brightness, not that it varies the speed of any of those sounds. Choice D is incorrect because the text indicates only that the device plays a distinct sound (flute, clarinet, or clicking) for each of the three levels of brightness, not that it varies the volume of any of those sounds.","is_grid_in":false},{"source_id":"6eb0223c","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"In subtropical Asia, Apis dorsata (giant honeybee) plays an essential role in pollinating a wide variety of crops and wild plants. To study how different agricultural land covers affect the species, Rika Raffiudin and colleagues monitored the foraging activity of the bees as well as the pollen content of the honey from A. dorsata colonies at two sites in Indonesia: Kampar, characterized by its surrounding monoculture farms (growing a single crop), and Kerinci, a forest-agriculture site where multiple crops, including hot peppers and coffee, are grown nearby. The researchers concluded that a lack of crop variety may reduce total pollen collection by A. dorsata.","passage_html":null,"question_text":"Which finding, if true, would most directly support the researchers’ conclusion?","question_text_html":null,"choices":[{"label":"A","text":"Pollen in honey samples from Kampar bee colonies was predominantly sourced from a single plant species, whereas pollen in honey samples from Kerinci bee colonies was sourced from multiple different plant species."},{"label":"B","text":"In one Kerinci bee colony, a greater proportion of bees returned to their nests with pollen than returned without pollen, whereas the inverse was observed in a second Kerinci bee colony."},{"label":"C","text":"Significantly fewer bees were observed engaging in foraging activities with the crops surrounding Kerinci than with the crops surrounding Kampar."},{"label":"D","text":"Honey samples from Kerinci bee colonies contained significantly higher concentrations of pollen than honey samples from Kampar bee colonies did."}],"correct_answer":"D","explanation":"Choice D is the best answer because it presents a finding that, if true, would most directly support the researchers’ conclusion that a lack of crop variety may reduce total pollen collection by A. dorsata. The text explains that the researchers compared two sites: Kampar, which is surrounded by farms all growing the same crop, and Kerinci, which is a forest-agriculture site with multiple crops. If honey samples from Kerinci bee colonies contained significantly higher pollen concentrations than honey samples from Kampar bee colonies did, this finding would suggest that bees in the multiple-crop environment collected more pollen overall, thereby supporting the conclusion that the low crop variety at the Kampar site corresponds with reduced total pollen collection.\nChoice A is incorrect because this finding addresses the diversity of pollen sources—single species at the Kampar site versus multiple species at the Kerinci site—not the total quantity of pollen collected. Choice B is incorrect because this finding compares two colonies within Kerinci rather than comparing the two sites and it concerns whether bees returned with pollen, which doesn’t address the total quantity of pollen collected. Choice C is incorrect because the finding that fewer bees foraged at Kerinci—the higher-variety site—than at Kampar doesn’t address the conclusion about total pollen collected. If anything, a lower number of foraging bees would suggest reduced activity and hence a lower amount of pollen collected in the variety-rich environment, which would undermine rather than support the researchers’ conclusion.","is_grid_in":false},{"source_id":"b238a07a","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"easy","passage":"“Banking Coal” is a 1922 poem by Jean Toomer. The poem describes a fire being lit and maintained. In the poem, the speaker praises the person who built the fire: ______","passage_html":null,"question_text":"Which quotation from “Banking Coal” most effectively illustrates the claim?","question_text_html":null,"choices":[{"label":"A","text":"“I’ve seen them set to work, each in his way, / Though all with shovels and with ashes.”"},{"label":"B","text":"“Whoever it was who brought the first wood and coal / To start the Fire, did his part well.”"},{"label":"C","text":"“Sometimes the fire left alone / Would die...”"},{"label":"D","text":"“Whereupon they’d crawl in hooded night-caps / Contentedly to bed.”"}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a quotation that effectively illustrates the claim that the speaker in the poem praises the person who built the fire. In the quotation, the speaker explicitly refers to the builder of the fire—the one “who brought the first wood and coal / To start the Fire”—and offers praise, stating that this person “did his part well.”\nChoice A is incorrect. Although the quotation describes seeing people working with shovels and ashes, which can be associated with tending a fire, it doesn’t mention the building of the fire or single out any person for praise. Choice C is incorrect. Although the quotation refers to the fire, it describes the fire dying when left alone, not the starting of the fire or the person who built it. Choice D is incorrect because the quotation makes no reference to the fire and doesn’t praise anyone; it simply states that people got into bed contentedly in nightcaps.","is_grid_in":false},{"source_id":"71c2cea9","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"Belonging to neither the minimalist nor the abstract art movements but heavily influencing both, Constantin Brâncuşi spent his sculpting career returning to the same few themes—a kiss, a sleeping head, and a bird in flight—each rendered in pristine, simple, almost abstract forms. Perhaps the most famous example is Bird in Space (1923), a tall, slender bronze sculpture that arcs upward in a manner suggestive of flight but that otherwise lacks any identifiable characteristics of a bird. Despite the seeming simplicity of his works, the exacting standards to which Brâncuşi held his work meant that he produced relatively few pieces over his career. There is thus something of a disparity between ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"the nature of much of Brâncuşi’s work and the abstraction of Bird in Space."},{"label":"B","text":"Brâncuşi’s relatively limited productivity and the diversity of his sculptures."},{"label":"C","text":"the themes Brâncuşi explored and the themes favored by artists he inspired."},{"label":"D","text":"Brâncuşi’s importance to the history of art and his total artistic output."}],"correct_answer":"D","explanation":"Choice D is the best answer because it most logically completes the text’s discussion of the sculptor Constantin Brâncuşi. The text establishes Brâncuşi’s significance by noting that although he belonged to neither the minimalist nor the abstract art movements, he heavily influenced both—a detail that signals his importance to the history of art. At the same time, the text notes that the exacting standards to which Brâncuşi held his work meant that he produced relatively few pieces over his career. Because the text presents both Brâncuşi’s major artistic influence and his limited output, it is reasonable to infer that the disparity the text identifies is between his importance to the history of art and his total artistic output.\nChoice A is incorrect because the text explicitly identifies Brâncuşi’s Bird in Space as “a famous example” of how the artist conveyed his preferred themes—in this case, a bird in flight—through simplicity bordering on abstraction. Thus, this particular sculpture is consistent with the nature of much of Brâncuşi’s work instead of showing a disparity, or marked difference, with it. Choice B is incorrect because the text indicates that Brâncuşi returned to the same few themes, suggesting limited thematic diversity. Since his productivity and his thematic diversity were both limited, these two aspects of Brâncuşi’s work are consistent with each other instead of showing a disparity, or a marked difference. Choice C is incorrect because although the text mentions that Brâncuşi heavily influenced both the minimalist and abstract art movements, it doesn’t discuss the specific themes favored by artists in those movements. There is therefore no basis for identifying a disparity between Brâncuşi’s themes and those of artists he inspired.","is_grid_in":false},{"source_id":"2398ffbf","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Archaeologist Weiwei Wang and her colleagues analyzed footed grinding slabs and other food-preparation tools excavated from Óc Eo, a Southeast Asian port city that flourished between the first and sixth centuries CE. Wang and colleagues recovered microscopic remnants of turmeric and other spices from the surfaces of the tools. Turmeric is native to South Asia, more than a thousand miles west of Óc Eo, and the researchers showed that the footed grinding slabs at Óc Eo are very similar to footed grinding slabs common throughout South Asia from around 500 BCE to 300 CE. Wang and colleagues’ findings therefore indicate that there must have been a trade link, whether direct or indirect, between the two regions.","passage_html":null,"question_text":"Which finding, if true, would directly weaken the conclusion about Wang and her colleagues’ findings that is presented in the text?","question_text_html":null,"choices":[{"label":"A","text":"Some of the spices recovered from Óc Eo are native to the Maluku Islands, which are located approximately 2,000 miles southeast of Óc Eo."},{"label":"B","text":"In the first through third centuries CE, there was a significant migration of people from South Asia to Southeast Asia."},{"label":"C","text":"Other types of artifacts originating in South Asia and dating to the first through sixth centuries CE have been found throughout Southeast Asia."},{"label":"D","text":"The people of Óc Eo and several communities in South Asia regularly traded with people in the region that is now the Southeast Asian country of Malaysia no later than the first century CE."}],"correct_answer":"B","explanation":"Choice B is the best answer because it presents a finding that, if true, would most directly weaken the conclusion that Wang and colleagues’ findings indicate a trade link between Óc Eo and South Asia. The text explains that turmeric (native to South Asia) and footed grinding slabs of a style common in South Asia between roughly 500 BCE and 300 CE were found at Óc Eo, a Southeast Asian port that flourished between the first and sixth centuries CE. From this evidence, the text concludes that these items must have reached Óc Eo through trade. If, however, there was a significant migration of people from South Asia to Southeast Asia during the first through third centuries CE, that would offer an alternative explanation: South Asian people could have brought turmeric and grinding slabs with them when they migrated. Thus, the finding would weaken the conclusion that trade must account for the items’ presence at Óc Eo.\nChoice A is incorrect. A finding involving spices from a different region—the Maluku Islands, southeast of Óc Eo—wouldn’t undermine the conclusion because it wouldn’t reveal how the items from South Asia, a region to the west, reached Óc Eo. If anything, such a finding might be further evidence of broad trade networks involving Óc Eo. Choice C is incorrect. If it were true that other South Asian artifacts from the period when Óc Eo flourished have been found throughout Southeast Asia, that would suggest only that South Asian items other than turmeric and footed grinding slabs were present in the region at the time; it wouldn’t reveal anything about how any of those items reached Southeast Asia from South Asia. If anything, the widespread presence of South Asian artifacts in Southeast Asia during this period could be seen as further support for a trade network connecting the regions. Choice D is incorrect because the finding that Óc Eo and some South Asian communities traded with people in another Southeast Asian location (what is now Malaysia) would suggest that this location could have been an intermediary for the movement of items from South Asia to Óc Eo. Such a finding would support, not weaken, the plausibility of an indirect trade link that’s presented in the conclusion.","is_grid_in":false},{"source_id":"e35aa99b","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Bar graph titled Compressive Strength of Mortar Mixtures After Curing. The horizontal axis is labeled Mixture. 4 data categories are shown. The vertical axis is labeled Compressive strength (megapascals). It ranges from 0 to 30 in increments of 5. Refer to long description.\nMollusk shells are mainly composed of calcium carbonate, a chemical compound used in mortar and other construction materials. A research team led by Ariane da Silva Cardoso investigated pulverizing discarded Sururu mussel shells to create a substitute for fine aggregates (such as sand) in mortar mixtures. The team prepared mixtures with Sururu shell aggregate (SSA) replacing varying percentages of sand and then tested the mortars’ compressive strength on days 7 and 28 of curing. Based on their findings, the team recommended SSA substitution in relatively small proportions to avoid compromising strength.","passage_html":"<p><figure><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"400\" height=\"466.4185791015625\" viewBox=\"0 0 400 466.4185791015625\" role=\"img\" aria-label=\"Bar graph titled Compressive Strength of Mortar Mixtures After Curing. The horizontal axis is labeled Mixture. 4 data categories are shown. The vertical axis is labeled Compressive strength (megapascals). It ranges from 0 to 30 in increments of 5. Refer to long description.\"><g id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\"><defs><pattern id=\"bar4\" x=\"0\" y=\"0\" width=\"10\" height=\"100\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(50)\"><rect x=\"0\" y=\"0\" width=\"5\" height=\"100\" fill=\"#CDCDCD\"/><rect x=\"5\" y=\"0\" width=\"5\" height=\"100\" fill=\"#444444\"/></pattern></defs><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"72\" x2=\"385\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"72.89311218261719\" y1=\"72\" x2=\"84.89311218261719\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(66.89311218261719 78)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">30</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"105.33333333333334\" x2=\"385\" y2=\"105.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"72.89311218261719\" y1=\"105.33333333333334\" x2=\"84.89311218261719\" y2=\"105.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(66.89311218261719 111.33333333333334)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">25</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"138.66666666666669\" x2=\"385\" y2=\"138.66666666666669\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"72.89311218261719\" y1=\"138.66666666666669\" x2=\"84.89311218261719\" y2=\"138.66666666666669\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(66.89311218261719 144.66666666666669)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">20</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"172\" x2=\"385\" y2=\"172\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"72.89311218261719\" y1=\"172\" x2=\"84.89311218261719\" y2=\"172\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(66.89311218261719 178)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">15</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"205.33333333333334\" x2=\"385\" y2=\"205.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"72.89311218261719\" y1=\"205.33333333333334\" x2=\"84.89311218261719\" y2=\"205.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(66.89311218261719 211.33333333333334)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"238.66666666666669\" x2=\"385\" y2=\"238.66666666666669\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"72.89311218261719\" y1=\"238.66666666666669\" x2=\"84.89311218261719\" y2=\"238.66666666666669\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(66.89311218261719 244.66666666666669)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">5</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"272\" x2=\"385\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"72.89311218261719\" y1=\"272\" x2=\"84.89311218261719\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(66.89311218261719 278)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Compressive strength (megapascals)</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"78.89311218261719\" y1=\"72\" x2=\"78.89311218261719\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"102.43979586087741\" y=\"123.33333333333331\" height=\"148.66666666666669\" width=\"23.546683678260216\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"125.98647953913763\" y=\"98.66666666666666\" height=\"173.33333333333334\" width=\"23.546683678260216\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(135.90647953913762 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">control (0% SSA)</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"173.07984689565808\" y=\"106.66666666666666\" height=\"165.33333333333334\" width=\"23.546683678260216\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"196.6265305739183\" y=\"102.66666666666666\" height=\"169.33333333333334\" width=\"23.546683678260216\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(206.5465305739183 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10% SSA</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"243.71989793043875\" y=\"146.66666666666666\" height=\"125.33333333333334\" width=\"23.546683678260216\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"267.26658160869897\" y=\"128.66666666666666\" height=\"143.33333333333334\" width=\"23.546683678260216\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(277.186581608699 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">20% SSA</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"314.35994896521936\" y=\"186\" height=\"86\" width=\"23.546683678260216\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"337.90663264347955\" y=\"173.33333333333331\" height=\"98.66666666666667\" width=\"23.546683678260216\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(347.82663264347957 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">40% SSA</text><text text-anchor=\"middle\" transform=\"translate(231.9465560913086 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Compressive Strength of</text><text text-anchor=\"middle\" transform=\"translate(231.9465560913086 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Mortar Mixtures After Curing</text><text text-anchor=\"middle\" transform=\"translate(231.9465560913086 411.41861328125)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Mixture</text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"150.3215560913086\" y=\"428.57861328125\" height=\"26.84\" width=\"163.25\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"157.3215560913086\" y=\"435.57861328125\" height=\"12\" width=\"12\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(176.3215560913086 447.57861328125)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">day 7</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"230.7434310913086\" y=\"435.57861328125\" height=\"12\" width=\"12\" fill=\"#333333\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(249.7434310913086 447.57861328125)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">day 28</text></g></svg><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for bar graph titled Compressive Strength of Mortar Mixtures After Curing\"><ul><li>For each data category, the following bars are shown:<br/><ul><li>day 7</li><li>day 28</li></ul></li><li>The Compressive strength data for the 4 categories are as follows:<br/><ul><li>control (0% SSA):<br/><ul><li>day 7: 22.3 megapascals</li><li>day 28: 26.0 megapascals</li></ul></li><li>10% SSA:<br/><ul><li>day 7: 24.8 megapascals</li><li>day 28: 25.4 megapascals</li></ul></li><li>20% SSA:<br/><ul><li>day 7: 18.8 megapascals</li><li>day 28: 21.5 megapascals</li></ul></li><li>40% SSA:<br/><ul><li>day 7: 12.9 megapascals</li><li>day 28: 14.8 megapascals</li></ul></li></ul></li></ul></div></figure></p><p>Mollusk shells are mainly composed of calcium carbonate, a chemical compound used in mortar and other construction materials. A research team led by Ariane da Silva Cardoso investigated pulverizing discarded Sururu mussel shells to create a substitute for fine aggregates (such as sand) in mortar mixtures. The team prepared mixtures with Sururu shell aggregate (SSA) replacing varying percentages of sand and then tested the mortars’ compressive strength on days 7 and 28 of curing. Based on their findings, the team recommended SSA substitution in relatively small proportions to avoid compromising strength.</p>","question_text":"Which choice most effectively uses data from the graph to support the researchers’ recommendation?","question_text_html":null,"choices":[{"label":"A","text":"The 10% SSA mixture’s compressive strength was greater than or approximately equal to that of the control mixture on day 7 and on day 28, but on both days the 20% and 40% SSA mixtures had less compressive strength than the control mixture did."},{"label":"B","text":"The compressive strength of the 10% SSA mixture remained nearly the same from day 7 to day 28, while that of the 20% and 40% SSA mixtures changed substantially."},{"label":"C","text":"The 10% SSA mixture’s compressive strength was greater than that of the control mixture on day 7, but by day 28 the 10% SSA mixture’s compressive strength had decreased while that of the control mixture had increased."},{"label":"D","text":"The compressive strength of the 10% SSA mixture never surpassed the compressive strength measured for the control mixture on day 28."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most effectively uses data from the graph to support the researchers’ recommendation that Sururu shell aggregate (SSA) substitution be done in relatively small proportions to avoid compromising the compressive strength of mortar mixtures. The text explains that a research team investigated whether SSA can serve as a substitute for sand in mortar mixtures. The graph presents the compressive strength (in megapascals) of mortar mixtures with SSA replacing 0% (control), 10%, 20%, and 40% of the sand on day 7 and day 28 of curing. The graph shows that the compressive strength of the 10% SSA mixture was approximately 25 megapascals on day 7, which is greater than the control mixture’s approximately 22 megapascals on the same day. The graph also shows that the 10% SSA mixture’s compressive strength was slightly more than 25 megapascals on day 28, which is only slightly less than the control’s compressive strength on the same day (about 26 megapascals). Therefore, the graph shows that the compressive strength of the 10% SSA mixture was greater than that of the control on day 7 and roughly equal to that of the control on day 28, suggesting that substituting only 10% of the sand with SSA avoids compromising the mortar’s compressive strength. The graph also shows that on day 7, the 20% and 40% SSA mixtures had compressive strengths of about 19 and 13 megapascals, respectively (both lower than the control’s), and on day 28, they had compressive strengths of about 22 and 15 megapascals, respectively (once again lower than the control’s). Thus, the data support the recommendation by indicating that substituting relatively small proportions of sand with SSA in mortar mixtures doesn’t compromise strength compared with the control, whereas substituting larger proportions does.\nChoice B is incorrect because the comparison it makes isn’t relevant to the researchers’ recommendation. Although the graph does show that the bars representing the compressive strength of the 10% SSA mixture on day 7 and day 28 are roughly the same height (suggesting that the mixture’s compressive strength changed by only a small amount), and although there are relatively large gaps between the bars showing the compressive strength of the 20% and 40% SSA mixtures on day 7 and day 28 (suggesting that their compressive strength changed over time by a greater amount), this comparison concerns only how each SSA mixture’s strength changed over time and doesn’t compare the SSA mixtures with the control mixture. Supporting the recommendation that SSA substitution be done in small proportions requires evidence that small substitutions don’t compromise strength relative to the control while larger substitutions do. Choice C is incorrect because it doesn’t accurately represent the data in the graph, nor is the comparison it makes relevant to the researchers’ recommendation. While the graph does show that the compressive strength of the 10% SSA mixture was greater than that of the control on day 7 (about 25 megapascals vs. about 22 megapascals) and, moreover, that the compressive strength of the control increased from day 7 to day 28 (from about 22 megapascals to about 26 megapascals), the graph shows that the compressive strength of the 10% SSA mixture increased by a small amount (from about 25 megapascals to slightly more than 25 megapascals), not that it decreased. Moreover, the researchers recommended substituting relatively small proportions (compared with larger proportions) of the mixtures with SSA; comparing the compressive strength of the 10% SSA mixture with that of the control without also considering how the compressive strength of the 10% SSA mixture compared with that of the 20% and 40% SSA mixtures wouldn’t support the recommendation. Choice D is incorrect. Though the graph indicates that the 10% SSA mixture’s compressive strength on day 7 and day 28 (about 25 megapascals and slightly more than 25 megapascals, respectively) didn’t surpass the control mixture’s compressive strength on day 28 (about 26 megapascals), this observation doesn’t support the recommendation. The recommendation concerns the trade-off between SSA proportion and compressive strength; supporting it requires not just evidence about how the 10% SSA mixture compared with the control but also evidence about how the mixtures with larger proportions of SSA (20% and 40%) compared with the 10% SSA mixture and the control.","is_grid_in":false},{"source_id":"629fb8a9","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Percentages of New Year’s Resolution Makers Who Make Certain Kinds of Resolutions\nType of resolutionAge 18-29Age 30-49Age 50-64Age 65+\nHealth and exercise79807976\nFinances68635647\nPersonal relationships63535852\nHobbies65535145\nA Pew Research Center survey conducted in January 2024 found that three out of ten US adults make at least one New Year’s resolution (a promise for the year ahead), while half of those who make a resolution make more than one. The survey asked participants what kinds of resolutions they made and separated them into several categories. The table presents percentages of people who make particular kinds of New Year’s resolutions among those who choose to make them, indexed by age bracket.","passage_html":"<p><figure><table><caption><p>Percentages of New Year’s Resolution Makers Who Make Certain Kinds of Resolutions</p></caption><thead><tr><th scope=\"col\">Type of resolution</th><th scope=\"col\">Age 18-29</th><th scope=\"col\">Age 30-49</th><th scope=\"col\">Age 50-64</th><th scope=\"col\">Age 65+</th></tr></thead><tbody><tr><th scope=\"row\">Health and exercise</th><td>79</td><td>80</td><td>79</td><td>76</td></tr><tr><th scope=\"row\">Finances</th><td>68</td><td>63</td><td>56</td><td>47</td></tr><tr><th scope=\"row\">Personal relationships</th><td>63</td><td>53</td><td>58</td><td>52</td></tr><tr><th scope=\"row\">Hobbies</th><td>65</td><td>53</td><td>51</td><td>45</td></tr></tbody></table></figure></p><p>A Pew Research Center survey conducted in January 2024 found that three out of ten US adults make at least one New Year’s resolution (a promise for the year ahead), while half of those who make a resolution make more than one. The survey asked participants what kinds of resolutions they made and separated them into several categories. The table presents percentages of people who make particular kinds of New Year’s resolutions among those who choose to make them, indexed by age bracket.</p>","question_text":"Which choice best presents a conclusion about the habits of New Year’s resolution makers that is best supported by information in the text and the table?","question_text_html":null,"choices":[{"label":"A","text":"Resolution makers between the ages of 50 and 64 are more likely to make resolutions related to personal relationships and less likely to make resolutions related to finances than resolution makers between the ages of 30 and 49 are."},{"label":"B","text":"Resolution makers between the ages of 18 and 29 are more likely to make resolutions about health and exercise than resolution makers between the ages of 30 and 49 are."},{"label":"C","text":"The majority of US adults who make resolutions related to health and exercise also make resolutions in multiple additional categories."},{"label":"D","text":"Among all US adults, people become less likely to make New Year’s resolutions as they age, regardless of the type of resolution."}],"correct_answer":"A","explanation":"Choice A is the best answer because it presents a conclusion about the habits of New Year’s resolution makers that is best supported by information in the text and the table. The table presents percentages of resolution makers who make particular kinds of resolutions, indexed by age bracket. According to the table, 58 percent of resolution makers ages 50 to 64 made resolutions related to personal relationships, compared to 53 percent of resolution makers ages 30 to 49—indicating that the older group is more likely to make such resolutions. The table also shows that 56 percent of resolution makers ages 50 to 64 made resolutions related to finances, compared to 63 percent of resolution makers ages 30 to 49—indicating that the older group is less likely to make financial resolutions. Thus, the data support the conclusion that resolution makers between the ages of 50 and 64 are more likely to make resolutions related to personal relationships and less likely to make resolutions related to finances than resolution makers between the ages of 30 and 49 are.\nChoice B is incorrect because according to the table, 79 percent of resolution makers ages 18 to 29 made resolutions about health and exercise, while 80 percent of resolution makers ages 30 to 49 made such resolutions. Therefore, resolution makers ages 18 to 29 are slightly less likely, not more likely, to make resolutions about health and exercise than resolution makers ages 30 to 49 are. Choice C is incorrect because neither the text nor the table provides information about whether resolution makers who make resolutions related to health and exercise also make resolutions in multiple additional categories. The text indicates that half of those who make a resolution make more than one, but it doesn’t specify how many or in which categories, and the table presents only the percentages of resolution makers in each age bracket who made particular kinds of resolutions. Choice D is incorrect because the table presents data only about people who chose to make resolutions, not about all US adults; the table therefore can’t support a conclusion about whether US adults overall become less likely to make resolutions as they age. Furthermore, although percentages of resolution makers generally decline as age bracket increases in some resolution categories, the table shows that the percentage of resolution makers who made health and exercise resolutions remains relatively stable across age brackets; thus, even among resolution makers, there isn’t a consistent age-related decline across all types of resolutions.","is_grid_in":false},{"source_id":"7aa510fb","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"In their meta-analysis of research on advergames (video games developed to promote products or services), Zeph M.C. van Berlo et al. confirm that such games, though they can elicit player interest, may not facilitate subsequent recall of product and brand information. This phenomenon can be explained by the finite nature of cognitive capacity as it is articulated in Annie Lang’s limited capacity model of motivated mediated message processing. In this case, players’ cognitive resources are directed foremost toward the advergame’s mechanics, leaving little or no capacity for encoding and storing the information the advertiser intends to be salient.","passage_html":null,"question_text":"Which choice best states the main idea of the text?","question_text_html":null,"choices":[{"label":"A","text":"The limited capacity model of motivated mediated message processing developed by Lang provides a means of explaining the finding by van Berlo et al. that players may not readily recollect the brand and product information embedded in advergames."},{"label":"B","text":"Research by van Berlo et al. corroborates Lang’s conclusion that because people predominantly focus on game mechanics when playing video games, it is difficult for advergames to communicate brand and product information in ways that are highly memorable."},{"label":"C","text":"The meta-analysis by van Berlo et al. reveals that higher engagement in advergame mechanics is linked to lower effectiveness in persuading players to purchase particular brands and products."},{"label":"D","text":"Although the limited capacity model of motivated mediated message processing developed by Lang suggests otherwise, advergames can succeed as marketing tools, provided that they achieve a balance between game mechanics and the promotion of a brand or product."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most accurately states the main idea of the text. The text begins by presenting van Berlo et al.’s finding that advergames—video games intended to promote a specific product or service—can be engaging to players but “may not facilitate subsequent recall of product and brand information,” ultimately limiting their effectiveness as advertisements. The text then suggests that Lang’s limited capacity model of motivated mediated message processing, which characterizes cognitive capacity as finite, can explain or account for van Berlo et al.’s finding: specifically, players’ attention is “directed foremost toward the advergame’s mechanics” instead of toward the advertising information. The main idea of the text is therefore that Lang’s model provides a means of explaining van Berlo et al.’s finding.\nChoice B is incorrect because it mischaracterizes the relationship between Lang’s model and van Berlo et al.’s finding. The text presents Lang’s model as a broad theoretical framework about cognitive capacity that can explain van Berlo et al.’s finding. The text doesn’t indicate that Lang drew conclusions specific to video games that van Berlo et al. then corroborated. Choice C is incorrect because it mischaracterizes the findings of the meta-analysis by van Berlo et al. Although Lang’s model suggests that engagement in advergame mechanics occurs at the expense of recalling advertising information, the text doesn’t indicate that van Berlo et al. offered this explanation for their finding. The text merely states that van Berlo et al. found that advergames “can elicit player interest” but “may not facilitate subsequent recall of product and brand information.” In addition, the text doesn’t discuss whether players’ ability to recall advertising content ultimately affects their purchasing behavior. Choice D is incorrect. Although the text presents Lang’s model as an explanation of why advergames may not succeed in promoting recall of advertising information, the text doesn’t suggest that advergames can succeed as marketing tools if they balance mechanics and promotion. The text doesn’t propose a design solution to the limitations of advergames or suggest that these limitations can be overcome.","is_grid_in":false},{"source_id":"b603f00b","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"Microbial fuel cells (MFCs) capitalize on the ability of some species of bacteria to oxidize organic matter and transfer electrons extracellularly. The bacteria form a dense biofilm on the surface of an electron-collecting anode, but moving the electrons from the bacterial cytoplasm to an external electrode requires that the electrons pass through a series of inefficient oxidation-reduction (redox) reactions. Accordingly, MFC power output rarely exceeds a density of 0.30 milliwatts per square centimeter (mW/cm2). In an experiment, researchers added silver nanoparticles to carbon paper covering the anode in an MFC. The resulting power density was 0.66 mW/cm2. Since metals such as silver exhibit high electrical conductivity, the researchers hypothesized that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"silver nanoparticles may allow electrons to bypass the series of redox reactions and transfer directly to the electrode."},{"label":"B","text":"electrons may be conducted directly to the electrode before the silver nanoparticles catalyze the redox reactions."},{"label":"C","text":"silver nanoparticles may increase the metabolic processes of the bacteria, thereby increasing the number of free electrons available to transfer to the electrode."},{"label":"D","text":"as the density of the biofilm increases, the series of redox reactions may accelerate independent of the presence of the silver nanoparticles."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of microbial fuel cells (MFCs) and the effect of silver nanoparticles on power output. The text explains that in MFCs, electrons are transferred from the bacterial cytoplasm to an external electrode through a series of inefficient redox reactions, which typically prevent power output from exceeding 0.30 mW/cm2. When researchers added silver nanoparticles to carbon paper covering the anode, power density more than doubled to 0.66 mW/cm2. Critically, the text notes that metals such as silver exhibit high electrical conductivity. Given that the inefficiency of the redox reactions accounted for the limited power output of MFCs and that the addition of a highly conductive material dramatically increased that output, it is reasonable to hypothesize that the silver nanoparticles allowed electrons to bypass the redox reactions and transfer directly to the electrode.\nChoice B is incorrect because the researchers’ hypothesis, as set up by the last sentence of the text, is specifically grounded in the high electrical conductivity of metals such as silver. Nothing in the text supports the idea that the silver nanoparticles function as catalysts for the redox reactions, nor does the text suggest that electrons are being conducted to the electrode independently of any role played by the silver nanoparticles. The text points to the conductivity of silver as the explanation for the increased power density, not to any catalytic effect of the nanoparticles on the existing redox reactions. Choice C is incorrect because the text never discusses the metabolic processes of the bacteria in the biofilm coating the electron-collecting anodes, nor is there any suggestion that the high conductivity of silver nanoparticles would interact with the bacteria’s metabolism in any way. Choice D is incorrect because the text never suggests that in the experiment, the biofilm on the electron-collecting anodes varied in density. Moreover, the hypothetical statement begun in the last sentence of the text concerns the high electrical conductivity of metals such as silver. Thus, proposing that redox reactions—which, as the text establishes, conduct electricity—accelerated independently of a conductive metallic material (the silver nanoparticles) wouldn’t logically complete that hypothesis.","is_grid_in":false},{"source_id":"024eb2ec","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"Through adaptive radiation, multiple species of Tetragnatha—a genus of orb-weaving spiders—have significantly diversified their web architecture over a relatively short timescale. To investigate whether the material properties of Tetragnatha silk have been similarly affected by this evolutionary process, Angela M. Alicea-Serrano et al. examined the chemical composition of both the radial (non-sticky threads extending from the center) and capture (sticky threads that hold prey) silks that form the web as well as tested the tensile strength and viscosity of samples collected from three Tetragnatha species at two sites in the Hawaiian archipelago. The team found significant interspecies variation in these biomaterials.","passage_html":null,"question_text":"Which choice best states the main idea of the text?","question_text_html":null,"choices":[{"label":"A","text":"Research reveals that web architecture among species of Tetragnatha spiders has likely diversified more rapidly than the material properties of Tetragnatha’s silk have."},{"label":"B","text":"Research suggests that the material properties of silk from species of Tetragnatha spiders have diversified during adaptive radiation."},{"label":"C","text":"A study indicates that variations in web architecture among species of Tetragnatha spiders can likely be explained by corresponding variations in the material properties of their silks."},{"label":"D","text":"A study shows that adaptive radiation can explain interspecies variation in the web architecture of Tetragnatha spiders but not in the material properties of the spiders’ silk."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most accurately states the main idea of the text. The text notes that Tetragnatha spiders have diversified their web architecture, or web design, through adaptive radiation and that Alicea-Serrano et al. investigated whether silk material properties were also affected by this process. After examining chemical composition, tensile strength, and viscosity of silks from three Tetragnatha species, the team found significant interspecies variation in these material properties, meaning that there were observable differences in these traits across the studied species. In the context of the study’s research question, this finding suggests that the material properties of silk from species of Tetragnatha spiders have indeed diversified during adaptive radiation, which is the main idea of the text.\nChoice A is incorrect because the text doesn’t compare the rate of diversification in web architecture to the rate of diversification in silk properties. Although the text notes that web architecture diversified “over a relatively short timescale,” it doesn’t make a corresponding temporal claim about silk properties or suggest that one changed more rapidly than the other. Choice C is incorrect because the study investigated silk properties as a separate question, not as an explanation for differences in web architecture. The researchers discussed in the text investigated whether silk properties were “similarly affected” by adaptive radiation, not whether they caused the variations in web design. Choice D is incorrect because it contradicts the findings described in the text. The study found “significant interspecies variation” in silk biomaterials, suggesting that adaptive radiation did affect the properties of Tetragnatha spiders’ silk rather than showing that adaptive radiation cannot explain silk variation.","is_grid_in":false},{"source_id":"4a5bda7a","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"In a study of perceptions of listening ability, participants explained their position on a sociopolitical issue and then received a listener’s written summary that expressed agreement or disagreement. Within selected summaries, researchers embedded markers of attentive listening (e.g., references to specific details), hypothesizing that such indications would positively influence perceptions of listening skill even in the context of disagreement. Instead, participants consistently rated listeners who expressed disagreement as less skilled, regardless of the other traits of the listeners’ summaries.","passage_html":null,"question_text":"What does the text most strongly imply about how participants responded to expressions of disagreement?","question_text_html":null,"choices":[{"label":"A","text":"When participants felt personally invested in the topics they discussed, they were less likely to perceive listeners who expressed disagreement as attentive, regardless of evidence to the contrary in these listeners’ summaries."},{"label":"B","text":"When participants encountered summaries from listeners who expressed disagreement with their views, participants tended to disregard evidence that the listeners had in fact been attentive."},{"label":"C","text":"Although participants maintained their positions regardless of a summary’s level of detail, they tended to regard listeners who expressed disagreement as more attentive when these listeners provided more detailed summaries."},{"label":"D","text":"Although participants were critical of expressions of disagreement, they gave higher ratings to listeners whose summaries included markers of attentiveness than to listeners whose summaries did not include these markers."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most accurately describes what the text implies about participants’ responses to disagreement. The text describes a study in which participants were asked to explain their position on an issue to a listener, who then provided a written summary of that position that also expressed their level of agreement. The participants were then asked, based on these summaries, to rate listeners’ listening skill. The text indicates that researchers embedded markers of attentive listening, such as references to details, in some of the summaries, expecting that these markers would improve the participants’ perceptions of listening skill even when the listeners disagreed. Instead, participants rated disagreeing listeners as less skilled, or attentive, “regardless of the other traits of the listeners’ summaries.” This means that even when summaries contained evidence of attentive listening, participants still judged disagreeing listeners as less skilled—in effect, disregarding evidence that those listeners had been attentive.\nChoice A is incorrect. Although the text does suggest that participants tended to disregard evidence of attentiveness when listeners disagreed with their position on the topic they discussed, it doesn’t address participants’ level of personal investment in these topics; therefore, the text can’t support any conclusions about how personal investment in a topic affected participants’ perceptions of the listening skill of disagreeing listeners. Choice C is incorrect because it directly contradicts the text. The text states that participants rated disagreeing listeners as less skilled regardless of the other traits of the listeners’ summaries, which means markers of attentiveness (specific details) didn’t lead participants to regard disagreeing listeners as more attentive. Instead, disagreement alone determined the participants’ lower ratings. Moreover, the text doesn’t address whether participants maintained their positions based on the listeners’ summaries. The text focuses on factors affecting participants’ perceptions of listeners’ attentiveness, not on how features of listeners’ summaries influenced the participants’ views of the sociopolitical issue they discussed. Choice D is incorrect because the text indicates the opposite: participants didn’t give higher ratings to disagreeing listeners whose summaries included markers of attentiveness than to disagreeing listeners whose summaries didn’t include these markers. Rather, the text states that participants rated disagreeing listeners as less skilled than agreeing listeners regardless of the other traits of the summaries, meaning attentiveness markers had no positive effect when listeners’ summaries expressed disagreement.","is_grid_in":false},{"source_id":"5869a196","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","passage":"Hypothesizing that reliance on smartphones for information retrieval will lead a person to incorrectly remember instances of phone-assisted retrieval as instances of retrieval from memory, researchers asked participants general-knowledge trivia questions, instructing them to answer certain questions using only their smartphone and other questions using only their memory. When surveyed a week later, participants exhibited higher levels of misattribution for answers retrieved in the smartphone condition than for those retrieved in the memory condition, a finding that the researchers claimed supported their hypothesis.","passage_html":null,"question_text":"Which question would be most useful to answer in determining the validity of the researchers’ claim as it is presented in the text?","question_text_html":null,"choices":[{"label":"A","text":"Were participants as likely to remember the source of their information when asked a week later as they would have been if asked immediately after answering the trivia questions?"},{"label":"B","text":"Were participants less confident about the accuracy of information they were instructed to retrieve from a smartphone than they were of that retrieved from their own memory?"},{"label":"C","text":"How likely were participants to answer all the trivia questions correctly in both the smartphone and the memory conditions?"},{"label":"D","text":"How did participants attribute information they were instructed to retrieve from a smartphone in instances when they already knew that information independently of their phone?"}],"correct_answer":"D","explanation":"Choice D is the best answer because it identifies a question that directly addresses a potential confounding factor in the research. The text discusses a study investigating source misattribution for information retrieved with the assistance of a smartphone—that is, how well people remember whether they used a smartphone to look up information or retrieved the information from their memory. The researchers hypothesized that smartphone reliance causes people to mistakenly think that they retrieved the information from their memory when they in fact used a smartphone. To test this hypothesis, the researchers instructed participants to look up answers to some trivia questions on smartphones and to answer some questions using only their memory. The text then indicates that a week later, participants were more likely to misremember smartphone-assisted answers as coming from memory than to misremember memory-based answers as coming from smartphones. The researchers claimed that the higher misattribution rates for the smartphone-retrieval condition supported their hypothesis. However, the text doesn’t specify whether the study design accounted for the possibility that some participants might have known many—perhaps even all—of the trivia answers beforehand. If participants already knew some answers they were instructed to look up on their phones, their later attribution of those answers to memory might be accurate rather than a misattribution. Knowing how participants attributed information in such cases would help determine whether the observed effect reflects smartphone-induced misattribution or simply participants’ recall of prior knowledge. Thus, in evaluating the validity of the researchers’ claim, it would be most useful to know how participants attributed information they were instructed to retrieve from a phone in instances where they already knew the information.\nChoice A is incorrect. Although survey timing is a methodological consideration, it doesn’t help distinguish between genuine misattribution caused by smartphone reliance and other explanations for the observed effect. Though it’s plausible that participants’ recollections of their information source may have been more accurate immediately after answering the trivia questions than they would have been a week later, the one-week delay would affect both conditions equally and doesn’t specifically challenge the researchers’ claim about smartphone-induced misattribution. Choice B is incorrect because confidence in the accuracy of retrieved information doesn’t directly pertain to source misattribution. The researchers’ claim concerns whether participants believed information came from their smartphone or their memory, not how confident they were in its correctness. Instead, a useful question would need to address the source-attribution process itself. Choice C is incorrect because the accuracy of the participants’ answers doesn’t bear on the researchers’ claim about source misattribution. The claim concerns the remembered origin of answers, not their correctness. Instead, the relevant issue is whether participants who looked up answers they already knew might have attributed those answers to memory regardless of which of the two experimental conditions they answered those questions under.","is_grid_in":false},{"source_id":"43f4013a","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Global Strontium Seawater Curve\n87Sr/86SrAge (Ma)\n0.7089806.20\n0.7090005.86\n0.7090205.40\n0.7090404.75\n0.7090603.00\nThe late Hemphillian (Hh) North American Land Mammal Age includes the subdivisions Hh3, 6.8 million years ago (Ma) to 6 Ma, and Hh4, 6 Ma to 4.75 Ma. While mammalian fossils have indicated that Florida’s Montbrook Fossil Site (MFS) and Palmetto Fauna of the Bone Valley Region (PFBV) date to Hh4, a more precise determination of the sites’ ages has proved challenging. Stephanie R. Killingsworth et al. compared average ratios of strontium-87 to strontium-86 (87Sr/86Sr) in fossil shark teeth from MFS and PFBV—0.709000 and 0.709028, respectively—to 87Sr/86Sr ratios in the global strontium seawater curve, a record that shows how 87Sr/86Sr ratios in seawater correspond to numerical ages and that is used to date fossils and, by extension, fossil sites. The researchers concluded that ______","passage_html":"<p><figure><table><caption><p>Global Strontium Seawater Curve </p></caption><thead><tr><th scope=\"col\"><sup>87</sup><span>Sr</span>/<sup>86</sup><span>Sr</span></th><th scope=\"col\">Age (<span>Ma</span>)</th></tr></thead><tbody><tr><th scope=\"row\">0.708980</th><td>6.20</td></tr><tr><th scope=\"row\">0.709000</th><td>5.86</td></tr><tr><th scope=\"row\">0.709020</th><td>5.40</td></tr><tr><th scope=\"row\">0.709040</th><td>4.75</td></tr><tr><th scope=\"row\">0.709060</th><td>3.00</td></tr></tbody></table></figure></p><p>The late Hemphillian (Hh) North American Land Mammal Age includes the subdivisions Hh3, 6.8 million years ago (<span>Ma</span>) to 6 <span>Ma</span>, and Hh4, 6 <span>Ma</span> to 4.75 <span>Ma</span>. While mammalian fossils have indicated that Florida’s Montbrook Fossil Site (MFS) and Palmetto Fauna of the Bone Valley Region (PFBV) date to Hh4, a more precise determination of the sites’ ages has proved challenging. Stephanie <span>R.</span> Killingsworth et al. compared average ratios of strontium-87 to strontium-86 (<sup>87</sup><span>Sr</span>/<sup>86</sup><span>Sr</span>) in fossil shark teeth from MFS and PFBV—0.709000 and 0.709028, respectively—to <sup>87</sup><span>Sr</span>/<sup>86</sup><span>Sr</span> ratios in the global strontium seawater curve, a record that shows how <sup>87</sup><span>Sr</span>/<sup>86</sup><span>Sr</span> ratios in seawater correspond to numerical ages and that is used to date fossils and, by extension, fossil sites. The researchers concluded that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","question_text":"Which choice most effectively uses data from the table to complete the statement?","question_text_html":null,"choices":[{"label":"A","text":"mammalian fossil evidence offers less dating precision than do 87Sr/86Sr ratios in fossil shark teeth and that PFBV likely was deposited closer to the Hh3-Hh4 boundary than was MFS."},{"label":"B","text":"the average 87Sr/86Sr ratios in the fossil shark teeth from MFS and PFBV only partially support the site age estimates previously established through mammalian fossil evidence."},{"label":"C","text":"the average 87Sr/86Sr ratios in the fossil shark teeth from MFS and PFBV resolve previous uncertainty about the sites’ relative ages by indicating that both sites were deposited contemporaneously during the late Hh."},{"label":"D","text":"the average 87Sr/86Sr ratios in the fossil shark teeth from MFS and PFBV corroborate that both MFS and PFBV fall within Hh4 but suggest that PFBV was likely deposited more recently than MFS."}],"correct_answer":"D","explanation":"Choice D is the best answer because it most effectively uses data from the table to complete the statement about the researchers’ conclusion about fossil shark teeth. The text states that mammalian fossil evidence has placed both MFS and PFBV within Hh4 (6 Ma to 4.75 Ma) but “a more precise determination of the sites’ ages has proved challenging,” prompting Killingsworth and colleagues to attempt to date the sites by comparing average ⁸⁷Sr/⁸⁶Sr ratios for fossil shark teeth from MFS and PFBV to ratios in the global strontium seawater curve. Given that “⁸⁷Sr/⁸⁶Sr ratios in seawater correspond to numerical ages,” a fossil whose ⁸⁷Sr/⁸⁶Sr ratio corresponds to the ratio associated with a particular age in the global strontium seawater curve can be inferred to date to that age. According to the table, the ⁸⁷Sr/⁸⁶Sr ratio of 0.709000 for fossil shark teeth from MFS corresponds to an age of 5.86 Ma, which falls within Hh4. By contrast, the table shows that the ⁸⁷Sr/⁸⁶Sr ratio of 0.709028 for fossils from PFBV would fall between 0.709020 (5.40 Ma) and 0.709040 (4.75 Ma), indicating an age that falls within Hh4 but is more recent than MFS’s age of 5.86 Ma. The data therefore corroborate the conclusion that both sites fall within Hh4 while suggesting that PFBV was likely deposited more recently than MFS was.\nChoice A is incorrect because the table indicates that MFS was deposited closer to the Hh3-Hh4 boundary than PFBV was, not the reverse. The table indicates that PFBV’s ⁸⁷Sr/⁸⁶Sr ratio of 0.709028 corresponds to an age between 4.75 Ma and 5.40 Ma, while MFS’s ⁸⁷Sr/⁸⁶Sr ratio of 0.709000 corresponds to an age of 5.86 Ma. Because the Hh3-Hh4 boundary occurs at 6 Ma, MFS was deposited closer to that boundary than PFBV was. In addition, the text doesn’t establish that mammalian fossil evidence offers less dating precision than ⁸⁷Sr/⁸⁶Sr ratios do; it states only that mammalian fossils have placed both MFS and PFBV in Hh4 and that more precise dating has proved challenging. Choice B is incorrect because it mischaracterizes the level of support for the site age estimates established through mammalian fossil evidence. The table indicates that the average ⁸⁷Sr/⁸⁶Sr ratios from MFS (0.709000) and PFBV (0.709028) both correspond to ages that fall within Hh4 (6 Ma to 4.75 Ma)—5.86 Ma for MFS and an age between 5.40 Ma and 4.75 Ma for PFBV. The ⁸⁷Sr/⁸⁶Sr ratios therefore fully support, rather than only partially support, the previous mammalian fossil evidence placing both sites within Hh4. Choice C is incorrect because the table indicates that the average ⁸⁷Sr/⁸⁶Sr ratios in fossil shark teeth from MFS (0.709000) and PFBV (0.709028) correspond to different ages—5.86 Ma for MFS and an age between 5.40 Ma and 4.75 Ma for PFBV. Because the ratios point to different ages, they don’t support the conclusion that the fossils at the two sites were deposited contemporaneously, or at the same time.","is_grid_in":false},{"source_id":"46a31ca1","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"Bar graph titled Relative Contributions of Processes to Prokaryotic and Fungal Community Assembly in Qinghai-Tibetan Lakes. The horizontal axis has no label. 5 data categories are shown. The vertical axis is labeled Percentage of contribution. It ranges from 0 to 60 in increments of 10. Refer to long description.\nIn a 2020 study, Jian Yang et al. examined prokaryotic and fungal microbial communities in Qinghai-Tibetan Plateau lake sediment to understand the relative contributions of various factors to community assembly, or formation. They quantified the contributions of environmental pressures (variable and homogeneous selection), dispersal limitation, homogenizing dispersal, and nondominant processes. Tolerance of environmental pressures is known to be higher in fungi than in prokaryotes, which the researchers hypothesize accounts for the finding that ______","passage_html":"<p><figure><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"400\" height=\"567.4010009765625\" viewBox=\"0 0 400 567.4010009765625\" role=\"img\" aria-label=\"Bar graph titled Relative Contributions of Processes to Prokaryotic and Fungal Community Assembly in Qinghai-Tibetan Lakes. The horizontal axis has no label. 5 data categories are shown. The vertical axis is labeled Percentage of contribution. It ranges from 0 to 60 in increments of 10. Refer to long description.\"><g id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\"><defs><pattern id=\"bar4\" x=\"0\" y=\"0\" width=\"10\" height=\"100\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(50)\"><rect x=\"0\" y=\"0\" width=\"5\" height=\"100\" fill=\"#CDCDCD\"/><rect x=\"5\" y=\"0\" width=\"5\" height=\"100\" fill=\"#444444\"/></pattern></defs><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"96\" x2=\"385\" y2=\"96\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.375\" y1=\"96\" x2=\"85.375\" y2=\"96\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.375 102)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">60</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"129.33333333333334\" x2=\"385\" y2=\"129.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.375\" y1=\"129.33333333333334\" x2=\"85.375\" y2=\"129.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.375 135.33333333333334)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">50</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"162.66666666666669\" x2=\"385\" y2=\"162.66666666666669\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.375\" y1=\"162.66666666666669\" x2=\"85.375\" y2=\"162.66666666666669\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.375 168.66666666666669)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">40</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"196\" x2=\"385\" y2=\"196\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.375\" y1=\"196\" x2=\"85.375\" y2=\"196\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.375 202)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">30</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"229.33333333333334\" x2=\"385\" y2=\"229.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.375\" y1=\"229.33333333333334\" x2=\"85.375\" y2=\"229.33333333333334\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.375 235.33333333333334)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">20</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"262.6666666666667\" x2=\"385\" y2=\"262.6666666666667\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.375\" y1=\"262.6666666666667\" x2=\"85.375\" y2=\"262.6666666666667\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.375 268.6666666666667)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"296\" x2=\"385\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.375\" y1=\"296\" x2=\"85.375\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.375 302)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 196) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Percentage of contribution</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.375\" y1=\"96\" x2=\"79.375\" y2=\"296\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"98.4765625\" y=\"168.33333333333334\" height=\"127.66666666666666\" width=\"19.1015625\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"117.578125\" y=\"103\" height=\"193\" width=\"19.1015625\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(127.498125 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">variable selection</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"155.78125\" y=\"291\" height=\"5\" width=\"19.1015625\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"174.8828125\" y=\"296\" height=\"0\" width=\"19.1015625\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(184.8028125 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">homogeneous selection</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"213.0859375\" y=\"287.6666666666667\" height=\"8.333333333333334\" width=\"19.1015625\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"232.1875\" y=\"296\" height=\"0\" width=\"19.1015625\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(242.1075 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">dispersal limitation</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"270.390625\" y=\"250.33333333333334\" height=\"45.666666666666664\" width=\"19.1015625\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"289.4921875\" y=\"171.66666666666669\" height=\"124.33333333333333\" width=\"19.1015625\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(299.4121875 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">homogenizing dispersal</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"327.6953125\" y=\"150.33333333333331\" height=\"145.66666666666669\" width=\"19.1015625\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"346.796875\" y=\"284.3333333333333\" height=\"11.666666666666668\" width=\"19.1015625\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(356.716875 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">nondominant process</text><text text-anchor=\"middle\" transform=\"translate(232.1875 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Relative Contributions of Processes to </text><text text-anchor=\"middle\" transform=\"translate(232.1875 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Prokaryotic and Fungal Community </text><text text-anchor=\"middle\" transform=\"translate(232.1875 72)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Assembly in Qinghai-Tibetan Lakes</text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"95.43976593017578\" y=\"485.4010009765625\" height=\"71\" width=\"224.12046813964844\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"102.43976593017578\" y=\"497.4010009765625\" height=\"12\" width=\"12\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(124.43976593017578 509.4010009765625)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> fungal community</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"102.43976593017578\" y=\"529.4010009765625\" height=\"12\" width=\"12\" fill=\"#333333\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(124.43976593017578 541.4010009765625)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> prokaryotic community</text></g></svg><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for bar graph titled Relative Contributions of Processes to Prokaryotic and Fungal Community Assembly in Qinghai-Tibetan Lakes\"><ul><li>For each data category, the following bars are shown:<br/><ul><li>fungal community</li><li>prokaryotic community</li></ul></li><li>The Percentage of contribution data for the 5 categories are as follows:<br/><ul><li>variable selection:<br/><ul><li>fungal community: 38.3 percent</li><li>prokaryotic community: 57.9 percent </li></ul></li><li>homogeneous selection: <br/><ul><li>fungal community: 1.5 percent</li><li>prokaryotic community: 0.0 percent </li></ul></li><li>dispersal limitation: <br/><ul><li>fungal community: 2.5 percent</li><li>prokaryotic community: 0.0 percent </li></ul></li><li>homogenizing dispersal: <br/><ul><li>fungal community: 13.7 percent</li><li>prokaryotic community: 37.3 percent</li></ul></li><li>nondominant process: <br/><ul><li>fungal community: 43.7 percent</li><li>prokaryotic community: 3.5 percent</li></ul></li></ul></li></ul></div></figure></p><p>In a 2020 study, Jian Yang et al. examined prokaryotic and fungal microbial communities in Qinghai-Tibetan Plateau lake sediment to understand the relative contributions of various factors to community assembly, or formation. They quantified the contributions of environmental pressures (variable and homogeneous selection), dispersal limitation, homogenizing dispersal, and nondominant processes. Tolerance of environmental pressures is known to be higher in fungi than in prokaryotes, which the researchers hypothesize accounts for the finding that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","question_text":"Which choice most effectively uses data from the graph to complete the statement?","question_text_html":null,"choices":[{"label":"A","text":"homogenizing dispersal contributed substantially less to fungal community assembly than variable selection did."},{"label":"B","text":"the total number of factors that contributed to community assembly was greater for prokaryotes than for fungi."},{"label":"C","text":"variable selection contributed substantially less to fungal community assembly than to prokaryote community assembly."},{"label":"D","text":"the contribution of homogeneous selection to community assembly was negligible for both fungi and prokaryotes."}],"correct_answer":"C","explanation":"Choice C is the best answer because it most effectively uses data from the graph to complete the statement about the researchers’ hypothesis regarding a finding. The text states that the researchers attribute a certain finding about community assembly in fungi and prokaryotes to the fact that fungi have a higher tolerance for environmental pressures than do prokaryotes. This finding, then, would be explained by the fact that fungi better tolerate environmental pressures, which the text defines as including variable and homogeneous selection. According to the graph, the contribution of variable selection to community assembly was nearly 40 percent for fungi but nearly 60 percent for prokaryotes, indicating that variable selection contributed significantly less to fungal community assembly than to prokaryotic community assembly. This finding aligns with the researchers’ hypothesis: because fungi tolerate environmental pressures like variable selection better than prokaryotes do, those pressures play a smaller role in shaping fungal communities than in shaping prokaryotic communities.\nChoice A is incorrect. Although this comparison is supported by the graph, which shows that homogenizing dispersal’s contribution to fungal community assembly was just over 10 percent while variable selection’s contribution was just under 40 percent, this comparison doesn’t illustrate the hypothesis because it involves two factors affecting fungal community assembly. The researchers’ hypothesis specifically concerns a difference between fungi and prokaryotes (namely, fungi’s greater tolerance of environmental pressures), so a comparison that is limited to fungal community assembly doesn’t represent a finding that aligns with this hypothesis. Choice B is incorrect because it mischaracterizes the information in the graph. The graph indicates that the total number of factors that contributed to community assembly was greater for fungi than for prokaryotes: all five factors made nonzero contributions to fungal community assembly, while two factors—homogeneous selection and dispersal limitation—appear not to have contributed to prokaryotic community assembly. In addition, the overall number of factors that influence community assembly isn’t directly relevant to the researchers’ hypothesis, which addresses the effects of higher tolerance of environmental pressures among fungi in comparison to prokaryotes. Choice D is incorrect. Although the graph indicates that homogeneous selection contributed only minimally to fungal community assembly and appears not to have contributed at all to prokaryotic community assembly, this isn’t a finding that the researchers’ hypothesis would account for. The hypothesis concerns a difference between fungi and prokaryotes that is plausibly attributable to fungi’s greater tolerance of environmental pressures, which include homogeneous and variable selection. The finding that one type of environmental pressure contributed negligibly to both groups doesn’t differentiate fungi from prokaryotes and therefore doesn’t illustrate what the hypothesis is meant to explain.","is_grid_in":false},{"source_id":"6ca4f991","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"medium","passage":"Many linguists have claimed that the lyricism of Alexander Pushkin’s Russian novel in verse Eugene Onegin makes the work incapable of being faithfully translated, especially into English. The original work is written much like a long poem, featuring linguistic patterns and flourishes specific to the Russian language. Rather than striving to portray each scene of the novel literally, John Cranko, in his ballet adaptation of Eugene Onegin, opted to let the essence of the work’s emotions inspire the passion of the dancers. Critic Emma Golden writes that Cranko’s “choreography uses the poetry of the human body to summon the parts of Pushkin’s novel that were deemed untranslatable—its commitments to rhythm, cadence, symmetry.” It seems, then, that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"Cranko’s loose adaptation of Eugene Onegin into a different medium may have preserved fundamental elements of the source material better than a strictly literal written translation of the text would have."},{"label":"B","text":"though written works are frequently adapted into other formats, ballets are rarely considered to be faithful adaptations of texts."},{"label":"C","text":"English is a particularly difficult language into which to translate poetic works, as its rhythms differ from those of many other languages."},{"label":"D","text":"most critics believe that, like other English translations of Eugene Onegin, Cranko’s ballet adaptation fails to capture the essence of the original’s meaning."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of John Cranko’s ballet adaptation of Pushkin’s Russian novel in verse, Eugene Onegin. According to the text, the novel’s lyricism—specifically its reliance on linguistic patterns and flourishes that are unique to the Russian language—renders a faithful translation, especially one into English, impossible. The text then discusses Cranko’s adaptation of Eugene Onegin into a ballet whose choreography, according to one critic, evokes aspects of the novel that were deemed untranslatable: “its commitments to rhythm, cadence, symmetry.” Given the claim that the ballet captures what would seem untranslatable, it can be inferred that Cranko’s loose adaptation of the novel into a different medium—namely, dance—may have preserved fundamental elements of the source material better than a strictly literal written translation into English or another language would have.\nChoice B is incorrect because the text discusses one specific ballet adaptation of Eugene Onegin and one critic’s assessment of it. The text makes no general claims about the adaptation of written works into other formats or about whether ballets are typically considered faithful adaptations of such works. Choice C is incorrect because the text discusses the difficulty of translating only one poetic work—Pushkin’s Russian-language novel Eugene Onegin—into English and doesn’t consider whether English generally poses challenges for translators of poetic works of various languages. Moreover, the text focuses on the challenge presented by the Russian language’s unique patterns and flourishes, not a difficulty inherent to the English language. Choice D is incorrect because the text gives no indication of what most critics believe about Cranko’s adaptation of Eugene Onegin and instead presents the reaction of only one critic: Golden’s praise of Cranko’s ballet for capturing essential elements of the novel that have been “deemed untranslatable.” Nothing in the text suggests that most other critics would disagree with Golden’s positive view.","is_grid_in":false},{"source_id":"f9884b7a","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"medium","passage":"Zooarchaeologist Ophélie Lebrasseur and her team examined a fox skeleton discovered in 1991 at an archaeological site alongside artifacts of human habitation (like spear points) in central Argentina. Lebrasseur et al. determined that the fox was Dusicyon avus, an extinct species resembling a jackal, and radiocarbon dating placed the fox at the site at the same time as human inhabitants. (Indeed, the inhabitants may have deliberately buried the fox.) In addition, while wild foxes have a diet entirely made of meat, isotopic signatures of the skeleton’s teeth indicated that the fox’s diet, like that of the humans, was partly composed of plant material. Lebrasseur et al. therefore concluded that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"the humans who were alive at the same time as the fox most likely ate more meat than the fox did."},{"label":"B","text":"the fox may have been a companion animal of the humans who inhabited the site at the same time."},{"label":"C","text":"the fox had a diet more similar to that of jackals than to that of wild foxes."},{"label":"D","text":"the humans who were alive at the same time as the fox hunted using the spears whose points were also found at the site."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of Lebrasseur et al.’s examination of a fox skeleton found at an archaeological site in central Argentina. The text explains that the fox was found next to artifacts of human habitation, that radiocarbon dating indicated that it was at the site at the same time as human inhabitants, that humans at the site may have deliberately buried the fox, and that analysis indicated that the fox’s diet included meat and plant material, as the humans’ diet did, even though wild foxes eat only meat. The diet similarity, along with the fox’s location, the radiocarbon dating of its remains, and its possibly deliberate burial, suggests the fox was closely associated with the site’s human inhabitants—making it reasonable to conclude that the fox may have been a companion animal of those humans.\nChoice A is incorrect. The text indicates that both the fox and the human inhabitants at the site had a diet that included both meat and plant material, but the text gives no information about the relative proportions of meat in the fox’s and the humans’ respective diets. Choice C is incorrect. The text states that Dusicyon avus is an extinct species that resembled a jackal, but this description refers to the fox’s physical appearance, not its diet, and no information is given about what jackals eat. Choice D is incorrect. The last two sentences of the text focus on the possibility that the human inhabitants of the site may have given the fox a burial and that they and the fox may have eaten a similarly omnivorous diet—details pointing to the conclusion that the fox may have been a companion animal of the inhabitants. Thus, a conclusion about the hunting technology used by the inhabitants wouldn’t follow from the text.","is_grid_in":false},{"source_id":"b9a3941b","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"The single origin hypothesis of iron metallurgy posits that the craft originated in Anatolia (West Asia) circa 2200–2000 BCE before diffusing to other parts of the world, including Africa. Some proponents of the hypothesis argue that iron production technologies first arrived in North Africa through Carthage, where the earliest evidence of ironworking dates to approximately 800–600 BCE, before these technologies spread to sub-Saharan Africa over the following centuries. However, excavation of multiple sites on the Adamawa plateau in Central Africa conducted by Étienne Zangato and Augustin Holl uncovered evidence of iron workshops that may have been in operation as late as 900–750 BCE in Gbabari and as early as 2300–1900 BCE in Ôboui and Gbatoro. These findings suggest that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"iron production may have developed independently and relatively simultaneously in Anatolia and parts of Central Africa."},{"label":"B","text":"iron production technologies found in Gbabari likely derived directly from technologies transmitted from Anatolia, but those found in Ôboui and Gbatoro did not."},{"label":"C","text":"iron production technologies were likely transmitted from Anatolia to Central Africa via an alternate route than the one suggested by some proponents of the single origin hypothesis."},{"label":"D","text":"iron production may have originated in Anatolia much earlier than the available evidence currently indicates."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of the origin of iron metallurgy in Africa. The text explains that the single origin hypothesis suggests that iron metallurgy originated in Anatolia in West Asia circa 2200–2000 BCE and then spread to other parts of the world, with some advocates of this hypothesis arguing that the technology reached sub-Saharan Africa through the North African site of Carthage, where evidence of ironworking dates as far back as approximately 800–600 BCE. However, according to the text, researchers uncovered evidence of iron workshops at one Central African site, Gbabari, dating to circa 900–750 BCE—slightly before ironworking in Carthage—and at two other sites in Central Africa, Ôboui and Gbatoro, dating to as early as 2300–1900 BCE—significantly before ironworking spread to Carthage and roughly contemporaneous with its emergence in Anatolia. If iron metallurgy’s presence in Central Africa preceded its presence in North Africa, then this technology likely didn’t diffuse from Carthage to Central Africa. Moreover, this technology’s presence in Central Africa at roughly the same period when it originated in Anatolia would require its virtually immediate diffusion across the vast distances between the two regions—a development that would have been unlikely in the ancient world. Therefore, the researchers’ findings suggest that iron production may have developed independently and relatively simultaneously in Anatolia and parts of Central Africa.\nChoice B is incorrect. The findings presented in the text indicate that iron metallurgy may have been occurring in Ôboui and Gbatoro as early as 2300 BCE, which is earlier than it is thought to have emerged in Anatolia, and may have been occurring in Gbabari as early as 900 BCE, which is earlier than it is thought to have arrived in Carthage as it began diffusing into Africa. These earlier instances suggest that instead of diffusing from Anatolia to Central Africa, this technology independently emerged in Central Africa instead, spreading from the earlier iron production sites in the region to the later site. Moreover, the text doesn’t indicate any differences in the iron technologies used at the two earlier sites in Central Africa and the technology used at the later site that might suggest separate origins for iron metallurgy within the region. Choice C is incorrect because the text discusses findings that iron metallurgy may have been occurring in Central Africa at nearly the same time as or even slightly before it emerged in Anatolia, without time for it to have spread there from Anatolia—suggesting that the technology may have independently developed in parts of Central Africa. Thus, instead of suggesting an alternate route for the diffusion of iron production into Central Africa, the findings suggest that the technology didn’t arrive there by diffusion through an intermediate geographical region at all. Choice D is incorrect because, as the text explains, researchers found that iron metallurgy may have been practiced at a Central African site as early as 2300–1900 BCE—a chronological range that not only predates the technology’s spread from Anatolia to Carthage in North Africa circa 800–600 BCE but also overlaps with, and slightly precedes, the range assigned to its invention in Anatolia, 2200–2000 BCE. This finding suggests that instead of diffusing from Anatolia to Central Africa over a vast distance and a great expanse of time, this technology may have been independently invented by Central African civilizations at the same time as it was invented in Anatolia, if not slightly before then. Nothing in the text necessarily suggests that technology arose “much earlier” in Anatolia than the evidence there currently indicates.","is_grid_in":false},{"source_id":"45f66433","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"While mammals collectively exhibit the highest ratio of brain size to body size among vertebrates, a team led by paleontologist Ornella Bertrand demonstrates that for ten million years following the extinction of dinosaurs, that ratio in fact shrank for mammals as they evolved to fill newly vacated ecological niches and their bodies increased in size more rapidly than their brains. Competition for resources tends to favor intelligence and thus large, complex brains, but during this period, the abundance of resources relative to mammalian population numbers likely moderated competition and facilitated an increase in body size. Bertrand and her team reason that as population numbers swelled, competition intensified, creating conditions that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"heightened the advantage that large body size conferred on mammals in certain ecological niches."},{"label":"B","text":"restricted resources so drastically that mammals struggled to secure enough food to maintain large brain sizes."},{"label":"C","text":"favored an evolutionary increase in brain size relative to body size among mammals."},{"label":"D","text":"encouraged mammals with large brain sizes to adapt to a range of ecological niches."}],"correct_answer":"C","explanation":"Choice C is the best answer because it most logically completes the text’s discussion of the evolution of mammalian brain-to-body size ratios. As the text explains, mammals evolved to fill ecological niches left vacant by the dinosaurs’ extinction, and for the next ten million years, brain-to-body size ratios among mammals shrank as their bodies grew more rapidly than their brains. This decline was a natural outcome of resource abundance since increased competition for resources tends to favor intelligence and large brains, while decreased competition conversely favors large body size. Later, mammalian population sizes “swelled,” resulting in intensified competition—that is, a decrease in the abundance of resources relative to population sizes. Given the relationship established between resource availability and the ratio of brain size to body size, it can be inferred that around ten million years after the dinosaurs’ extinction, ecological conditions favored an evolutionary increase in brain size relative to body size among mammals—a reversal of the previous trend.\nChoice A is incorrect because, as the text explains, competition for resources tends to favor intelligence and large brains, not large body size. Thus, when mammalian population sizes swelled and competition among mammals intensified, the result would have been a decrease, not an increase, in the advantage that large body size conferred on mammals in certain ecological niches. Choice B is incorrect because the text frames competition for resources as a selective pressure favoring intelligence and brain size relative to body size. Thus, even if competition among mammals resulted in resource deprivation, these conditions would have favored adaptation toward larger brain-to-body size and consequently greater intelligence to compete more effectively for decreased resources. Choice D is incorrect. The period when mammals adapted to a range of ecological niches that is under discussion in the text is the ten million years immediately following the dinosaurs’ extinction, when competition for resources was low. Moreover, the text explains that increased competition tends to favor brain size, while decreased competition tends to favor body size. Thus, when competition increased, the logical outcome would have been an increase in brain size relative to body size among mammals, not a dispersal of large-brained mammals into new ecological niches, which the text states had already occurred under the very different conditions of low competition.","is_grid_in":false},{"source_id":"dd412b31","section":"reading_writing","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"medium","passage":"Online surveys are a common tool researchers use to collect information. These surveys are usually designed for use on personal computers (PCs), but more people are using smartphones to complete them than they are PCs. This shift in device usage may change how participants interact with online surveys. When researchers Jean Philippe Décieux and Philipp E. Sischka investigated, they found that PC users were more likely to multitask while taking surveys than smartphone users were, but PC users were also more likely to complete the surveys.","passage_html":null,"question_text":"Which choice best states the main idea of the text?","question_text_html":null,"choices":[{"label":"A","text":"People are choosing to take online surveys on smartphones more often than they are on PCs because smartphones are convenient."},{"label":"B","text":"Researchers are investigating why survey completion rates are higher on PCs than they are on smartphones, despite increased multitasking on PCs."},{"label":"C","text":"Researchers prefer online surveys to other ways of collecting information because they think online survey results are more reliable."},{"label":"D","text":"A study shows that the type of device people use to complete online surveys affects how they interact with these surveys."}],"correct_answer":"D","explanation":"Choice D is the best answer because it most accurately states the main idea of the text. The text opens by noting that online surveys are usually designed for PCs but that more people now use smartphones to take them—a shift, the text proposes, that may affect how participants interact with the surveys. The text then describes study findings—PC users were more likely to multitask but also more likely to complete surveys than smartphone users were—as evidence to illustrate the overall point that device type does indeed change how participants behave when responding to surveys. Thus, the text as a whole conveys the idea that according to a study, the type of device people use to complete online surveys affects how they interact with these surveys.\nChoice A is incorrect. Although the text notes that more people are using smartphones than PCs for surveys, it doesn’t indicate why people are making this choice, much less suggest that convenience is a factor in this shift. The text focuses on the consequences of the shift in device usage, not on its causes. Choice B is incorrect. Although the text reports that PC users were more likely to complete surveys than smartphone users were despite also being more likely to multitask while taking the surveys, it doesn’t frame the study as an inquiry into the reasons for these differences in completion rates. Instead, the text presents these findings to illustrate how device type affects survey participants’ interactions with online surveys. Choice C is incorrect. Although the text states that online surveys are commonly used in research, the text doesn’t discuss whether researchers prefer online surveys over other data collection methods, nor does it indicate that online surveys are more reliable than alternative methods. Rather, the text focuses on how different devices affect the way participants interact with online surveys.","is_grid_in":false},{"source_id":"9c199797","section":"reading_writing","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","passage":"The presence of other individuals of the same species has been observed to mitigate stress in highly social mammals. To investigate whether this phenomenon, known as social buffering, also occurs in reptiles, researchers led by Chelsea E. Martin monitored stress responses in wild southern Pacific rattlesnakes (Crotalus helleri) in three experimental treatments: when alone, with a rope, and with a companion C. helleri. The researchers compared the percent change between baseline and peak heart rate in response to a (harmless) disturbance, with higher values indicating higher stress levels.","passage_html":null,"question_text":"Which finding, if true, would most directly support the idea that social buffering occurs among C. helleri?","question_text_html":null,"choices":[{"label":"A","text":"The average percent change in heart rate was lower among C. helleri with a companion than among solitary C. helleri and C. helleri with a rope."},{"label":"B","text":"Average peak heart rates were highest among solitary C. helleri, but no differences were observed in average peak heart rates between C. helleri with a companion and C. helleri with a rope."},{"label":"C","text":"C. helleri with a companion displayed a lower average baseline heart rate and lower average peak heart rate than did solitary C. helleri or C. helleri with a rope."},{"label":"D","text":"Solitary C. helleri had higher average baseline heart rates than did C. helleri in the other treatments, but the average percent change in heart rate was smaller among solitary C. helleri than among C. helleri with a companion."}],"correct_answer":"A","explanation":"Choice A is the best answer because it presents a finding that, if true, would most directly support the idea that social buffering—the mitigation of stress by the presence of other animals of the same species—occurs among C. helleri. According to the text, the researchers quantified the amount of stress in C. helleri as the percent change between baseline and peak heart rate, with higher values indicating greater stress. The text also describes the researchers’ three treatments: snakes alone, snakes with a rope, and snakes with a companion C. helleri. If the average percent change in heart rate was lower among snakes with a companion than among either solitary snakes or snakes with a rope, that would indicate two things: snakes accompanied by a companion experienced less stress than they did when alone, and the reduction wasn’t simply the result of any object being present, since the rope didn’t produce the same effect. Together, these results would directly support the conclusion that the companion’s presence mitigated stress, as the social buffering hypothesis predicts.\nChoice B is incorrect because the finding compares peak heart rates among the three treatments rather than the percent change in heart rates among those treatments. The finding also indicates that snakes with a companion and snakes with a rope showed no differences in peak heart rates. If a rope produced the same effect as a companion did, that would suggest that the effect, whatever its extent, isn’t caused specifically by the presence of another individual of the same species and so wouldn’t support the social buffering hypothesis. Choice C is incorrect because the finding addresses absolute baseline and peak heart rates rather than the percent change between them, which is the measure of stress response the researchers used. Lower absolute heart rates in companion-present snakes could reflect a generally calmer state but wouldn’t show that the stress response to the disturbance was reduced and so wouldn’t directly demonstrate social buffering as defined in the study. Choice D is incorrect because the finding states that the percent change in heart rate was smaller among solitary snakes than among snakes with a companion, which would indicate a smaller stress response when alone. This pattern would directly contradict the social buffering hypothesis rather than support it. Furthermore, a comparison of baseline heart rates would be immaterial for determining whether social buffering occurs among C. helleri because the text indicates that a change in heart rate, not average baseline heart rate, indicates a stress response.","is_grid_in":false},{"source_id":"27ea642e","section":"reading_writing","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","passage":"As juveniles, all white-necked jacobin hummingbirds display vibrantly blue head plumage; when they enter adulthood, males retain these blue feathers and most females molt to a drab green hue. However, 28% of adult female jacobins remain identical in coloration to juveniles and adult males. Based on field observations in Panama, a team of researchers reports that while adult males show a clear preference in mate selection for adult females with drab green feathers, they also engage in more antagonistic behavior toward those adult females than toward blue-feathered adult females when competing for resources. Therefore, the team hypothesizes that ______","passage_html":null,"question_text":"Which choice most logically completes the text?","question_text_html":null,"choices":[{"label":"A","text":"adult male jacobins do not act antagonistically toward juvenile jacobins with blue head plumage when competing for resources."},{"label":"B","text":"the percentage of blue-feathered females will increase until fewer than half of adult female jacobins are green-feathered."},{"label":"C","text":"the occurrence of blue head plumage in adult female jacobins is driven by one or more factors not associated with mate attraction."},{"label":"D","text":"coloration prevents green-feathered adult female jacobins from distinguishing between adult males and blue-feathered adult females."}],"correct_answer":"C","explanation":"Choice C is the best answer because it most logically completes the text’s discussion of researchers’ observations of white-necked jacobin hummingbird females that retain blue head plumage into adulthood. The text indicates that even though adult males show a clear preference in mate selection for adult females with drab green feathers, a significant percentage of adult females (28%) retain blue head plumage. Critically, the text also notes that the mating advantage conferred on adult females by green head plumage is offset by the fact that when competing for resources, adult males behave more antagonistically toward green-feathered adult females than toward blue-feathered ones. Given this discrepancy in the males’ behavior, it is reasonable to hypothesize that the occurrence of blue head plumage in adult females is driven by factors not associated with mate attraction—specifically, reduced antagonism during resource competition.\nChoice A is incorrect because the antagonistic behavior discussed in the text is that displayed by adult male jacobins toward blue-feathered and green-feathered adult females, not toward juveniles. The text doesn’t discuss the behavior of adult males toward juveniles. Choice B is incorrect. Although the text cites the current percentage (28%) of female white-necked jacobin hummingbirds that retain blue plumage into adulthood, it doesn’t make predictions about future changes in the proportion of blue to green plumage in this species or provide information supporting such a prediction. Choice D is incorrect because the text doesn’t discuss the perceptual abilities of green-feathered adult females or whether they can distinguish between adult males and blue-feathered adult females. Instead, the text focuses on adult male behavior—namely, mate selection and antagonism toward adult females.","is_grid_in":false},{"source_id":"dd0aada1","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","passage":"Science fiction has long served as a ______ real-world technological advancements. Indeed, from Jules Verne’s 1865 novel From the Earth to the Moon inspiring developments in aerospace engineering to the television show Star Trek sparking the design of the ancestor of today’s smartphones, these narratives have spurred many actual innovations.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"constraint to"},{"label":"B","text":"sponsor of"},{"label":"C","text":"catalyst of"},{"label":"D","text":"diversion from"}],"correct_answer":"C","explanation":"Choice C is the best answer because it most logically completes the text’s discussion of science fiction’s relationship to real-world technological advancements. In this context, “catalyst of” means something that prompts the development of. The text indicates that science fiction narratives have “spurred many actual innovations,” giving as examples Verne’s From the Earth to the Moon “inspiring” aerospace engineering developments and Star Trek “sparking” the design of early analogues of smartphones. Thus, this context supports the idea that science fiction has prompted the development of, or served as a catalyst of, real-world technological advancements.\nChoice A is incorrect because saying that science fiction has served as a “constraint to,” or limitation on, real-world technological advancements would contradict the text, which indicates that science fiction has inspired technological innovation rather than inhibited it. Choice B is incorrect because describing science fiction as a “sponsor of,” or an entity who takes on responsibility for, real-world technological advancements wouldn’t make sense in context. A sponsor provides material support for an undertaking, often by providing funds for the undertaking or by overseeing its management, but the text describes science fiction as inspiring or sparking ideas for innovation, not as financially backing technological development or taking direct responsibility for overseeing it. Choice D is incorrect because in this context, a “diversion from” would mean either a distraction from or a deviation from, which contradicts the text’s examples of science fiction inspiring real-world technological advancements. It therefore wouldn’t make sense to say that science fiction has distracted people from such advancements or that the innovations science fiction depicts deviate from actual innovations.","is_grid_in":false},{"source_id":"1917ba9a","section":"reading_writing","domain":"Craft and Structure","skill":"Cross-Text Connections","difficulty":"hard","passage":"Text 1\nMany teleost fish species are protogynous, meaning that fertile females can become fertile males. One model holds that protogyny occurs when body size confers a greater reproductive advantage on males than on females. In teleost fish, body size is irrelevant to female reproduction, but among males (which tend to be larger than females), only individuals comparatively large enough to defend territory reproduce. An individual could thus maximize its lifetime reproductive success by staying female when small and becoming male upon reaching a critical size threshold.\nText 2\nInvestigating protogyny in teleost fish, Alexander Goikoetxea and colleagues placed captured spotty wrasses of typical size distributions into two mixed-sex tanks. During the breeding season, they removed all males from tank 1 but none from tank 2. They observed that sexual change began in 81 percent of females in tank 1 but in no females in tank 2.","passage_html":null,"question_text":"Based on the texts, which choice best explains the difference in the outcomes of the two tanks in Goikoetxea and colleagues’ experiment (Text 2) using the model presented in Text 1?","question_text_html":null,"choices":[{"label":"A","text":"Once the males were removed from tank 1, territories in the tank were undefended and thus even small females could maximize their reproductive success by becoming male and taking over those territories, whereas only the largest females in tank 2 could successfully take over territories due to the ongoing presence of males in the tank."},{"label":"B","text":"With no males left in tank 1, females were potentially large enough to defend territory as males and thus could gain an advantage by becoming male at their current size, whereas females in tank 2 may not have been large enough to outcompete the males in the tank and thus would have greater reproductive success by remaining female."},{"label":"C","text":"Differences in body size among the females in tank 1 became irrelevant to reproductive success once the males were removed, thereby eliminating any advantage to becoming male, whereas the ongoing presence of males in tank 2 made differences in body size among the females in that tank relevant to their reproductive success."},{"label":"D","text":"Since all males were removed from tank 1, the females in the tank could not reproduce regardless of their size and thus some became male, whereas the presence of males in tank 2 meant that females in that tank could reproduce without first becoming male and thus they remained female."}],"correct_answer":"B","explanation":"Choice B is the best answer because it correctly applies the model presented in Text 1 to explain the different outcomes in the two tanks described in Text 2. Text 1 begins by explaining that fertile female teleost fish will sometimes become fertile males through protogyny. The model, or explanation, of protogyny advanced in Text 1 holds that among female teleost fish, size doesn’t confer any reproductive advantage, but among male teleost fish, “only individuals comparatively large enough to defend territory reproduce”—in other words, there is a direct relationship between relative body size and reproductive success, but only among male fish. Text 1 concludes by saying that, according to this model, individuals can maximize their reproductive success by “staying female when small” (when size has no relevance to reproduction) and only becoming male when they reach a certain size threshold by becoming large enough relative to other male fish to be able to defend territory. In sum, according to the model, whether protogyny is advantageous depends on a female’s body size relative to the males currently present. Text 2 describes an experiment in which fish of “typical size distributions” (meaning, size distributions consistent with Text 1’s note about the tendency of males to be larger than females) were placed in two tanks. Applying Text 1’s model, once the males (that is, the typically larger fish) were removed from tank 1, the remaining females would no longer be at a size disadvantage and could potentially defend territory as males at their current size, making sex change advantageous for some of the fish in tank 1. This would therefore explain the finding that 81 percent of female fish began changing into males. In tank 2, however, the continued presence of larger males meant that on average, females would not be large enough to outcompete the males for territory and would therefore have greater reproductive success by remaining female. In this way, the size-advantage model presented in Text 1 would also account for why no fish changed sex in tank 2.\nChoice A is incorrect because it claims that “even small females” could succeed as males once territories were undefended, contradicting Text 1’s emphasis on there being a “critical size threshold” for male reproductive success, wherein only male fish who were sufficiently large to defend territory would have a reproductive advantage. Under this model, small females would have more reproductive success by remaining female than by becoming male and being unable to compete with larger fish for territory. Additionally, this choice’s claim about tank 2—that “only the largest females” could take over territories—implies either that females defend territory (when the model in Text 1 makes no such claim) or that at least some females were sufficiently large to change sex and compete for territory with fish that began the experiment as males, yet the results show that no females in tank 2 did so. Choice C is incorrect. Not only is it based on a flawed understanding of the model presented in Text 1, it flatly contradicts the experimental results summarized in Text 2. While Text 1 clearly states that body size is irrelevant to female reproductive success, choice C states that the presence of males in tank 2 made differences in body size relevant to the females’ reproductive success. This choice also claims that the removal of males from tank 1 eliminated any advantage to becoming male, yet the researchers reported that 81 percent of females in tank 1 began changing sex. Choice D is incorrect because it doesn’t use the model proposed in Text 1 to explain the findings described in Text 2. It is common sense that a certain number of male fish are required for reproduction to occur in tank 1, but the model presented by Text 1 focuses on the individual reproductive benefits of protogyny, not on its potential to benefit the population by maintaining a favorable sex ratio.","is_grid_in":false},{"source_id":"4d13a0c0","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"Before the Mariner 2 mission completed a successful flyby of Venus in 1962, astronomers’ ideas about the planet were little more than ______. Venus’s atmosphere is so thick that Earth-based observations had yielded very little information about the planet.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"summations"},{"label":"B","text":"conjectures"},{"label":"C","text":"conclusions"},{"label":"D","text":"exemplifications"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of pre-Mariner 2 ideas about Venus. In this context, “conjectures” means guesses or inferences formed without sufficient evidence. The text indicates that before the successful 1962 flyby, Earth-based observations of Venus had produced “very little information” because of the planet’s thick atmosphere. The limited scope of astronomers’ earlier knowledge of Venus is also emphasized by the text’s description of their ideas as being “little more than” something before the flyby. This context conveys that before Mariner 2 flew close to Venus, astronomers lacked the evidence needed for their ideas about the planet to be much more than conjectures, or guesses.\nChoice A is incorrect. In this context, “summations” would be final conclusions reached by putting all information together. Because the text emphasizes that very little information about Venus was available before the 1962 flyby, it wouldn’t make sense to describe astronomers’ pre-Mariner 2 ideas about Venus as summations; the text suggests that astronomers didn’t have enough information to draw solid conclusions about Venus. Choice C is incorrect. In this context, “conclusions” would be reasoned final judgments or outcomes. Because the text emphasizes that very little information about Venus was available before the 1962 flyby, it wouldn’t make sense to describe astronomers’ pre-Mariner 2 ideas about Venus as conclusions; the text suggests that astronomers didn’t have what they would have needed to make informed judgments about Venus. Choice D is incorrect because it wouldn’t make sense to describe astronomers’ pre-Mariner 2 ideas about Venus as “exemplifications,” or examples that illustrate something; people’s ideas about a subject are the ideas themselves, not illustrations. Further, the text emphasizes that the astronomers had little information before 1962, suggesting they didn’t have much to work with to form examples.","is_grid_in":false},{"source_id":"49d3dc62","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","passage":"Scientists studying marine ecosystems were surprised by the extent of internal carbon recycling by red coralline algae. While some ______ of carbon was expected, the scientists found that the algae reabsorb nearly 40% of the carbon dioxide they produce during calcification processes and harness it for photosynthesis.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"imitation"},{"label":"B","text":"supply"},{"label":"C","text":"examination"},{"label":"D","text":"reuse"}],"correct_answer":"D","explanation":"Choice D is the best answer because it most logically completes the text’s discussion of internal carbon recycling by red coralline algae. In this context, “reuse” means using something again rather than disposing of it as waste. The text describes scientists’ surprise at “the extent of” internal carbon recycling by the algae, characterizing this finding as a departure from the more limited degree of activity that the scientists had expected to observe. The text goes on to explain that, in contrast to the scientists’ expectation that “some” carbon would be affected by the activity being described, the algae were found to “reabsorb nearly 40% of the carbon dioxide they produce during calcification processes and harness it for photosynthesis,” a specific example of their extensive capacity for taking in carbon and recycling, or reusing, it. Because the scientists thought the algae would use some of their own carbon dioxide again but were surprised by the extent of this activity, the context supports the idea that some reuse of carbon was expected.\nChoice A is incorrect because it wouldn’t be logical in context to state that some “imitation,” or reproduction of something else, of carbon was expected. The text discusses the algae’s reabsorption and reuse of the carbon dioxide they produce, not any process by which carbon copies or reproduces something. Choice B is incorrect because stating that some “supply,” or available amount, of carbon was expected wouldn’t fit the contrast established within the text. The text contrasts the scientists’ expectations about carbon recycling in algae with their actual observations, noting that the scientists anticipated a more limited version of the recycling process they observed. This context doesn’t suggest that the scientists merely anticipated the presence of some amount of carbon. Choice C is incorrect because it wouldn’t be logical in context to state that some “examination,” or careful inspection, of carbon was expected. The text isn’t discussing scientists’ inspection of carbon, and carbon itself isn’t something that engages in inspection. Rather, the text focuses on the algae’s reabsorption and reuse of the carbon dioxide they produce.","is_grid_in":false},{"source_id":"153aaae2","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"hard","passage":"Guadalupe Romero Villanueva et al. conducted radiocarbon analysis of paint used in rock art at the Patagonian archaeological site Cueva Huenul 1, revealing that images of a comblike motif date to as early as 8,000 years ago, predating other paintings in the region by several millennia. The motif was subsequently reproduced multiple times at the site over the next 3,000 years, a period coinciding with extremely arid conditions and slightly negative population growth. The motif may therefore have functioned to help preserve cultural knowledge during a time of ecological and demographic stress.","passage_html":null,"question_text":"Which choice best describes the function of the underlined portion in the text as a whole?","question_text_html":null,"choices":[{"label":"A","text":"It identifies a consideration that factored into an interpretation of the rock art at Cueva Huenul 1 that is presented in the text."},{"label":"B","text":"It provides context that informs the text’s claim about why the peoples of Patagonia chose Cueva Huenul 1 as a culturally significant site."},{"label":"C","text":"It emphasizes the historical conditions that explain why production of the painted motif described in the text abruptly ceased after 3,000 years of continued use."},{"label":"D","text":"It explains the environmental circumstances that account for the rarity of rock art dating to the same period as the motif discussed in the text."}],"correct_answer":"A","explanation":"Choice A is the best answer because it most accurately describes the function of the underlined portion in the text as a whole. The text first reports that a comblike motif at Cueva Huenul 1 dates to 8,000 years ago and was reproduced over the next 3,000 years. The underlined portion then indicates that this 3,000-year period corresponds to a span of very dry environmental conditions and a slowly declining human population in the area. The text then suggests that the chronological overlap between use of the comblike motif and the ecological and demographic conditions might suggest that what the motif is meant to communicate is related to those specific factors. Thus, the underlined portion identifies a consideration that factored into an interpretation of the rock art at Cueva Huenul 1 that is presented in the text.\nChoice B is incorrect. Although the text suggests that Cueva Huenul 1 may have been an important site because it enabled the peoples of Patagonia to preserve cultural knowledge, nothing in the text addresses why they chose the site for their paintings. Choice C is incorrect because the text indicates that the motif was reproduced over a period of 3,000 years (beginning 8,000 years ago) without directly addressing the cessation of its use. Furthermore, nothing in the text suggests that the motif was abandoned abruptly. Choice D is incorrect because nothing in the underlined portion or the text as a whole addresses the rarity of rock art during the period in question.","is_grid_in":false},{"source_id":"37c481f8","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"hard","passage":"The following text is from Rachel Heng’s 2023 novel The Great Reclamation. Ah Boon is fishing off the coast of Singapore.\nWhen he pulled up the nets, they contained only one kind of fish—black pomfrets, the flat diamonds of their bodies slick in the morning light. This uniformity did not surprise him; over the years, he’d learned that the waters here were temperamental. They could be relied upon for a good catch, but from time to time threw up only prawns or squid, and other times colorful varieties of fish that weren’t even supposed to be found in this region. He’d grown to accept the unpredictability, embracing it as a game to be played, like the reading of tea leaves or the grooves of a palm.\n©2023 by Rachel Heng","passage_html":null,"question_text":"Taken together, the three underlined portions most clearly serve which function in the text as a whole?","question_text_html":null,"choices":[{"label":"A","text":"They provide examples of what Ah Boon most frequently catches in the area."},{"label":"B","text":"They illustrate the changeable nature of the fishing grounds where Ah Boon is."},{"label":"C","text":"They emphasize the wide variety of sea creatures that Ah Boon has caught on this particular fishing trip."},{"label":"D","text":"They underscore Ah Boon’s lack of surprise at seeing sea creatures that aren’t usually found in the region."}],"correct_answer":"B","explanation":"Choice B is the best answer because it most accurately describes the function that the three underlined portions serve in the text as a whole. The text states that Ah Boon’s nets contained only one kind of fish and explains that he is unsurprised because the waters are “temperamental.” The three underlined portions name different types of catch yielded by the waters on different occasions, demonstrating how the catch varies unpredictably. Thus, taken together, the three underlined portions illustrate the changeable nature of the waters where Ah Boon fishes.\nChoice A is incorrect because the text does not indicate which types of catch are most frequent; it describes the waters as unpredictable and varying over time. Instead of illustrating frequency, the underlined portions that mention different kinds of sea creatures illustrate variability. Choice C is incorrect because the text states that on this particular trip, Ah Boon caught only one kind of fish—black pomfrets. The other two underlined portions refer to catches from other occasions, not from the present trip. Instead of emphasizing variety on one trip, the underlined portions illustrate the unpredictability of the waters over time. Choice D is incorrect. Although the text notes that Ah Boon is unsurprised by his catch of black pomfrets, only one of the three underlined portions—“colorful varieties of fish”—refers to creatures not usually found in the region. The underlined portions collectively convey the range of what Ah Boon has caught while fishing in the waters, illustrating their changeable nature rather than underscoring Ah Boon’s emotional response.","is_grid_in":false},{"source_id":"0e033f9b","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"Among stock-market investors, the practice of diversification, or distributing investment funds across many different companies in many different industries, is regarded as ______ since it protects investors from major losses if the value of one particular company or industry sector falls.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"contentious"},{"label":"B","text":"prudent"},{"label":"C","text":"unworkable"},{"label":"D","text":"optimistic"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of how stock-market investors regard diversification. In this context, “prudent” means showing sensible judgment. The text defines diversification as the practice of spreading investment funds across many different companies and industries and explains that this practice “protects investors from major losses” when a particular company or sector loses value. This context supports the idea that diversification is regarded as prudent—that is, as a sensible strategy because of the financial protection it provides.\nChoice A is incorrect because describing diversification as “contentious,” or likely to cause disagreement, would contradict the text, which presents diversification as a practice valued by investors for its protective benefits, not as one that prompts dispute. Choice C is incorrect because describing diversification as “unworkable,” or unable to function effectively, would contradict the text, which indicates that diversification successfully protects investors from major losses. Choice D is incorrect because describing diversification as “optimistic,” or expressing confidence in a positive outcome, wouldn’t make sense in context. The text presents diversification as a defensive strategy designed to limit losses, not as one expressing confidence about future gains.","is_grid_in":false},{"source_id":"15daaded","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"Among saltwater fish species, there is a clear association between habitat latitude and morphological variety. While tropical species are ______ deep-bodied physical forms (body shapes that are laterally compressed but vertically extended), polar and temperate species are highly dispersed across the morphological spectrum.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"authenticated by"},{"label":"B","text":"habituated to"},{"label":"C","text":"contemporary with"},{"label":"D","text":"concentrated among"}],"correct_answer":"D","explanation":"Choice D is the best answer because it most logically completes the text’s discussion of the relationship between habitat latitude and body shape in saltwater fish species. In this context, “concentrated among” means largely confined to. The text sets up a contrast between tropical species, which are generally characterized by a single shape—deep-bodied forms—and polar and temperate species, which are “highly dispersed across the morphological spectrum” (meaning they exhibit a wide range of body shapes). This context supports the idea that tropical species are concentrated among deep-bodied physical forms—that is, largely confined to this single morphological category rather than spread across many.\nChoice A is incorrect because saying that tropical species are “authenticated by,” or proven genuine by, deep-bodied physical forms wouldn’t make sense. Instead, the text describes the typical morphology (body shape) of tropical fish species and how that differs from the typical morphologies of polar and temperate fish species. Choice B is incorrect because saying that tropical species are “habituated to,” or accustomed through repeated exposure to, deep-bodied physical forms wouldn’t make sense. Instead, the text describes the typical morphology (body shape) of tropical fish species and how that differs from the typical morphologies of polar and temperate fish species. Choice C is incorrect because saying that tropical species are “contemporary with,” or existing at the same time as, deep-bodied physical forms indicates that the species exist at the same time as their body shapes do, which, if it is a meaningful statement at all, is at best trivially true and unrelated to the text’s discussion of the typical morphology (body shape) of tropical fish species and how that differs from the typical morphologies of polar and temperate fish species.","is_grid_in":false},{"source_id":"8af926b1","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"hard","passage":"Despite potential independent confirmation, the apparent detection in 2020 of phosphine (PH3)—a gas that on Earth almost exclusively derives from biological sources—in Venus’s cloud deck remains controversial, in part because Venus is thought to be uninhabitable. To evaluate such a finding’s plausibility, William Bains et al. modeled multiple abiotic PH3 pathways, including geochemical, atmospheric, and photochemical reactions, but none adequately explain the observed levels of PH3. If Venusian PH3 does exist, it would indicate insufficiencies in the current consensus on Venus’s chemistry.","passage_html":null,"question_text":"Which choice best describes the overall structure of the text?","question_text_html":null,"choices":[{"label":"A","text":"It outlines recent efforts to confirm the presence of a particular gas in Venus’s atmosphere, summarizes a research team’s evaluations of those efforts’ methodological shortcomings, and then explains why that team remains skeptical of the gas’s future detection."},{"label":"B","text":"It explains why the consensus view of a particular gas in Venus’s atmosphere has recently become controversial, expands on a scientific team’s reasons for questioning that consensus, and then suggests that future observations of Venus’s atmosphere will likely be needed to settle the controversy."},{"label":"C","text":"It introduces an unexpected observation of a particular gas in Venus’s atmosphere, presents an effort to investigate possible mechanisms that could explain that observation, and then notes an implication of that investigation’s findings."},{"label":"D","text":"It compares the levels of a particular gas on Venus and Earth, sketches the chemical processes that account for differences in these levels, and then addresses some of the practical challenges of studying the presence of this gas on Venus more closely."}],"correct_answer":"C","explanation":"Choice C is the best answer because it most accurately describes the overall structure of the text. The text begins by discussing the detection of phosphine gas in Venus’s atmosphere, indicating that it is unexpected because on Earth, phosphine derives from biological sources, and Venus is thought to be uninhabitable, thereby lacking in biological sources. The text then presents the effort by Bains et al. to determine whether one or more abiotic (nonbiological) pathways could explain the observed levels of phosphine on Venus, noting that none could. Finally, the text notes an implication: if phosphine exists on Venus, its presence would indicate that our current understanding of chemical processes on Venus that could produce it is inadequate. Thus, the text introduces an unexpected observation about Venus’s atmosphere, presents an effort to investigate mechanisms related to that observation, and notes an implication of that effort’s findings.\nChoice A is incorrect. The text starts by mentioning that phosphine has been detected in Venus’s atmosphere. Rather than discuss whether the presence of phosphine on Venus can be confirmed, the text focuses on the efforts of one team of researchers, Bains et al., who are trying to explain the observed amount of phosphine on Venus. Furthermore, the text doesn’t suggest that the research team was skeptical about the presence of phosphine on Venus. Choice B is incorrect because, rather than indicating a consensus view about the phosphine detected on Venus, the text focuses on the fact that the detection “remains controversial,” a framing that suggests the controversy is not a new phenomenon. The text also doesn’t suggest that future atmospheric observations would be needed to settle the controversy. There is no consensus view about the presence of phosphine on Venus. Choice D is incorrect because the text does not compare levels of phosphine on Venus with levels on Earth, nor does it address practical challenges of studying the gas on Venus.","is_grid_in":false},{"source_id":"7d60a322","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"easy","passage":"Zygomorphic (bilaterally symmetric) flowers remain open and functional on average 1.1 days longer than actinomorphic (radially symmetric) flowers do. Ruby E. Stephens and colleagues claim that this extended period could be ______ the relatively small pool of potential pollinators available to zygomorphic flowers and the greater chance at successful pollination that remaining open affords them.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"analogous to"},{"label":"B","text":"converted by"},{"label":"C","text":"attributed to"},{"label":"D","text":"magnified by"}],"correct_answer":"C","explanation":"Choice C is the best answer because it most logically completes the text’s discussion of why zygomorphic flowers (those with bilateral symmetry) remain open longer than actinomorphic flowers (those with radial symmetry). In this context, “attributed to” means explained as a consequence of. The text indicates that compared with actinomorphic flowers, zygomorphic flowers have a small pool of potential pollinators and that remaining open therefore increases their chances of being pollinated successfully. This would be a reasonable explanation for why zygomorphic flowers remain open on average 1.1 days longer than actinomorphic flowers do. Thus, in context it would be most logical to say that zygomorphic flowers’ extended opening period can likely be attributed to the factors discussed in the text.\nChoice A is incorrect because saying that the extended period in which zygomorphic flowers remain open could be “analogous to,” or comparable to, these flowers’ limited pollinator pool and the fact that remaining open increases their chances of pollination wouldn’t make sense in context. The text presents these factors as a possible explanation for the extended period, not as something that the extended period resembles in some way. Choice B is incorrect because saying that the extended period could be “converted by,” or transformed by, the limited pollinator pool and the increased pollination chances wouldn’t make sense in context. The text presents these factors as a possible cause of the extended period, not as forces that change the period into something else. Choice D is incorrect because in this context, “magnified by” would mean exaggerated by or made more extreme or intense by, neither of which would make sense. The text presents zygomorphic flowers’ limited pollinator pool and the fact that this might require remaining open for longer to increase chances of pollination as factors that could explain why these flowers remain open for extended periods; nothing in the text suggests these are factors that could exaggerate an already-extended period (that is, make the period seem greater or more important than it actually is), or that the extended period is in some way extreme or intense.","is_grid_in":false},{"source_id":"089b0b41","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"easy","passage":"Bing Xie and her team have discovered that plains zebras make at least four types of vocalizations: “snorts,” “soft snorts,” “squeals,” and “quagga quagga” calls. The researchers used machine-learning algorithms to ______ recorded vocalizations according to type, finding that snorts vary across individual zebras, while squeals are more uniform across zebra populations.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"categorize"},{"label":"B","text":"extend"},{"label":"C","text":"collapse"},{"label":"D","text":"suppress"}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of how Bing Xie and her team analyzed plains zebra vocalizations. In this context, “categorize” means to sort into groups based on shared characteristics. The text states that Xie and her team discovered that the vocalizations of plains zebras can be grouped into at least four distinct types: “snorts,” “soft snorts,” “squeals,” and “quagga quagga” calls. According to the text, the team also found that whereas snorts vary from zebra to zebra, squeals are more consistent across zebra populations. The text indicates that the researchers used machine-learning algorithms to arrive at these findings. This context supports the idea that the researchers used the algorithms to categorize recorded vocalizations.\nChoice B is incorrect because in this context, “extend” would mean to make longer or greater in size. The text discusses the researchers’ use of machine-learning algorithms to study recorded zebra vocalizations and identify patterns among the different types of calls that the researchers had recorded, not to lengthen or increase the size of the recordings. Choice C is incorrect because in this context, “collapse” would mean to break down or combine into a smaller form. The text indicates that the researchers used machine-learning algorithms as part of a process that yielded findings about distinct types of zebra vocalizations, suggesting that the researchers used the algorithms to distinguish among vocalization types, not to combine them. Choice D is incorrect because in this context, “suppress” would mean to hold back or eliminate. The text indicates that the researchers used machine-learning algorithms as part of a process that yielded findings that zebra vocalizations can be classified into four distinct types, not that the researchers used the algorithms to hold back or eliminate the vocalizations themselves.","is_grid_in":false},{"source_id":"2ec0e43e","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"medium","passage":"Alternative-history fiction is a subgenre of science fiction in which plots center on “what if?” questions. What if India had started the Industrial Revolution? What if Soviet cosmonauts had been first to land on the moon? Speculative counterfactuals like these can be great fodder for stories, but they’re also commonly deployed by academic historians to better understand factors influencing historical events. Well-realized and coherent alternative-history stories can thus complement historians’ speculations about the past.","passage_html":null,"question_text":"Which choice best describes the function of the underlined portion in the text as a whole?","question_text_html":null,"choices":[{"label":"A","text":"It illustrates how academic historians have influenced writers of alternative-history fiction."},{"label":"B","text":"It acknowledges counterfactual questions that academic historians have largely overlooked."},{"label":"C","text":"It provides examples of the types of scenarios addressed in alternative-history fiction."},{"label":"D","text":"It indicates specific ideas that were first raised by writers of alternative-history fiction and that subsequently inspired scholarship by academic historians."}],"correct_answer":"C","explanation":"Choice C is the best answer because it best describes the function of the underlined portion in the text as a whole. The text begins by defining alternative-history fiction as a subgenre centered on “what if?” questions. The underlined portion then poses two such questions—one about India starting the Industrial Revolution and one about Soviet cosmonauts landing on the moon first. The sentence that follows refers to the two questions as “speculative counterfactuals like these,” confirming that the underlined questions serve as examples. Thus, the underlined portion provides examples of the types of scenarios addressed in alternative-history fiction.\nChoice A is incorrect because the underlined portion provides examples of “what if?” scenarios, not evidence of a line of influence from academic historians to fiction writers; nothing in the text addresses such a relationship. The text mentions academic historians only in the context of how alternative-history stories can supplement their work. Choice B is incorrect because the text states that counterfactuals like the ones presented in the underlined portion are “commonly deployed by academic historians,” indicating engagement with such questions rather than neglect. Instead of acknowledging overlooked questions, the underlined portion provides examples of the types of scenarios addressed in alternative-history fiction. Choice D is incorrect because nothing in the text indicates that the specific questions in the underlined portion originated with fiction writers or that they subsequently inspired academic historians. Instead, the underlined portion simply illustrates the kind of “what if?” questions typical of the alternative-history fiction subgenre.","is_grid_in":false},{"source_id":"70e6af39","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"hard","passage":"To produce batik, an Indonesian textile that originated as early as the 6th century CE, an artist creates patterns on fabric by skillfully applying wax to the surface and then dyeing it. Traditionally, the artist draws on the cloth using a canting, a pen-shaped tool that applies wax in fine lines or dots. To expedite this laborious process, the cap, a copper stamp that applies preset wax patterns, was introduced. Although the cap made the process of producing batiks much quicker, the canting is often preferred because it results in unique pieces.","passage_html":null,"question_text":"Which choice best describes the overall structure of the text?","question_text_html":null,"choices":[{"label":"A","text":"It introduces a traditional type of textile, suggests that it is a variation of an even older type of textile, and then explains a significant difference in how those types of textiles are produced."},{"label":"B","text":"It establishes how a textile production technique originated, indicates how the technique has changed over time, and then suggests that renewed interest in the original technique is growing."},{"label":"C","text":"It presents a method of textile production, identifies two approaches to that method, and then addresses the relative advantage of each approach."},{"label":"D","text":"It conveys admiration of a certain style of textile, emphasizes the level of skill needed to produce the textile, and then urges broader recognition of the skill involved in producing the textile."}],"correct_answer":"C","explanation":"Choice C is the best answer because it most accurately describes the overall structure of the text. The text begins by describing batik fabric and the method for producing it—designs are applied in wax on the fabric, after which the fabric is dyed. The text then indicates that a “canting” (a pen-shaped tool) is traditionally used to apply the wax finely in lines or dots, and that “the cap” (a copper stamp of an entire pattern) is another, faster way to apply the wax design. Finally, the text states that the cap has the advantage of making batik production quicker, whereas a canting tends to produce a more unique design, which often makes a batik created using a canting more desirable than a mass-produced one. Thus, the text presents a method of textile production, identifies two approaches to that method, and addresses the relative advantage of each approach.\nChoice A is incorrect. Although the text describes making the textile batik with a canting and with the cap, both approaches are for making the same type of textile (batik). No other type of textile is mentioned in the text. Choice B is incorrect. Although the text indicates when batik originated (perhaps the 6th century CE), it doesn’t describe how it originated. And although the text indicates that a batik created using a canting “is often preferred” over mass-produced batiks, nothing in the text suggests that this preference is a recent trend. Choice D is incorrect. Although the text indicates that the batik artists “skillfully” apply the wax designs that create the batik patterns, the overall discussion in the text describes factual aspects of the process of batik production without seeming to advocate for greater recognition of the art form.","is_grid_in":false},{"source_id":"6557f7fc","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"The following text is adapted from Edith Wharton’s 1911 novella Ethan Frome. The narrator has asked the woman he rents a room from about Ethan Frome, a town resident he encountered recently.\nHer mind was a store-house of innocuous anecdote and any question about her acquaintances brought forth a volume of detail; but on the subject of Ethan Frome I found her unexpectedly reticent. There was no hint of disapproval in her reserve; I merely felt in her an insurmountable reluctance to speak of him.","passage_html":null,"question_text":"As used in the text, what does the word “reserve” most nearly mean?","question_text_html":null,"choices":[{"label":"A","text":"Modesty"},{"label":"B","text":"Misgiving"},{"label":"C","text":"Constraint"},{"label":"D","text":"Composure"}],"correct_answer":"C","explanation":"Choice C is the best answer because as used in the text, “reserve” most nearly means constraint, or repression of one’s behavior or actions. The text indicates that although the narrator’s landlady is ordinarily “a store-house of innocuous anecdote” who readily produces “a volume of detail” in response to questions about her acquaintances—that is, she usually tells harmless stories and is willing to share details about people she knows—she is “unexpectedly reticent,” or surprisingly unwilling to speak, when it comes to Ethan Frome. The narrator then observes that the landlady doesn’t appear to disapprove of Ethan, she simply seems completely reluctant to speak of him. In this context, then, “reserve” refers to the landlady’s constraint—her repression of her usual willingness to share details in conversation.\nChoice A is incorrect. “Modesty” can refer to being appropriate in speech or behavior, and one might consider it appropriate to decline to speak of someone, but the text gives no indication that the narrator thinks the landlady is acting out of modesty. The narrator suggests that the landlady generally isn’t concerned about the appropriateness of discussing others (she’s usually “a store-house of innocuous anecdote” and shares many details) and isn’t holding back to avoid saying something negative about Ethan Frome (there’s “no hint of disapproval”); indeed, the narrator suggests he can’t tell why the landlady is so unwilling to speak of Ethan. Choice B is incorrect because the text never suggests that the landlady has any “misgiving,” or feeling of doubt or apprehension, about Ethan Frome. In fact, the text explicitly states that there is “no hint of disapproval” in her surprising unwillingness to discuss Ethan. Choice D is incorrect because the narrator doesn’t suggest that the landlady is acting with “composure,” or calmness and control of her emotions. Instead of describing the landlady’s emotional state or presenting her as calm, the narrator simply conveys her surprising unwillingness to discuss Ethan Frome.","is_grid_in":false},{"source_id":"1eeb9bb8","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"The subscription model in which consumers who do not deliberately cancel their subscriptions automatically pay recurring fees for access to products and services benefits retailers when consumer ______ is high. Many of the 8.5 percent of subscribers who canceled their food and beverage subscriptions in January 2022 had stopped valuing their subscriptions long before then, but sellers profited from those customers’ passivity in the interim.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"inertia"},{"label":"B","text":"decisiveness"},{"label":"C","text":"evasion"},{"label":"D","text":"turnover"}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of when the subscription model benefits retailers. In this context, “inertia” means a tendency to remain inactive or unchanged. The text describes a subscription model in which consumers continue to pay recurring fees unless they actively cancel and indicates that retailers profit when consumers fail to cancel even after they have stopped valuing the subscription. The text reinforces this by stating that sellers profited from canceling customers’ “passivity in the interim”—that is, the period during which those customers had ceased valuing their subscriptions but had not yet acted to cancel. This context supports the idea that the model benefits retailers when consumer inertia is high—that is, when consumers tend to remain inactive rather than take action to cancel.\nChoice B is incorrect because saying that the subscription model benefits retailers when consumer “decisiveness,” or quick and firm action, is high would contradict the text. The text indicates that retailers profit from consumer “passivity”—the failure to act—and decisive consumers would presumably cancel subscriptions promptly once they stopped valuing them, eliminating the retailers’ benefit. Choice C is incorrect because saying that the subscription model benefits retailers when consumer “evasion,” or active avoidance, is high wouldn’t make sense in this context. Evasion implies deliberate action to avoid something, but the text describes consumers as passive—they fail to cancel not because they actively avoid doing so but because they don’t take action at all. Choice D is incorrect because saying that the subscription model benefits retailers when consumer “turnover,” or the rate at which customers are replaced by new ones, is high would contradict the text. The text indicates that retailers profit when consumers continue paying without canceling, which means retailers benefit from retaining consumers, not from a high rate of consumer replacement.","is_grid_in":false},{"source_id":"735b0776","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"medium","passage":"Though Chloé Zhao’s films are fictional, she incorporates real events into them in a documentary-like style and casts nonprofessional actors who reside in the places that she aims to portray. She also encourages these actors, whether they are teenagers living on the Pine Ridge Indian Reservation or adults who travel the country for work, to put as much of themselves into their roles as possible. Her approach adds powerful resonance to films that explore the highly personal experiences of place and home, and often the difficult decision to stay or leave.","passage_html":null,"question_text":"Which choice best states the main purpose of the text?","question_text_html":null,"choices":[{"label":"A","text":"To argue that Chloé Zhao’s films are best understood as documentaries"},{"label":"B","text":"To discuss how Chloé Zhao’s background in documentary filmmaking has influenced her storytelling style in films"},{"label":"C","text":"To emphasize that Chloé Zhao’s decisions during the filmmaking process reinforce the themes of her films"},{"label":"D","text":"To summarize how Chloé Zhao’s style of filmmaking changed over the course of her career"}],"correct_answer":"C","explanation":"Choice C is the best answer because it most accurately states the main purpose of the text. The text begins by describing Zhao’s filmmaking decisions: incorporating real events, casting nonprofessional actors from the locations she portrays, and encouraging those actors to bring personal experiences to their roles. The text then states that this approach “adds powerful resonance” to films that explore themes of place, home, and the decision to stay or leave. Therefore, the main purpose of the text is to emphasize that Zhao’s filmmaking decisions reinforce the themes of her films.\nChoice A is incorrect because the text explicitly states that Zhao’s films are fictional. Although the text states that Zhao uses a “documentary-like style,” it does not suggest that the films are best understood as documentaries, or nonfiction movies. Instead, the text describes how her approach strengthens her films’ themes. Choice B is incorrect because the text does not discuss whether Zhao has a background in documentary filmmaking. The text does not mention her background. Instead, the text describes Zhao’s filmmaking approach and its effect on her films’ themes. Choice D is incorrect because the text does not address changes in Zhao’s filmmaking style over time; instead, it describes her consistent approach and how that approach reinforces her films’ themes.","is_grid_in":false},{"source_id":"c762ca58","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"hard","passage":"Technological advances have prompted companies to increasingly rely on automation to streamline production. Armin Granulo and colleagues, however, found that for products with higher symbolic value (those viewed as contributing to individual self-expression), consumers prefer products made by humans rather than by robots, likely because human-made products are more strongly associated with uniqueness. When considering automation, therefore, companies—especially those specializing in products of symbolic value—should weigh trade-offs between efficiency gains and consumer preferences.","passage_html":null,"question_text":"Which choice best describes the function of the underlined sentence in the text as a whole?","question_text_html":null,"choices":[{"label":"A","text":"It presents evidence supporting the text’s argument that consumers prefer products with high symbolic value over products with low symbolic value."},{"label":"B","text":"It refers to a finding presented in the previous sentence to recommend that companies that value product quality reconsider automating their production processes."},{"label":"C","text":"It illustrates the need for additional research to evaluate the claim in the previous sentence that automation affects how consumers rate product uniqueness."},{"label":"D","text":"It emphasizes that a research finding discussed in the text has practical implications that are particularly relevant for businesses making a certain class of product."}],"correct_answer":"D","explanation":"Choice D is the best answer because it best describes the function of the underlined sentence in the text as a whole. The text begins by noting that companies increasingly depend on automation to improve production efficiency. The text then presents Granulo and colleagues’ finding that consumers think it’s preferable for one category of products (those “with higher symbolic value”) to be human made rather than machine made. The underlined sentence highlights a practical consequence of that finding: companies, especially those specializing in such products, should balance the efficiency of automation against consumer preferences. Thus, the underlined sentence emphasizes that the research finding has practical implications that are especially relevant for businesses making a certain class of product.\nChoice A is incorrect. Although the text indicates that among products with high symbolic value, people prefer those made by humans over those made by machines, it doesn’t address whether products with high symbolic value are preferred over those with low symbolic value. Choice B is incorrect because rather than reiterate the finding in the previous sentence—that people tend to prefer “products with higher symbolic value” that are human made over those that are machine made—the underlined sentence instead makes a recommendation to companies that sell such products to carefully consider a potential drawback of making their products with machines. Choice C is incorrect because nothing in the underlined sentence or the text as a whole suggests that additional research is needed to evaluate Granulo and colleagues’ claim. Moreover, the researchers’ finding is that consumers prefer “products with higher symbolic value” to be human made, not that automation affects consumers’ ratings of how unique products are.","is_grid_in":false},{"source_id":"644f59cd","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"easy","passage":"Researchers studying how consumers develop their attitudes toward brands have found that the shapes of the logos used to present brand names are ______. Brand names presented using rounded logos, for example, were found to lead consumers to view brands as significantly more approachable than the same names did when presented using angular logos.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise phrase?","question_text_html":null,"choices":[{"label":"A","text":"a contributing factor"},{"label":"B","text":"an analogous case"},{"label":"C","text":"an overlooked effect"},{"label":"D","text":"a surprising paradox"}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of how logo shapes affect consumer attitudes toward brands. In this context, “a contributing factor” means an element that helps produce a particular outcome. The text indicates that researchers studied how consumers develop attitudes toward brands and found that logo shape affects those attitudes: rounded logos led consumers to view brands as “significantly more approachable” than angular logos did, even when the brand names were the same. This context supports the idea that logo shape is a contributing factor to consumer attitudes toward brands—that is, it helps influence how consumers perceive brands.\nChoice B is incorrect because describing logo shapes as “an analogous case,” or an instance comparable to another instance, wouldn’t make sense in this context. The text doesn’t mention any factor other than logo shape, and thus the text doesn’t provide another case (analogous or otherwise) against which to compare the effect of logo shape. Choice C is incorrect because describing logo shapes as “an overlooked effect,” or a result that has been disregarded, wouldn’t make sense in this context. The text is focused on describing observations about the effect of logo shape on consumer attitudes toward brands, but at no point does it suggest that this effect has been overlooked or disregarded. Choice D is incorrect because describing logo shapes as “a surprising paradox,” or a self-contradictory finding, wouldn’t make sense in this context. The finding that different logo shapes produce different consumer attitudes is straightforward and doesn’t exhibit any internal contradiction.","is_grid_in":false},{"source_id":"177ed7dc","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"Though copies of The Adventures of Indiana Jones in Wenceslas Square in Prague on January 16, 1989—an underground computer game that was created anonymously in 1989 as an act of political protest against the authoritarian regime of what was then Czechoslovakia—were originally distributed ______, the game is now readily available online for anyone to play.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"succinctly"},{"label":"B","text":"dispassionately"},{"label":"C","text":"disingenuously"},{"label":"D","text":"surreptitiously"}],"correct_answer":"D","explanation":"Choice D is the best answer because it most logically completes the text’s discussion of how The Adventures of Indiana Jones in Wenceslas Square in Prague on January 16, 1989 was originally distributed. In this context, “surreptitiously” means in a secret manner. The text describes the game as being underground and created anonymously as a way to oppose the regime of what was then Czechoslovakia. The text goes on to contrast the game’s original distribution with its current broader availability. This context supports the idea that copies were originally distributed surreptitiously—that is, secretly, as would be necessary for an act of protest against an authoritarian regime.\nChoice A is incorrect because saying that copies of the game were originally distributed “succinctly,” or in a brief and concise manner, wouldn’t make sense in this context. “Succinctly” describes the manner in which something is expressed, not the manner in which physical copies of a game are circulated. Choice B is incorrect because saying that copies of the game were originally distributed “dispassionately,” or without emotion, wouldn’t make sense in this context. The text describes the game as an act of political protest, suggesting that its creation and distribution were motivated by strong feelings about the then Czechoslovakian regime. Moreover, the text establishes the contrast between secretive distribution and open availability, not between emotional and unemotional distribution. Choice C is incorrect because saying that copies of the game were originally distributed “disingenuously,” or in an insincere manner, wouldn’t make sense in this context. The text characterizes the game as a sincere act of political protest, and the contrast the text sets up concerns secrecy (“underground” and “anonymously”) versus openness (“readily available”).","is_grid_in":false},{"source_id":"dbb56a02","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"medium","passage":"People tend to assume that being happy is the ideal emotional state and should be an ongoing aspiration; recently, however, research has suggested that it is at times beneficial to embrace negative emotions. To test whether anger can contribute to problem-solving abilities, researcher Heather Lench led an experiment in which participants were randomly assigned to view images designed to create an emotional condition—either neutral or one of anger, amusement, desire, or sadness. When asked to then solve a series of challenging puzzles, the participants in the anger condition had greater success than those in the other conditions.","passage_html":null,"question_text":"Which choice best describes the function of the underlined portion in the text as a whole?","question_text_html":null,"choices":[{"label":"A","text":"It describes a general psychological tendency that the study discussed in the text was designed to explain."},{"label":"B","text":"It explains an assumption underlying the hypothesis investigated in the study discussed in the text."},{"label":"C","text":"It notes a generally accepted belief that is called into question by a finding of the experiment outlined in the text."},{"label":"D","text":"It suggests a psychological basis for the behaviors of the participants in the experiment reported in the text."}],"correct_answer":"C","explanation":"Choice C is the best answer because it best describes the function of the underlined portion in the text as a whole. The underlined portion states that people commonly believe happiness is the ideal emotional state. However, the text then notes that recent research suggests that negative emotions can be beneficial, as demonstrated by an experiment by Heather Lench in which participants primed to feel anger did better at solving puzzles than did those primed to feel other emotions. This finding calls into question the belief that happiness is always the ideal state. Thus, the underlined portion notes a generally accepted belief that is called into question by a finding from the experiment.\nChoice A is incorrect because the study does not address why people assume happiness is ideal. Rather, the text indicates the study was designed to test whether anger can contribute to problem-solving abilities. Choice B is incorrect because rather than underlying the study’s hypothesis that anger could be beneficial in some circumstances, the underlined portion presents the widely held belief that happiness is always preferable to negative emotions, which directly conflicts with that hypothesis. Choice D is incorrect because the underlined portion presents a common belief that happiness is the ideal emotional state, not an explanation for the participants’ behavior in the experiment. The text reports that participants in the anger condition performed better on the puzzles but does not explain the psychological reason for this outcome.","is_grid_in":false},{"source_id":"5ccbfe22","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"To entice study participants, psychology researchers commonly offer a gift card or other compensation. However, this practice may undercut the applicability of the study’s results: people who join a study in response to ______ may differ in important ways from a representative sample of the population of interest.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"a propensity"},{"label":"B","text":"an inducement"},{"label":"C","text":"a paradigm"},{"label":"D","text":"an appeasement"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of how compensation in psychology studies may affect the applicability of results. In this context, “an inducement” means a reward offered to encourage a person to take a particular action. The text indicates that psychology researchers commonly offer rewards such as gift cards to encourage people to participate in their studies, potentially rendering the participant pool unrepresentative of the target population. This context supports the idea that participants are joining studies in response to an inducement.\nChoice A is incorrect. While participants might join a study in response to “a propensity,” or a natural inclination, to do so, the text isn’t focused on participants’ predispositions. Rather, the text is concerned with the external rewards that researchers offer to attract participants. Choice C is incorrect because saying that participants join studies in response to “a paradigm,” or a typical model or framework, wouldn’t make sense in context. The text doesn’t address any such framework. Instead, it focuses on tangible rewards that researchers offer to attract study participants. Choice D is incorrect because saying that participants join a study in response to “an appeasement,” or a concession made to pacify a person, wouldn’t make sense in context. The text describes researchers offering gift cards and other forms of compensation to attract willing study participants, not to address anyone’s grievance or dissatisfaction.","is_grid_in":false},{"source_id":"be069e38","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","passage":"In Habitat Threshold, Chamoru (Chamorro) poet Craig Santos Perez practices what he calls “recycling,” in which he preserves the syntactical and rhetorical structures of canonical poems but replaces their content to evoke current environmental issues. The form of these poems is thus ______ to their meaning, inviting readers to consider how climate change alters ostensibly familiar experiences.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"antithetical"},{"label":"B","text":"resigned"},{"label":"C","text":"invulnerable"},{"label":"D","text":"integral"}],"correct_answer":"D","explanation":"Choice D is the best answer because it most logically completes the text’s discussion of Craig Santos Perez’s poetic practice in Habitat Threshold. In this context, “integral” means essential or fundamentally connected. The text describes Perez’s “recycling” technique, in which he retains the syntactical and rhetorical structures (i.e., formal elements) of canonical poems but alters their content to address current environmental issues. The text further indicates that this technique invites readers to recognize how climate change has transformed seemingly familiar experiences—an effect that depends on the contrast between a poem’s recognizable inherited form and its new content. Because meaning derives from the particular way in which form and content interact in Perez’s poems, the context supports the idea that the form of these poems is integral to their meaning—in other words, form is fundamentally bound up with what the poems convey.\nChoice A is incorrect because it wouldn’t make sense in context to say that the form of Perez’s poems is “antithetical,” or directly opposed, to their meaning. The text indicates that the inherited form and the new content work together to produce the poems’ effect, so the form is essential, not opposed, to the poems’ meaning. Choice B is incorrect because it wouldn’t make sense in context to say that the form of Perez’s poems is “resigned,” or passively accepting. “Resigned” describes an attitude held by a person, not a relationship between a poem’s form and its meaning. Moreover, the poems’ form actively contributes to their meaning; it would contradict the text to suggest that the poems’ form merely serves as a passive vehicle for meaning. Choice C is incorrect because it wouldn’t make sense in context to say that the form of Perez’s poems is “invulnerable,” or incapable of being harmed. The text doesn’t characterize the poems’ meanings as threats to their form; instead, it discusses how form and meaning relate.","is_grid_in":false},{"source_id":"9ff88d6b","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"The work of Tobias Gerstenberg et al. on tracking eye movements supports a theory that people envision ______ scenarios when making causal judgments: when subjects were asked to look at two colliding billiard balls and judge whether one caused or prevented the other’s movement through a gate, their eyes looked at where the target ball would have gone if the ball that altered its path did not exist.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"ambivalent"},{"label":"B","text":"retrospective"},{"label":"C","text":"counterfactual"},{"label":"D","text":"analogical"}],"correct_answer":"C","explanation":"Choice C is the best answer because it most logically completes the text’s discussion of what people envision when making causal judgments, or judgments of cause and effect. In this context, “counterfactual” means contrary to fact. The text explains that in an experiment in which subjects judged whether one billiard ball caused or prevented another billiard ball’s movement through a gate, researchers found that the subjects looked at where the target ball would have gone if the other ball hadn’t been there at all—that is, the subjects pictured the path the target ball would have taken in a scenario contrary to the one they actually saw. This would be an example of people envisioning counterfactual scenarios when considering causes and effects.\nChoice A is incorrect because it wouldn’t make sense to describe scenarios people envision when making judgments of cause and effect as “ambivalent,” or characterized by conflicting feelings. People might have conflicting feelings in response to a scenario, but a scenario itself can’t have feelings. Choice B is incorrect. In this context, “retrospective” would mean looking back at something that occurred in the past. The text indicates that when asked to make a judgment about the movement of the target billiard ball, subjects envisioned what would have happened if only one ball had been present—that is, the text indicates that they envisioned a scenario that hadn’t actually happened, not that they examined only what had already actually happened. Choice D is incorrect. The text indicates that in an experiment involving the interaction of two billiard balls, eye movements showed that subjects pictured the path one ball would have taken if the other hadn’t been present. Because the subjects were picturing a scenario in the same context (the movement of the target billiard ball), just with a different arrangement of details (only one ball present), this wouldn’t be an example of people envisioning “analogical” scenarios, or hypothetical scenarios that are comparable to the scenario in question despite having different contexts.","is_grid_in":false},{"source_id":"de059199","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"hard","passage":"Typically, synthetic leather is petroleum based, but materials scientists searching for an ecologically sustainable alternative have used various bacteria that secrete linear chains of glucose, forming a dense mesh of cellulose called a pellicle, which is leatherlike except in color. The standard process for dyeing leather generates substantial wastewater and other undesirable byproducts, so adopting such a regimen would run counter to the ecological promise of the pellicle approach. To address this, Kenneth T. Walker and colleagues worked to modify Komagataeibacter rhaeticus bacteria to produce a pellicle with embedded pigmentation cells, thereby allowing the pellicle to “dye” itself from the inside.","passage_html":null,"question_text":"Which choice best describes the function of the underlined portion in the text as a whole?","question_text_html":null,"choices":[{"label":"A","text":"To concede that the researchers’ main goal as described in the text will be challenging to achieve due to the standard coloring approach being impractical for use on a pellicle"},{"label":"B","text":"To indicate the characteristic of conventional synthetic leathers that makes those leathers poorly suited to achieve the researchers’ main goal as presented in the text"},{"label":"C","text":"To describe a consideration that led the researchers to employ an alternative approach to coloring a pellicle that allowed them to achieve their main goal as presented in the text"},{"label":"D","text":"To illustrate how the researchers adapted the pellicle approach to overcome a potential impediment to their main goal as presented in the text"}],"correct_answer":"C","explanation":"Choice C is the best answer because it best describes the function of the underlined portion in the text as a whole. The text establishes that scientists developed a pellicle (a dense cellulose mesh) as an ecologically sustainable alternative to petroleum-based synthetic leather, noting that the pellicle is leatherlike except in color. The text then notes that the standard dyeing process for leather generates wastewater and other byproducts, and the underlined portion states that using such a process would be inconsistent with the ecological promise of the pellicle approach. The sentence that follows the underlined portion describes how Walker and colleagues addressed this problem by modifying bacteria to produce a pellicle with embedded pigmentation. Thus, the underlined portion describes a consideration—the incompatibility of standard dyeing methods with ecological aims—that led the researchers to employ an alternative coloring approach consistent with their goal of ecological sustainability.\nChoice A is incorrect because the text presents the underlined portion not as a concession that the researchers’ main goal, developing an ecologically sustainable alternative to synthetic leather, will be difficult to achieve, but as a reason why adopting a particular method of dyeing would be inconsistent with that goal. Choice B is incorrect because the underlined portion addresses a problem with the standard process for dyeing leather, not a characteristic of conventional synthetic leathers themselves. The issue identified in the underlined portion concerns the environmental impact of the standard method used to dye leather, not the petroleum-based nature of conventional synthetics. Choice D is incorrect because the underlined portion identifies the problem that motivated the researchers’ search for an alternative method of coloring the pellicle, not the method of coloring itself. The method of modifying bacteria to embed pigmentation is described in the sentence that follows the underlined portion.","is_grid_in":false},{"source_id":"3021d9ef","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"In a 2020 paper, Arya Udry et al. cautioned that although similarities in the isotopic signatures of elements detected in Mars’s atmosphere and in Martian meteorites recovered on Earth make it tempting to treat the geochemical properties of the meteorites as ______ those of Mars’s interiors, Mars’s geology cannot be ascertained based solely on meteorite-sample analyses.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"contrivances of"},{"label":"B","text":"proxies for"},{"label":"C","text":"catalysts of"},{"label":"D","text":"deterrents to"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of the relationship between Martian meteorites and Mars’s interior geology. In this context, “proxies for” means substitutes used to represent something else. The text describes Udry and colleagues as cautioning against a tempting line of reasoning: because the isotopic signatures (chemical fingerprints) of elements in Mars’s atmosphere resemble those in Martian meteorites recovered on Earth, researchers might be inclined to treat the meteorites’ geochemical properties as reasonably standing in for those of Mars’s interiors. The text indicates that Udry and colleagues argue against this reasoning, noting that Mars’s geology cannot be determined solely from meteorite analysis. This context conveys that it is tempting to treat the meteorites’ properties as proxies for those of Mars’s interiors.\nChoice A is incorrect because “contrivances of” would mean things artificially devised or produced by something, and it wouldn’t make sense to say that it’s tempting to treat the geochemical properties of meteorites as having been artificially produced by the planet the meteorites came from; it’s not clear how a planet could fabricate such properties. Further, the text is focused on the idea that it’s tempting to treat the meteorites’ properties as standing in for those of Mars’s interiors, which likely wouldn’t be the case if the meteorite’s properties were considered artificial in any way. Choice C is incorrect because “catalysts of” something are things that trigger or accelerate its change or action. The text focuses on the idea of analyzing samples of Martian meteorites found on Earth to determine Mars’s geology; this suggests that the temptation is to view the geochemical properties of the meteorites as direct evidence of those of Mars’s interior, not to treat them as though they had caused changes in Mars’s interior geology. Choice D is incorrect because “deterrents to” something would mean things that discourage or prevent it, and it wouldn’t make sense to say that it’s tempting to treat the geochemical properties of Martian meteorites as preventing the geochemical properties of Mars’s interiors; the meteorites came from Mars and are no longer there, so their properties can’t have any effect on those of the planet.","is_grid_in":false},{"source_id":"3bd32343","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","passage":"The following text is adapted from Henry James’s 1881 novel The Portrait of a Lady.\nEverything Osmond did was pose—pose so subtly considered that if one were not on the lookout one mistook it for impulse. Ralph had never met a man who lived so much in the land of consideration. His tastes, his studies, his accomplishments, his collections, were all for a purpose.","passage_html":null,"question_text":"As used in the text, what does the word “consideration” most nearly mean?","question_text_html":null,"choices":[{"label":"A","text":"Deference"},{"label":"B","text":"Courtesy"},{"label":"C","text":"Calculation"},{"label":"D","text":"Indecision"}],"correct_answer":"C","explanation":"Choice C is the best answer because as used in the text, “consideration” most nearly means calculation. The text describes Osmond as someone whose every action is a “pose;” that is, he adopted a deliberate appearance crafted so subtly that an unwary observer “mistook it for impulse.” The text further indicates that Osmond’s tastes, studies, accomplishments, and collections “were all for a purpose,” meaning each was strategically chosen to serve some intended end. The phrase “the land of consideration” thus characterizes Osmond as someone whose mental life is dominated by deliberate planning—that is, calculation.\nChoice A is incorrect because “deference,” meaning submissive yielding to others’ wishes, wouldn’t make sense in context. The text portrays Osmond as a man who carefully crafts his own image and arranges his life “for a purpose,” which suggests self-direction rather than yielding to others. Choice B is incorrect because although “consideration” can mean courtesy, or thoughtful regard for others, this meaning wouldn’t fit the text, which characterizes the calculated, purposeful nature of Osmond’s behavior, not his treatment of other people. Choice D is incorrect because “indecision,” meaning the inability to make a choice, wouldn’t make sense in context. The text portrays Osmond as decisive in his self-presentation: each pose is “subtly considered,” and his tastes and accomplishments serve “a purpose,” indicating firm choices made in service of his aims.","is_grid_in":false},{"source_id":"72bae7f4","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"medium","passage":"A team investigating frugivorous (fruit-eating) birds found that their feeding patterns vary depending on where they live within their habitat range. At the geographic boundaries of their natural range, these birds become highly selective, choosing fruits that closely match their beak size to maximize energy intake while minimizing effort. However, this fruit-selection strategy doesn’t occur at elevation boundaries (the highest and lowest altitudes of their range). In these areas, other factors, such as territorial competition among species, have a stronger influence on feeding patterns.","passage_html":null,"question_text":"Which choice best states the main purpose of the text?","question_text_html":null,"choices":[{"label":"A","text":"To describe research methods that can be used to study the habitat preferences of frugivorous birds"},{"label":"B","text":"To present research findings concerning how location within a habitat affects the feeding patterns of frugivorous birds"},{"label":"C","text":"To discuss how competition among frugivorous bird species influences their habitat boundaries"},{"label":"D","text":"To explain why habitat boundaries are more important than beak size in determining the feeding patterns of frugivorous birds"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most accurately states the main purpose of the text. The text begins by introducing research on variation in frugivorous birds’ feeding patterns based on the specific part of their habitat range the birds occupy. The text then explains that birds at the geographic edges of their range feed selectively based on beak size, whereas birds at altitude-based boundaries feed based on local competition with other species. Therefore, the main purpose of the text is to present research findings concerning how location within a habitat affects the feeding patterns of frugivorous birds.\nChoice A is incorrect. Although the text does discuss studying habitats of frugivorous birds, it doesn’t address specific research methods. Choice C is incorrect. Although the text mentions territorial competition as a factor affecting the feeding patterns of frugivorous birds at elevation boundaries, nothing in the text suggests that such competition affects the boundaries of those birds’ habitats. Choice D is incorrect. Although the text mentions beak size as a key factor shaping frugivorous birds’ feeding patterns at the geographic boundaries of the birds’ natural range, it doesn’t compare the relative importance of different factors or indicate that habitat boundaries matter more than beak size. Instead, the text presents findings showing that different types of boundaries—geographic and elevational—are associated with different influences on feeding patterns.","is_grid_in":false},{"source_id":"e19e8478","section":"reading_writing","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"easy","passage":"Understanding juvenile sea turtles’ migratory patterns is crucial for conservation efforts. While adult sea turtles are well studied, little is known about juveniles during their oceanic stage, when they spend most of their time in the open ocean. To learn about this stage, researchers tagged and released six juvenile green sea turtles (Chelonia mydas) into the eastern Caribbean Sea. Their findings revealed that the majority of the turtles passively drifted with ocean currents throughout the region. However, two individuals swam against the currents, possibly in search of foraging grounds off the coast of South America.","passage_html":null,"question_text":"Which choice best states the main purpose of the text?","question_text_html":null,"choices":[{"label":"A","text":"To describe successful conservation efforts for sea turtles"},{"label":"B","text":"To summarize research on an understudied stage of sea turtle development"},{"label":"C","text":"To compare the behavior of adult and juvenile sea turtles during migration"},{"label":"D","text":"To suggest reasons why some juvenile sea turtles swim against the ocean currents"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most accurately states the main purpose of the text. The text begins by noting that little is known about juvenile sea turtles during their oceanic stage, establishing this as an understudied area. The text then describes a study in which researchers tagged and released six juvenile green sea turtles and reports the findings: most turtles drifted passively with currents, while two swam against them. Therefore, the main purpose of the text is to summarize research on an understudied stage of sea turtle development.\nChoice A is incorrect because although the text mentions that understanding migratory patterns is important for conservation, it does not describe any conservation efforts, successful or otherwise; instead, the text summarizes research findings about a stage of sea turtle development. Choice C is incorrect. Although the text notes that adult sea turtles are well studied while juveniles are not, it does not compare the migratory behavior of adults and juveniles; instead, the text focuses solely on findings about juvenile turtles. Choice D is incorrect. Although the text briefly mentions that two turtles swam against currents and speculates that they may have done so in search of foraging grounds, this is a single detail within the text’s broader summary of the study, not the main purpose of the text as a whole.","is_grid_in":false},{"source_id":"3cfbf077","section":"reading_writing","domain":"Craft and Structure","skill":"Cross-Text Connections","difficulty":"hard","passage":"Text 1\nHycean planets are a class of exoplanets (planets outside our solar system) with oceans of liquid water—critical to supporting life—and atmospheres rich in hydrogen. Computer models have determined that for potential hycean planets, the range of the habitable zone (HZ), the distance from a star that allows a planet to retain liquid water on its surface, begins at about 1 astronomical unit (AU). In 2021, Nikku Madhusudhan et al. identified K2-18 b as a hycean candidate, noting that the planet is located right on the inner edge of the HZ.\nText 2\nIn a 2023 paper, Shang-Min Tsai et al. claimed that the hydrogen-rich atmospheres of K2-18 b and other hycean candidates admit wavelengths of light that cause elevated surface temperatures and increased water evaporation. Unlike earlier assessments, Tsai et al.’s calculations therefore placed the inner edge for these planets’ HZ as far out as 3.85 AU.","passage_html":null,"question_text":"Based on the texts, how would Tsai et al. (Text 2) most likely respond to Madhusudhan et al.’s research, as presented in Text 1?","question_text_html":null,"choices":[{"label":"A","text":"By stating that the chemical composition of the atmosphere of the hycean candidate Madhusudhan et al. identified suggests that this planet’s surface is unlikely to harbor liquid water"},{"label":"B","text":"By maintaining that Madhusudhan et al. relied on a model whose estimates of surface temperatures on hycean candidates are likely too high"},{"label":"C","text":"By observing that unlike the hycean candidate Madhusudhan et al. discovered, most other types of planets with hydrogen-rich atmospheres are likely located within the HZ"},{"label":"D","text":"By arguing that K2-18 b and other hycean candidates are unlikely to support life because these planets are located too far from the stars they orbit"}],"correct_answer":"A","explanation":"Choice A is the best answer because it reflects how Tsai et al. would most likely respond to Madhusudhan et al.’s identification of K2-18 b as a hycean candidate. Text 1 establishes that the habitable zone (HZ) for potential hycean planets, which are typified by abundant liquid water and hydrogen-rich atmospheres, represents “the distance from a star that allows a planet to retain liquid water on its surface” and is estimated to begin at about 1 astronomical unit (AU). Based on this characterization of the HZ, Madhusudhan et al. identified K2-18 b as a hycean candidate whose location falls on the “inner edge” of the HZ—implying that its distance from its star is about 1 AU. However, Text 2 presents Tsai et al.’s claim that the same hydrogen-rich atmospheres that typify K2-18 b and other hycean candidates “admit wavelengths of light that cause elevated surface temperatures and increased water evaporation,” phenomena that would be exacerbated by proximity to their host stars. Tsai et al. instead placed the inner edge of the HZ “as far out as 3.85 AU,” implying that hycean candidates at lesser distances from their stars would be unlikely to maintain liquid oceans because of elevated surface temperatures and subsequent water evaporation. According to Tsai et al.’s HZ estimate, K2-18 b—at roughly 1 AU—would be too close to its star to retain liquid water. Therefore, based on the details in the texts, Tsai et al. would most likely respond that the very atmospheric composition that defines K2-18 b as a hycean candidate suggests that it is unlikely to harbor liquid water on its surface.\nChoice B is incorrect. In contrast to the suggestion that Madhusudhan et al.’s estimates of the surface temperature of hycean candidates are “likely too high,” Tsai et al.’s findings suggest the opposite: earlier assessments of the HZ didn’t fully account for the warming effect of wavelengths of light admitted by these planets’ hydrogen-rich atmospheres, which is why Tsai et al. placed the edge of the HZ farther out. The information in Text 2 therefore suggests that Tsai et al. would view Madhusudhan et al.’s temperature estimates as too low rather than as too high. Choice C is incorrect because neither text discusses other types of planets with hydrogen-rich atmospheres or compares them to hycean candidates. It therefore doesn’t follow from the information in the texts that Tsai et al. would observe that most other hydrogen-rich planets are likely within the HZ. Text 2 only indicates that the HZ for hycean candidates begins at about 3.85 AU and that K2-18 b therefore isn’t likely to be within the HZ, not that other planets with hydrogen-rich atmospheres are mostly located within the HZ. Choice D is incorrect because it mischaracterizes Tsai et al.’s findings. Rather than indicating that K2-18 b and other hycean candidates are “too far from the stars they orbit,” Tsai et al.’s findings suggest the opposite problem. Because these planets’ hydrogen-rich atmospheres admit wavelengths of light that cause elevated temperatures and water evaporation at distances of less than 3.85 AU, Tsai et al. would be more likely to argue that K2-18 b (at a distance of about 1 AU) and planets like it are too close to their stars, not too far from them. Moreover, Text 2 doesn’t suggest anything about hycean candidates more generally being unable to support life, only that hycean candidates at distances less than 3.85 AU from their stars, like K2-18 b, likely don’t have the liquid water needed to sustain life. Presumably, hycean candidates that are within the HZ described by Tsai et al. could harbor liquid oceans necessary for supporting life.","is_grid_in":false},{"source_id":"4ce8e2fa","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","passage":"Players of online games are largely aware that the games collect their data, and they’re often willing to trade some privacy for a fun experience. But the games are often quite ______ about what data they collect and why. Because of this, data-privacy advocates are seeking to expand online players’ knowledge of data collection practices and improve their ability to navigate privacy-setting features in games.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"opaque"},{"label":"B","text":"abrasive"},{"label":"C","text":"ambivalent"},{"label":"D","text":"outspoken"}],"correct_answer":"A","explanation":"Choice A is the best answer because it most logically completes the text’s discussion of how online games disclose information about their data collection practices. In this context, “opaque” means that games deliberately avoid sharing clear information about data collection. The text indicates that data-privacy advocates are working to “expand online players’ knowledge of data collection practices” and improve players’ ability to navigate privacy settings. The fact that advocates are working to expand players’ knowledge about data collection and privacy settings implies that players currently lack clear information about these aspects of the games. This context therefore supports the idea that online games are often quite unclear, or opaque, about what data they collect and why.\nChoice B is incorrect because describing online games as being “abrasive,” or harsh and irritating, about their data collection practices wouldn’t make sense in context. The text focuses on the clarity of the information about data collection that games share with players, not on the tone or manner in which this information is communicated. Choice C is incorrect because describing the games as “ambivalent,” or having mixed feelings, about their data collection practices wouldn’t make sense in context. The text isn’t discussing the game companies’ attitudes toward their own practices; it’s discussing the extent to which information about those practices is communicated to players. Choice D is incorrect because describing online games as “outspoken,” or frank and forthright, about their data collection practices would contradict the text. If the games were forthright about data collection, data-privacy advocates wouldn’t need to work to expand players’ awareness of this aspect of gaming. Instead, the text emphasizes the challenge of obtaining clear information about data collection in online games.","is_grid_in":false},{"source_id":"9828ab3d","section":"reading_writing","domain":"Craft and Structure","skill":"Cross-Text Connections","difficulty":"hard","passage":"Text 1 is adapted from E.M. Forster’s 1910 novel Howards End. Text 2 discusses Howards End. King’s Cross and St. Pancras are adjacent railway terminals in London from which trains travel to the countryside.\nText 1\nTo Margaret the station of King’s Cross had always suggested Infinity. Its very situation—withdrawn a little behind the facile splendours of St. Pancras—implied a comment on the materialism of life. Those two great arches, colourless, indifferent, shouldering between them an unlovely clock, were fit portals for some eternal adventure, whose issue might be prosperous, but would certainly not be expressed in the ordinary language of prosperity.\nText 2\nThe interplay between opposing ideological positions in Howards End is broadly articulated in the novel’s organization of geographic space. On the one hand, the modern metropolis of London represents capitalism’s emphasis on pragmatism and the accumulation of material wealth; on the other, the English countryside, accessible via King’s Cross, fosters an idealism that values tradition, authentic personal connection, and the aesthetic—what the novel calls “the infinite.”","passage_html":null,"question_text":"Based on the texts, the author of Text 2 would most likely agree with which statement about King’s Cross, as it is depicted in Text 1?","question_text_html":null,"choices":[{"label":"A","text":"King’s Cross has a relatively unassuming appearance whose sharp contrast with the more aesthetically pleasing appearance of St. Pancras suggests to Margaret the ascendancy of the pragmatic capitalistic outlook among London’s inhabitants."},{"label":"B","text":"Because it is situated at the beginning of Margaret’s journey from the city to the country, King’s Cross emblematizes the intrusion of the forces of materialism and modernity into the rural spaces that the novel associates with idealism and tradition."},{"label":"C","text":"The austerity conveyed by King’s Cross’s appearance mirrors Margaret’s disillusionment with the prospect of having authentic connections with other people in a world that chiefly values more conventional forms of prosperity."},{"label":"D","text":"As a point of connection between London and the countryside, King’s Cross suggests to Margaret the possibility of experiencing the intangible abundance promised by the kinds of authentic engagements that the novel’s rural spaces seem to offer."}],"correct_answer":"D","explanation":"Choice D is the best answer because it presents a statement about King’s Cross, as depicted in Text 1, that the author of Text 2 would most likely agree with. In Text 1, Margaret associates King’s Cross with “Infinity” and sees its arches as portals for an adventure whose value transcends London’s mundane materialism. The author of Text 2 provides an interpretation of the novel’s geography that is consistent with Margaret’s vision, explaining that London represents capitalist materialism while the countryside—“accessible via King’s Cross”—fosters idealism, authentic connection, and the aesthetic (“the infinite”). By characterizing King’s Cross as a “point of connection between London and the countryside” that offers access to the “intangible abundance” promised by “the novel’s rural spaces,” choice D provides a reading of the railway terminal that aligns with the interpretive framework set up by the author of Text 2.\nChoice A is incorrect because Margaret views King’s Cross positively—as evoking infinity and eternal adventure—not as a sign of capitalism’s dominance. Text 1 characterizes St. Pancras’s splendors as “facile,” or superficial, so that the contrast elevates King’s Cross rather than signaling materialism’s ascendancy. Choice B is incorrect because the author of Text 2 positions King’s Cross as a gateway to the countryside’s idealism, not as a vehicle for materialism intruding into rural spaces. Margaret’s sense of wonder at the station arises from her sense that it offers access to the countryside’s idealism rather than to London’s materialism. Choice C is incorrect because nothing in Text 1 suggests Margaret is disillusioned; her perception of King’s Cross is defined by expansive possibility, not resignation. Moreover, Margaret finds the austerity of King’s Cross (relative to St. Pancras) appealing—its unpretentious appearance resonates with her attitude toward the “materialism of life.”","is_grid_in":false},{"source_id":"2a6c71a4","section":"reading_writing","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","passage":"In the search for new impact craters on Mars, the roles of seismic monitoring and orbital imaging as data sources are ______: when vibrations detected with seismic monitoring indicate roughly where an impact has occurred, researchers can use orbital images of that relatively limited area of the rocky surface to precisely locate a new crater.","passage_html":null,"question_text":"Which choice completes the text with the most logical and precise word or phrase?","question_text_html":null,"choices":[{"label":"A","text":"interchangeable"},{"label":"B","text":"complementary"},{"label":"C","text":"exhaustive"},{"label":"D","text":"redundant"}],"correct_answer":"B","explanation":"Choice B is the best answer because it most logically completes the text’s discussion of how seismic monitoring and orbital imaging are used to find impact craters on Mars. In this context, “complementary” means combining in such a way that each contributes something the other lacks. The text describes how two data sources work together: seismic monitoring detects vibrations that indicate the rough location of an impact, and orbital imaging is then used to examine that limited area in detail to pinpoint the exact location of the crater. Each method does something the other does not—seismic monitoring narrows the search area, while orbital imaging provides the precise location—and together they accomplish what neither could alone. This context supports the idea that the two methods’ roles are complementary.\nChoice A is incorrect because describing the roles of seismic monitoring and orbital imaging as “interchangeable,” or able to be substituted for each other, would contradict the text. The text indicates that the two methods perform different functions in sequence (seismic monitoring narrows the area; orbital imaging pinpoints the crater), so they cannot be substituted for each other. Choice C is incorrect because describing the roles of seismic monitoring and orbital imaging as “exhaustive,” or comprehensive in covering all possibilities, wouldn’t be logical in context. The text describes how the two methods work together to perform a particular two-step task (locating new impact craters), not whether they collectively address every possible aspect of Mars research. Choice D is incorrect because describing the roles of seismic monitoring and orbital imaging as “redundant,” or unnecessarily duplicative, would contradict the text. The text indicates that each method performs a distinct function in finding impact craters on Mars—rough localization versus precise localization—so neither method duplicates the other’s contribution.","is_grid_in":false},{"source_id":"8a1ad52b","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"A research team led by Gal Badihi has discovered that chimpanzees communicate through exchanges of gestures occurring at a pace similar to that of human conversations. ______ chimpanzee gesture exchanges have short pauses of about 120 milliseconds between communications, comparable to the 200-millisecond average pause between turns in human speech.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"As a result,"},{"label":"B","text":"Specifically,"},{"label":"C","text":"By contrast,"},{"label":"D","text":"Nevertheless,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “Specifically” logically signals that the information in this sentence—that pauses between chimpanzee gestures average about 120 milliseconds, comparable to the 200-millisecond average pause in human speech—provides specific, precise details elaborating on the previous sentence’s claim about the pace of chimpanzee communication being similar to that of human conversations.\nChoice A is incorrect because “as a result” illogically signals that this sentence presents a result or consequence of the claim about chimpanzee communication described in the previous sentence. Instead, the sentence provides specific details elaborating on that claim. Choice C is incorrect because “by contrast” illogically signals that the information about chimpanzee gesture exchanges in this sentence contrasts with the previous sentence’s claim about the pace of chimpanzee communication being similar to that of human conversations. Instead, the sentence provides specific details elaborating on that claim. Choice D is incorrect because “nevertheless” illogically signals that the information about chimpanzee gesture exchanges in this sentence is true despite the previous claim about the pace of chimpanzee communication. Instead, the sentence provides specific details elaborating on that claim.","is_grid_in":false},{"source_id":"94c9788e","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"Brain imaging research led by neuroscientist Dwaynica Greaves found that actors showed suppressed responses in the left anterior prefrontal cortex (the portion of the brain associated with self-awareness) when their names were called during performances; ______ the actors’ responses were normal in nonacting contexts. These findings suggest that when embodying characters, performers may temporarily set aside their personal identities.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"specifically,"},{"label":"B","text":"conversely,"},{"label":"C","text":"likewise,"},{"label":"D","text":"thus,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “Conversely” logically signals that the information in this sentence—that the actors’ responses were normal in nonacting contexts—presents the opposite of the previous finding that actors showed suppressed responses when their names were called during performances.\nChoice A is incorrect because “specifically” illogically signals that the information about the actors’ normal responses in nonacting contexts provides specific details elaborating on the previous finding of suppressed responses during performances. Instead, the sentence presents the responses as opposites. Choice C is incorrect because “likewise” illogically signals that the actors’ normal responses in nonacting contexts are similar to the suppressed responses observed during performances. Instead, the sentence presents the responses as opposites. Choice D is incorrect because “thus” illogically signals that the actors’ normal responses in nonacting contexts are a result or consequence of the suppressed responses observed during performances. Instead, the sentence presents the responses as opposites.","is_grid_in":false},{"source_id":"e1079609","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"In 1845, the United States District Court for the state of Iowa was established. Initially, the court’s jurisdiction was a single district that encompassed the entire state, but as Iowa’s population grew, this single district began to struggle to serve the needs of everyone in the state. ______ the court’s jurisdiction was subdivided into two districts, each with its own district court.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Nevertheless,"},{"label":"B","text":"Ultimately,"},{"label":"C","text":"Additionally,"},{"label":"D","text":"For example,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “Ultimately” logically signals that the information in this sentence—that the court’s jurisdiction was subdivided into two districts—was the eventual outcome or resolution of the previously described struggle of the single district to serve the needs of everyone in the state.\nChoice A is incorrect because “nevertheless” illogically signals that the information in the sentence is true despite the single district’s struggle to serve the state’s needs. Instead, the sentence describes the eventual resolution of that struggle. Choice C is incorrect because “additionally” illogically signals that the information in the sentence is merely an additional fact related to the single district’s struggle. Instead, the sentence describes the eventual resolution of that struggle. Choice D is incorrect because “for example” illogically signals that the information in the sentence provides a specific example of the single district’s struggle to serve the state’s needs. Instead, the sentence describes the eventual resolution of that struggle.","is_grid_in":false},{"source_id":"1e655377","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"Denali National Park and Preserve is an important tourist destination in Alaska. Many visitors assume that its $15 entry fee is charged per vehicle. ______ that fee is charged per person.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Consequently,"},{"label":"B","text":"Second,"},{"label":"C","text":"Moreover,"},{"label":"D","text":"Actually,"}],"correct_answer":"D","explanation":"Choice D is the best answer. “Actually” logically signals that the information in this sentence—that the entry fee is charged per person—corrects the assumption described in the previous sentence that the fee is charged per vehicle.\nChoice A is incorrect because “consequently” illogically signals that the fee being charged per person is a consequence of visitors assuming the fee is charged per vehicle. Instead, the sentence corrects that assumption. Choice B is incorrect because “second” illogically signals that the fee being charged per person is a second point in a series following the previous information about what visitors assume. Instead, the sentence corrects that assumption. Choice C is incorrect because “moreover” illogically signals that the fee being charged per person is merely an additional fact related to the previous information about what visitors assume. Instead, the sentence corrects that assumption.","is_grid_in":false},{"source_id":"539abc58","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","passage":"While researching a topic, a student has taken the following notes:\nUkiyo-e woodblock prints were a popular artistic form in Japan from the 1600s through the 1800s.\nUkiyo-e prints were produced by teams of artisans that included artists, wood-carvers, printers, and publishers.\nSōsaku-hanga was a popular Japanese printmaking movement that emerged in the early 1900s.\nSōsaku-hanga prioritized individual artistic expression.\nAn artist working in this style typically handled all aspects of print creation, from drawing to wood carving to printing.","passage_html":null,"question_text":"The student wants to contrast ukiyo-e and sōsaku-hanga production methods. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"One notable distinction between ukiyo-e and sōsaku-hanga prints is sōsaku-hanga’s emphasis on individual artistic expression."},{"label":"B","text":"Ukiyo-e prints were popular in Japan from the 1600s through the 1800s, while sōsaku-hanga prints emerged later, in the early 1900s."},{"label":"C","text":"Teams of artisans produced ukiyo-e prints, whereas individual artists typically handled all aspects of sōsaku-hanga printmaking themselves."},{"label":"D","text":"In contrast to ukiyo-e prints, sōsaku-hanga prints were produced using methods such as drawing and wood carving."}],"correct_answer":"C","explanation":"Choice C is the best answer. The sentence contrasts the two production methods, noting that ukiyo-e prints are produced by teams of artisans, whereas sōsaku-hanga prints are typically produced by an individual artist.\nChoice A is incorrect. The sentence indicates a difference between the two styles, noting that sōsaku-hanga emphasizes individual artistic expression, but it doesn’t provide sufficient information about ukiyo-e prints to contrast the two styles’ production methods. Choice B is incorrect. The sentence contrasts when the two styles were popular; it doesn’t contrast their production methods. Choice D is incorrect. The sentence mischaracterizes information from the notes: both styles include drawing and wood carving in their production, not just sōsaku-hanga.","is_grid_in":false},{"source_id":"28c7a762","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"As the Proto-Indo-European language split into different languages, many words evolved to sound very different than they had in their proto-language—but this wasn’t always the case. ______ words retained much of their original sound. The word “father,” for instance, sounds similar in Italian (padre), Latin (pater), and Sanskrit (pitar), three Proto-Indo-European descendants.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"However,"},{"label":"B","text":"Moreover,"},{"label":"C","text":"Thus,"},{"label":"D","text":"Sometimes,"}],"correct_answer":"D","explanation":"Choice D is the best answer. “Sometimes” logically signals that the information in this sentence—that words retained much of their original sound—describes an occasional exception, elaborating on the previous statement that the evolution of words to sound very different from their proto-language origins “wasn’t always the case.”\nChoice A is incorrect because “however” illogically signals that the information about words retaining much of their original sound contrasts with the previous statement. Instead, the sentence describes an occasional exception, elaborating on the previous statement that the evolution of words to sound very different from their proto-language origins “wasn’t always the case.” Choice B is incorrect because “moreover” illogically signals that the information about words retaining much of their original sound merely adds to the previous statement. Instead, the sentence describes an occasional exception, elaborating on the previous statement that the evolution of words to sound very different from their proto-language origins “wasn’t always the case.” Choice C is incorrect because “thus” illogically signals that the information about words retaining much of their original sound is a result or consequence of the previous statement. Instead, the sentence describes an occasional exception, elaborating on the previous statement that the evolution of words to sound very different from their proto-language origins “wasn’t always the case.”","is_grid_in":false},{"source_id":"fb56b593","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"Despite its great distance from Earth—it is 570 light-years away—the star Shaula is one of the brightest stars in the sky, ranking 23rd. Although not as bright as Shaula, the star Alkaid also ranks among the 50 brightest stars (40th, to be exact). ______ Alkaid’s brightness is likely due to the star’s relative proximity: Alkaid is only 100 light-years from Earth.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Indeed,"},{"label":"B","text":"As a result,"},{"label":"C","text":"Granted,"},{"label":"D","text":"Similarly,"}],"correct_answer":"C","explanation":"Choice C is the best answer. “Granted” logically signals that the information in this sentence—that Alkaid’s brightness is likely due to its relative proximity to Earth—is a concession acknowledging that the star likely appears bright for different reasons than the faraway star to which it is compared, Shaula.\nChoice A is incorrect because “indeed” illogically signals that the information in this sentence offers additional emphasis in support of the previous information about Alkaid ranking among the 50 brightest stars. Instead, the sentence concedes that the most likely reason Alkaid is counted among the sky’s brightest stars is its relative proximity to Earth. Choice B is incorrect because “as a result” illogically signals that Alkaid’s brightness is caused by the previous information about Alkaid ranking among the 50 brightest stars. Instead, the sentence concedes that the most likely reason Alkaid is counted among the sky’s brightest stars is its relative proximity to Earth. Choice D is incorrect because “similarly” illogically signals that the information in this sentence is similar to the previous information about Alkaid ranking among the 50 brightest stars. Instead, the sentence concedes that the most likely reason Alkaid is counted among the sky’s brightest stars is its relative proximity to Earth.","is_grid_in":false},{"source_id":"9f7ac40d","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"In ArtMed inSight, a series of art-based medical education classes taught by Anne Willieme, medical students learn to use techniques more often associated with the arts, such as slowing down interpretation and considering multiple perspectives. ______ Willieme’s students develop better observational skills, enhancing their ability to understand and diagnose patients effectively.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"By contrast,"},{"label":"B","text":"In doing so,"},{"label":"C","text":"For example,"},{"label":"D","text":"Nevertheless,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “In doing so” logically signals that the information in this sentence—that the medical students develop better observational skills—is an outcome of the action described in the previous sentence (the students learning art-based techniques).\nChoice A is incorrect because “by contrast” illogically signals that the students developing better observational skills contrasts with the previous information about learning art-based techniques. Instead, the students’ improved skills are a direct result of learning those techniques. Choice C is incorrect because “for example” illogically signals that the students developing better observational skills is a specific example of learning art-based techniques. Instead, the students’ improved skills are a direct result of learning those techniques. Choice D is incorrect because “nevertheless” illogically signals that the students develop better observational skills despite the previous information about learning art-based techniques. Instead, the students’ improved skills are a direct result of learning those techniques.","is_grid_in":false},{"source_id":"7dbcb7f4","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"Karel Čapek’s 1920 play R.U.R. (Rossum’s Universal Robots), in which artificial workers overthrow their masters, left an indelible mark on the science fiction genre, and the English language, by introducing the term “robot” (derived from the Czech word robota, meaning “indentured labor” or “drudgery”). ______ Čapek’s play also contributed to a venerable literary and mythological tradition: using artificial beings as mirrors and foils for humanity.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Beyond the simple coining of a term,"},{"label":"B","text":"By achieving such a lofty goal,"},{"label":"C","text":"Ultimately limited in its lasting influence,"},{"label":"D","text":"Despite its creation of such an iconic trope,"}],"correct_answer":"A","explanation":"Choice A is the best answer. “Beyond the simple coining of a term” logically signals that the information in this sentence—that Čapek’s play contributed to a literary and mythological tradition of using artificial beings as mirrors and foils for humanity—describes contributions that extend beyond the previously described achievement of introducing the term “robot” to the English language.\nChoice B is incorrect because “by achieving such a lofty goal” illogically signals that the play’s contribution to a literary and mythological tradition was accomplished through the means of the previously described achievement of introducing the term “robot.” Instead, the sentence describes an additional contribution that goes beyond that achievement. Choice C is incorrect because “ultimately limited in its lasting influence” illogically minimizes the play’s influence, which is inconsistent with the text’s other claims about the play. Instead, the sentence describes contributions that go beyond the previously described achievement of introducing the term “robot.” Choice D is incorrect because “despite its creation of such an iconic trope” illogically signals that the play’s contribution to a literary and mythological tradition is surprising given the play’s creation of an iconic trope. Instead, the sentence describes contributions that go beyond the previously described achievement of introducing the term “robot.”","is_grid_in":false},{"source_id":"c3b854fa","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","passage":"While researching a topic, a student has taken the following notes:\nResearchers Gwangsu Kim et al. sought to explore the relationship between the brain’s ability to process natural sounds and its ability to process music.\nThey used an artificial deep neural network (DNN) that models how the brain processes auditory information.\nThe DNN had been trained to detect natural sounds (excluding music).\nFinding: The DNN spontaneously developed neurons that responded to music but not to other auditory stimuli.\nConclusion: The brain’s ability to process music may arise as a by-product of natural sound processing.","passage_html":null,"question_text":"The student wants to present the aim of the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"In their study, the researchers evaluated whether an artificial deep neural network could model how the brain processes auditory information."},{"label":"B","text":"By training an artificial deep neural network, the researchers aimed to establish that the brain’s ability to process natural sounds arises as a by-product of processing music."},{"label":"C","text":"The researchers used an artificial deep neural network, which spontaneously developed neurons that responded to music but not to other auditory stimuli."},{"label":"D","text":"Using an artificial deep neural network, the researchers sought to explore the relationship between the brain’s ability to process natural sounds and its ability to process music."}],"correct_answer":"D","explanation":"Choice D is the best answer. The sentence presents the aim of the study, noting that the researchers sought to explore the relationship between the brain’s ability to process natural sounds and its ability to process music.\nChoice A is incorrect. The researchers used the DNN to achieve their aim of exploring the relationship between the brain’s ability to process natural sounds and its ability to process music; evaluating the DNN itself was not their aim. Choice B is incorrect. The sentence misrepresents the researchers’ conclusion as their aim and also misrepresents that conclusion. The researchers’ aim was to explore the relationship between the brain’s ability to process natural sounds and its ability to process music; their conclusion was that the brain’s ability to process music arises as a by-product of natural sound processing, not the other way around. Choice C is incorrect. The sentence merely describes a finding from the study; it doesn’t present the aim of the study.","is_grid_in":false},{"source_id":"64bcdf3d","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"Giant dust plumes from the Sahara Desert that blow across the Atlantic Ocean can have complex and opposing effects on tropical cyclones. On one hand, the dust can enhance the formation of ice clouds in the cyclone’s core, increasing precipitation. ______ the dust can lower sea surface temperatures around the cyclone’s core, weakening the storm.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Previously,"},{"label":"B","text":"In other words,"},{"label":"C","text":"For example,"},{"label":"D","text":"On the other hand,"}],"correct_answer":"D","explanation":"Choice D is the best answer. “On the other hand” logically signals that the information in this sentence—that dust can lower sea surface temperatures, weakening the storm—presents an opposing effect to the one described in the previous sentence, in which dust enhances ice cloud formation and increases precipitation.\nChoice A is incorrect because “previously” illogically signals that the information in this sentence is an event that occurred before the dust-enhanced ice cloud formation mentioned in the previous sentence. Instead, the dust lowering surface temperatures—and weakening the storm—is an opposing effect. Choice B is incorrect because “in other words” illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about dust enhancing ice cloud formation. Instead, the dust lowering surface temperatures—and weakening the storm—is an opposing effect. Choice C is incorrect because “for example” illogically signals that the information in this sentence is an example of the previous information about dust enhancing ice cloud formation. Instead, the dust lowering surface temperatures—and weakening the storm—is an opposing effect.","is_grid_in":false},{"source_id":"be3363dd","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","passage":"While researching a topic, a student has taken the following notes:\nSuzanne K. Birner led a study analyzing rocks on the seafloor to better understand the history of Earth’s mantle.\nRock samples were collected from two seafloor ridges.\nThe researchers determined the samples’ period of formation (the Archean eon) and oxidation level (extremely low).\nHigh temperatures in the Archean likely caused the rocks’ low oxidation.\nBirner’s team suggests the oxidation of Earth’s mantle has remained stable over time, contrary to previous theories.\nThe findings help explain the unique conditions that allowed life to develop on Earth.","passage_html":null,"question_text":"The student wants to present the study’s research methods. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Birner led a study to better understand the history of Earth’s mantle and explain the conditions that allowed life to develop."},{"label":"B","text":"To further analyze the origins of Earth’s unique conditions, researchers focused on rocks from the Archean eon, when Earth’s temperatures were extremely high."},{"label":"C","text":"By studying these ancient rocks, the team aimed to challenge previous theories about changes in Earth’s mantle over time."},{"label":"D","text":"Birner’s team analyzed the age and oxidation levels of rock samples collected from two seafloor ridges."}],"correct_answer":"D","explanation":"Choice D is the best answer. The sentence presents the study’s research methods, explaining that Birner’s team analyzed the age and oxidation levels of rock samples collected from two seafloor ridges.\nChoice A is incorrect. The sentence describes the purpose of the study (to understand the history of Earth’s mantle and explain conditions for life); it doesn’t present the study’s research methods. Choice B is incorrect. The sentence notes the study’s focus on rocks from the Archean eon and a characteristic of the eon; it doesn’t present the study’s research methods. Choice C is incorrect. The sentence indicates the goal of the study (to challenge previous theories); it doesn’t present the study’s research methods.","is_grid_in":false},{"source_id":"8e9e473d","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","passage":"While researching a topic, a student has taken the following notes:\nA 2024 study analyzed the facial expressions of wolves and domestic dogs.\nIn the study, facial expressions were coded under 46 different facial actions.\nThe “ears rotator” facial action is seen in wolves.\nDog breeds with erect (wolf-like) ears can produce the “ears rotator” facial action.\nDog breeds with flopped or semi-flopped (non-wolf-like) ears cannot produce the “ears rotator” facial action.","passage_html":null,"question_text":"The student wants to compare dog breeds with wolf-like ears to dog breeds with non-wolf-like ears. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"In a 2024 study, dog breeds with non-wolf-like ears were able to produce the same facial movements that wolves could."},{"label":"B","text":"One difference between dog breeds with wolf-like ears and dog breeds without them is that wolf-like breeds cannot produce the “ears rotator” facial action."},{"label":"C","text":"Non-wolf-like ears are flopped or semi-flopped, but wolf-like ears are different: they are erect and can produce the “ears rotator” facial action."},{"label":"D","text":"Like wolves, dog breeds with erect ears can produce the “ears rotator” facial action, while those with flopped or semi-flopped ears cannot."}],"correct_answer":"D","explanation":"Choice D is the best answer. The sentence compares dog breeds with wolf-like (erect) and non-wolf-like (flopped or semi-flopped) ears, noting that breeds with erect ears are able to produce the same “ears rotator” facial action as wolves, while breeds with flopped or semi-flopped ears cannot.\nChoice A is incorrect. The sentence compares dog breeds with non-wolf-like ears to wolves, not to other dog breeds. It also misrepresents information from the notes: breeds with non-wolf-like ears cannot produce the “ears rotator” facial action. Choice B is incorrect. While the sentence appears to compare dog breeds with wolf-like and non-wolf-like ears, it misrepresents information from the notes: breeds with wolf-like ears can produce the “ears rotator” facial action. Choice C is incorrect. While the sentence compares the physical characteristics of the two ear types, it doesn’t compare the dog breeds that have these ear types.","is_grid_in":false},{"source_id":"b5ed1a8b","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","passage":"In his 2023 collection The Diaspora Sonnets, Filipino American poet Oliver de la Paz leverages the sonnet form’s “diamond-like quality of precision,” as he describes it. The poems often adhere scrupulously to the form’s centuries-old conventions, such as its characteristic fourteen-line length. In the twelve-line poem “Diaspora Sonnet at the Feeders Before the Freeze,” ______ de la Paz playfully subverts sonnet conventions, the poem’s truncated length conveying a sense of abruptness.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"fittingly,"},{"label":"B","text":"similarly,"},{"label":"C","text":"for example,"},{"label":"D","text":"by contrast,"}],"correct_answer":"D","explanation":"Choice D is the best answer. “By contrast” logically signals that the information in this sentence—that one of de la Paz’s poems subverts sonnet conventions—contrasts with the previous information that his poems often adhere to sonnet conventions.\nChoice A is incorrect because “fittingly” illogically signals that the information in this sentence is an appropriate or expected outcome of the previous information about de la Paz’s adherence to sonnet conventions. Instead, de la Paz’s subversion of sonnet conventions contrasts with that information. Choice B is incorrect because “similarly” illogically signals that the information in this sentence is similar to the previous information about de la Paz’s adherence to sonnet conventions. Instead, de la Paz’s subversion of sonnet conventions contrasts with that information. Choice C is incorrect because “for example” illogically signals that the information in this sentence exemplifies the previous information about de la Paz’s adherence to sonnet conventions. Instead, de la Paz’s subversion of sonnet conventions contrasts with that information.","is_grid_in":false},{"source_id":"ee51ad04","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","passage":"While researching a topic, a student has taken the following notes:\nThe nautical mile (6,076 feet) is the measure of distance used in seafaring navigation.\nA nautical mile directly correlates to one minute (1/60th of a degree) of latitude.\nThe curvature of Earth affects the accurate measurement of long distances when using flat maps.\nMeasuring distances with latitude and longitude coordinates takes into account Earth’s curvature.\nMariners use nautical charts marked with latitude and longitude to quickly calculate distances and positions.","passage_html":null,"question_text":"The student wants to explain why nautical miles are used to measure distances in seafaring navigation. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Nautical miles are a measure of distance equal to one minute of latitude, which is a feature nautical charts use to calculate distances and positions."},{"label":"B","text":"Since they directly correlate to the coordinates on nautical charts, which take into account Earth’s curvature, nautical miles are an efficient way to calculate distances at sea."},{"label":"C","text":"Using nautical miles for navigation at sea takes Earth’s curvature into account, whereas measuring distances with latitude and longitude coordinates does not."},{"label":"D","text":"Nautical charts use latitude and longitude to measure long distances; these charts are more accurate than flat maps for measuring distances in seafaring navigation because they account for Earth’s curvature."}],"correct_answer":"B","explanation":"Choice B is the best answer. The sentence explains why nautical miles are used to measure distances in seafaring navigation, noting that they directly correlate to the coordinates on nautical charts that take into account Earth’s curvature, making them an efficient way to calculate distances at sea.\nChoice A is incorrect. While the sentence describes what nautical miles are and their relationship to nautical charts, it doesn’t explain why nautical miles are used to measure distances in seafaring navigation. Choice C is incorrect. While the sentence indicates a reason why nautical miles are used, it misrepresents information from the notes: measuring distances with latitude and longitude does in fact account for Earth’s curvature. Choice D is incorrect. The sentence explains why nautical charts are more accurate than flat maps; it doesn’t explain why nautical miles specifically are used to measure distances in seafaring navigation.","is_grid_in":false},{"source_id":"991e849a","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"Mary Anning (1799–1847), one of the world’s first paleontologists, lived in Lyme Regis along the Jurassic Coast of southern England. ______ she made several important discoveries, including some of the first documented ichthyosaur and plesiosaur skeletons. Indeed, Anning’s groundbreaking work secured the Jurassic Coast a place in the annals of paleontology.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"For example,"},{"label":"B","text":"Likewise,"},{"label":"C","text":"There,"},{"label":"D","text":"Later,"}],"correct_answer":"C","explanation":"Choice C is the best answer. “There” logically signals where the events described in this sentence (Anning making several important discoveries) occurred: in Lyme Regis along the Jurassic Coast of southern England, which the previous sentence indicates is where she lived.\nChoice A is incorrect because “for example” illogically signals that the information in this sentence about Anning’s discoveries exemplifies the previous information about her living in Lyme Regis. Instead, the sentence refers to the discoveries Anning made while living there—as the information in the third sentence makes clear. Choice B is incorrect because “likewise” illogically signals that the information about Anning’s discoveries is similar to the previous information about her living in Lyme Regis. Instead, the sentence refers to the discoveries Anning made while living there—as the information in the third sentence makes clear. Choice D is incorrect because “later” illogically signals that the information in this sentence about Anning’s discoveries occurred after she lived in Lyme Regis, as described in the previous sentence. Instead, the sentence refers to the discoveries Anning made while living there—as the information in the third sentence makes clear.","is_grid_in":false},{"source_id":"e225cf02","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","passage":"A team of ornithologists documented patterns of conspecific brood parasitism among wood ducks (Aix sponsa) in California. The researchers observed several female wood ducks visiting dozens of nesting sites and laying eggs to be incubated by other nesting A. sponsa. Subject 7F64B, ______ visited a select few nesting sites before laying and incubating her eggs herself.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"in particular,"},{"label":"B","text":"alternatively,"},{"label":"C","text":"for example,"},{"label":"D","text":"similarly,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “Alternatively” logically signals that the information in this sentence—that Subject 7F64B incubated her own eggs—describes a contrasting alternative to the brood parasitism behavior described in the previous sentence, in which female wood ducks laid eggs to be incubated by other nesting ducks.\nChoice A is incorrect because “in particular” illogically signals that Subject 7F64B’s behavior provides a specific, focused detail about, or example of, the brood parasitism behavior described in the previous sentence. Instead, Subject 7F64B’s behavior represents a contrasting alternative to that brood parasitism. Choice C is incorrect because “for example” illogically signals that Subject 7F64B’s behavior provides a specific example of the brood parasitism behavior described in the previous sentence. Instead, Subject 7F64B’s behavior represents a contrasting alternative to that brood parasitism. Choice D is incorrect because “similarly” illogically signals that Subject 7F64B’s behavior is similar to the brood parasitism behavior described in the previous sentence. Instead, Subject 7F64B’s behavior represents a contrasting alternative to that brood parasitism.","is_grid_in":false},{"source_id":"742695d7","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"easy","passage":"While researching a topic, a student has taken the following notes:\nSpiders are classified as arachnids.\nThere are other types of arachnids besides spiders.\nHarvestmen are a type of arachnid.\nHarvestmen are also known as daddy longlegs.\nHarvestmen are not spiders.","passage_html":null,"question_text":"The student wants to explain what harvestmen are. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Spiders, also known as harvestmen, are classified as arachnids."},{"label":"B","text":"There are other types of arachnids besides spiders, such as daddy longlegs."},{"label":"C","text":"The spiders known as daddy longlegs are classified as harvestmen."},{"label":"D","text":"Harvestmen, also known as daddy longlegs, are arachnids but not spiders."}],"correct_answer":"D","explanation":"Choice D is the best answer. The sentence explains what harvestmen are, noting that they are also known as daddy longlegs and that they are arachnids but not spiders.\nChoice A is incorrect. While the sentence does mention harvestmen, its main focus is on spiders. Moreover, it misrepresents information from the notes: harvestmen are not spiders. Choice B is incorrect. The sentence focuses on the broader point that arachnids include more than just spiders; it doesn’t mention harvestmen directly or explain what they are. Choice C is incorrect. The sentence focuses on how daddy longlegs are classified; it doesn’t explain what harvestmen are. Moreover, it misrepresents information from the notes. The notes indicate that harvestmen are not spiders, and “harvestmen” is presented in the notes as an alternate name for “daddy longlegs,” not a category in which daddy longlegs belong.","is_grid_in":false},{"source_id":"0a9b36f9","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"Introduced in 2001, Luis von Ahn’s reCAPTCHA security software distinguished human users from autonomous spamming programs, or bots, by prompting a website’s visitors to read distorted text and type it in a box. Over time, though, bots became capable of deciphering distorted text. ______ a version of reCAPTCHA that could detect humans by analyzing cursor movements was released in 2014.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"For example,"},{"label":"B","text":"In other words,"},{"label":"C","text":"In response,"},{"label":"D","text":"Indeed,"}],"correct_answer":"C","explanation":"Choice C is the best answer. “In response” logically signals that the information in this sentence—that a new version of reCAPTCHA capable of analyzing cursor movements was released in 2014—was a direct response to the previously described issue of bots becoming capable of deciphering distorted text.\nChoice A is incorrect because “for example” illogically signals that the information in this sentence exemplifies the previously described issue of bots deciphering distorted text. Instead, the release of the new version of reCAPTCHA was a direct response to that issue. Choice B is incorrect because “in other words” illogically signals that the information in this sentence is a paraphrase or restatement of the previously described issue of bots deciphering distorted text. Instead, the release of the new version of reCAPTCHA was a direct response to that issue. Choice D is incorrect because “indeed” illogically signals that the information in this sentence offers additional emphasis in support of the previously described issue of bots deciphering distorted text. Instead, the release of the new version of reCAPTCHA was a direct response to that issue.","is_grid_in":false},{"source_id":"b4123d99","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"For millennia, acorns were a staple food for the Tongva people, the Indigenous inhabitants of what is now the Los Angeles basin. Raw acorns have an extremely bitter taste, though, due to their high tannin levels. ______ it was necessary to process the acorns—which involved grinding, rinsing, and shaping the nuts into a dough—before eating them.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Therefore,"},{"label":"B","text":"Similarly,"},{"label":"C","text":"Afterward,"},{"label":"D","text":"However,"}],"correct_answer":"A","explanation":"Choice A is the best answer. “Therefore” logically signals that the information in this sentence—that it was necessary to process the acorns before eating them—is a result or consequence of the previous information about raw acorns having an extremely bitter taste due to high tannin levels.\nChoice B is incorrect because “similarly” illogically signals that the need to process acorns is similar to the previous information about their bitter taste. Instead, the need to process the acorns is a result or consequence of their bitter taste. Choice C is incorrect because “afterward” illogically signals that the need to process acorns is an event that occurred later in a chronological sequence than the acorns’ bitter taste. Instead, the need to process the acorns is a result or consequence of their bitter taste. Choice D is incorrect because “however” illogically signals that the need to process acorns contrasts with the previous information about their bitter taste. Instead, the need to process the acorns is a result or consequence of their bitter taste.","is_grid_in":false},{"source_id":"70c19cf6","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","passage":"One proposed boundary between Earth’s atmosphere and outer space is the Kármán line, 100 km above sea level. Based on the work of physicist Theodore von Kármán, this line marks the theoretical height at which an aircraft no longer remains aloft using the force of lift. ______ an aircraft sustains flight past this altitude primarily by its velocity, reaching a speed sufficient to maintain an orbit but not to generate enough lift from the thin air.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"For instance,"},{"label":"B","text":"Instead,"},{"label":"C","text":"Granted,"},{"label":"D","text":"Regardless,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “Instead” logically signals that the information in this sentence—that an aircraft sustains flight past the Kármán line primarily by its velocity—is an alternative means of sustaining flight past this line, which the previous sentence indicates is the theoretical height at which an aircraft no longer remains aloft by using the force of lift.\nChoice A is incorrect because “for instance” illogically signals that the information about an aircraft sustaining flight by velocity exemplifies the previous information about the Kármán line marking the theoretical height at which an aircraft no longer remains aloft using lift. Rather, the sentence describes an alternative means of sustaining flight past this line. Choice C is incorrect because “granted” illogically signals that the information about an aircraft sustaining flight by velocity is a concession or acknowledgment that qualifies the previous information about the Kármán line marking the theoretical height at which an aircraft no longer remains aloft using lift. Rather, the sentence describes an alternative means of sustaining flight past this line. Choice D is incorrect because “regardless” illogically signals that the information about an aircraft sustaining flight by velocity is true despite the previous information about the Kármán line marking the theoretical height at which an aircraft no longer remains aloft using lift. Rather, the sentence describes an alternative means of sustaining flight past this line.","is_grid_in":false},{"source_id":"1c60119d","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","passage":"While researching a topic, a student has taken the following notes:\nJacob Lawrence was a US painter best known for The Migration Series (1940–41).\nThe Migration Series portrays scenes from the Great Migration of African Americans from the rural South to cities in the North and Midwest.\nThe series consists of 60 colorful semiabstract paintings, numbered 1 through 60.\nThe odd-numbered paintings are on display at the Phillips Collection in Washington, DC.\nThe even-numbered paintings are on display at the Museum of Modern Art in New York City.\nPainting #12 depicts people buying tickets in a crowded train station.","passage_html":null,"question_text":"The student wants to indicate where to go to view Painting #12 from Lawrence’s Migration Series. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Depicting a crowded train station, Painting #12 from The Migration Series is on display at the Museum of Modern Art in New York City."},{"label":"B","text":"In Painting #12 and the other works of The Migration Series, Lawrence painted African Americans going from the rural South to cities in the North and Midwest."},{"label":"C","text":"To view an even-numbered painting from Lawrence’s Migration Series, such as the one that depicts people buying train tickets, one must go to Washington, DC."},{"label":"D","text":"The 60 colorful semiabstract paintings of Lawrence’s series can be viewed in two places: the Phillips Collection in Washington, DC, and the Museum of Modern Art in New York City."}],"correct_answer":"A","explanation":"Choice A is the best answer. The sentence indicates where to go to view Painting #12 from Lawrence’s Migration Series, noting that this even-numbered painting is on display at the Museum of Modern Art in New York City.\nChoice B is incorrect. The sentence describes the subject matter of The Migration Series; it doesn’t indicate where to go to view Painting #12. Choice C is incorrect. The sentence misrepresents information from the notes: even-numbered paintings, such as Painting #12, are on display at the Museum of Modern Art in New York City, not in Washington, DC. Choice D is incorrect. While the sentence mentions both locations where paintings from the series are displayed, it doesn’t indicate where to go to view Painting #12 specifically.","is_grid_in":false},{"source_id":"19b08ead","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","passage":"While researching a topic, a student has taken the following notes:\nProducing the nutrient-rich cyanobacterium L. maxima at industrial scale requires high-quality samples of L. maxima DNA.\nYirlis Yadeth Pineda-Rodriguez and a team of researchers at the University of Córdoba, Colombia, evaluated the quantity and purity of L. maxima DNA extracted using three different DNA extraction kits.\nCTAB 2X (kit 1) had a DNA yield of 2,134 nanograms per microliter (ng/µL) and a purity ratio of 2.2.\nPbact (kit 2) had a DNA yield of 157 ng/µL and a purity ratio of 1.6.\nPplant (kit 3) had a DNA yield of 12.5 ng/µL and a purity ratio of 1.5.\nAccording to the researchers, Pbact was the most effective because it was the only one with both a sufficiently high yield and a purity rate close to the ideal of 1.8.","passage_html":null,"question_text":"The student wants to emphasize the significance of a similarity between two of the kits. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Due to their insufficient yield or purity, CTAB 2X and Pplant were deemed by the researchers to be less effective than Pbact."},{"label":"B","text":"Compared to CTAB 2X, which had a DNA yield of 2,134 ng/µL, both Pbact and Pplant had insufficient yields; Pplant, in particular, was ineffective due to its low yield."},{"label":"C","text":"CTAB 2X and Pplant both had a DNA yield above 10 and a purity ratio above 1.4."},{"label":"D","text":"With the ideal purity ratio being 1.8, CTAB 2X and Pbact were equal in purity, according to the researchers."}],"correct_answer":"A","explanation":"Choice A is the best answer. The sentence emphasizes the significance of a similarity between CTAB 2X and Pplant, noting that both were deemed less effective than Pbact due to their insufficient yield or purity. According to the notes, the researchers concluded that Pbact was the most effective kit because it was the only one with both a sufficiently high yield and a purity ratio close to 1.8. Since Pbact was the only kit to meet both criteria, it follows that CTAB 2X and Pplant each fell short on at least one critical measure.\nChoice B is incorrect. The sentence presents a similarity between two of the kits (Pbact and Pplant), but in doing so, it misrepresents information from the notes. The researchers deemed Pbact the most effective kit overall, not one with an insufficient yield. Choice C is incorrect. While the sentence identifies a similarity between CTAB 2X and Pplant (that both had a DNA yield above 10 and a purity ratio above 1.4), it doesn’t emphasize the significance of that similarity. Choice D is incorrect. The sentence presents a similarity between the CTAB 2X and Pbact kits, but in doing so, it misrepresents information from the notes. CTAB 2X had a purity ratio of 2.2, while Pbact had a purity ratio of 1.6, so they were not equal in purity.","is_grid_in":false},{"source_id":"c61fb134","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"As Iestyn Barr and his team of researchers discovered when establishing the glacial timeline of Antarctica, the Transantarctic Mountains—a 3,500-km mountain range spanning the continent—are home to glaciers of at least 60 million years in age. ______ the researchers concluded, Antarctica had glaciers long before the formation of its continent-wide ice sheet 34 million years ago.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"By contrast,"},{"label":"B","text":"Thus,"},{"label":"C","text":"Nevertheless,"},{"label":"D","text":"Even so,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “Thus” logically signals that the information in this sentence—that the researchers concluded that Antarctica had glaciers long before the formation of its continent-wide ice sheet—is a result of the previous information about the discovery that Antarctica’s glaciers are at least 60 million years old, whereas its continent-wide ice sheet formed just 34 million years ago.\nChoice A is incorrect because “by contrast” illogically signals that the researchers’ conclusion about Antarctica having glaciers before its ice sheet formed contrasts with the previous finding about the age of Antarctica’s glaciers. Instead, the conclusion is a result of that finding. Choice C is incorrect because “nevertheless” illogically signals that the researchers’ conclusion about Antarctica having glaciers before its ice sheet formed is true despite the previous finding about the age of Antarctica’s glaciers. Instead, the conclusion is a result of that finding. Choice D is incorrect because “even so” illogically signals that the researchers’ conclusion about Antarctica having glaciers before its ice sheet formed is true despite the previous finding about the age of Antarctica’s glaciers. Instead, the conclusion is a result of that finding.","is_grid_in":false},{"source_id":"8fbf206d","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","passage":"In Color Charts: A History (2024), anthropologist Anne Varichon uses vivid prose to describe various systems and tools that have been used over the past few centuries for categorizing colors. ______ Varichon’s book features many high-quality images of these color presentation tools—from fanlike arrangements of hued fabric swatches to clusters of dyed feathers.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Consequently,"},{"label":"B","text":"Additionally,"},{"label":"C","text":"That said,"},{"label":"D","text":"Specifically,"}],"correct_answer":"B","explanation":"Choice B is the best answer. “Additionally” logically signals that the information in this sentence—that Varichon’s book features many high-quality images of color presentation tools—is an additional feature of the book, supplementing the vivid prose descriptions of these tools mentioned in the previous sentence.\nChoice A is incorrect because “consequently” illogically signals that the information about the book’s high-quality images is a result or consequence of the previous statement about Varichon’s vivid prose descriptions. Instead, the images are an additional feature of the book. Choice C is incorrect because “that said” illogically signals that the information about the book’s high-quality images is an exception to or qualification of the previous statement about Varichon’s vivid prose descriptions. Instead, the images are an additional feature of the book. Choice D is incorrect because “specifically” illogically signals that the information about the book’s high-quality images provides specific, precise details about the vivid prose descriptions mentioned in the previous sentence. Instead, the images are an additional feature of the book.","is_grid_in":false},{"source_id":"bfab730e","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"Paleontologists Jordan C. Mallon and David W.E. Hone used computer models to produce detailed Tyrannosaurus rex size estimates, incorporating factors such as growth rate, lifespan, and the size of available fossils. ______ the researchers determined that the largest T. rex possible could have been 70% heavier than the current largest-known specimens.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"In addition to these factors,"},{"label":"B","text":"Despite these estimates,"},{"label":"C","text":"Further complicating these issues,"},{"label":"D","text":"Based on these models,"}],"correct_answer":"D","explanation":"Choice D is the best answer. “Based on these models” logically signals that the research finding described in this sentence—that the largest T. rex could have been 70% heavier than the current largest-known specimens—is derived from the computer models described in the previous sentence.\nChoice A is incorrect because “in addition to these factors” illogically signals that the research finding about T. rex size presented in this sentence introduces factors beyond those noted in the previous sentence (growth rate, lifespan, and the size of available fossils). Instead, the finding is derived from the researchers’ models, which incorporated those factors. Choice B is incorrect because “despite these estimates” illogically signals that the research finding about T. rex size presented in this sentence is true despite the previous information about the researchers’ model-generated size estimates. Instead, the finding is derived from the researchers’ models. Choice C is incorrect because “further complicating these issues” illogically signals that the previous information about the researchers’ computer models presents difficulties and that the research finding about T. rex size presented in this sentence adds to those difficulties. Instead, the finding is simply derived from the researchers’ use of the models.","is_grid_in":false},{"source_id":"5803befc","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","passage":"Resins play several important roles in maintaining the health of conifers and many other kinds of trees. ______ resins quickly seal wounds, which helps prevent harmful insects and fungi from entering trees. These sticky substances also help trees retain water that is needed for them to survive.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"However,"},{"label":"B","text":"Regardless,"},{"label":"C","text":"Next,"},{"label":"D","text":"For example,"}],"correct_answer":"D","explanation":"Choice D is the best answer. “For example” logically signals that the information in this sentence—that resins quickly seal wounds to help prevent harmful insects and fungi from entering trees—provides a specific example to support the previous sentence’s claim about resins playing several important roles in maintaining tree health.\nChoice A is incorrect because “however” illogically signals that the information in this sentence contrasts with the previous claim about resins playing several important roles in maintaining tree health. Instead, the sentence provides a specific example of one such role. Choice B is incorrect because “regardless” illogically signals that the information in this sentence is true despite the previous claim about resins playing several important roles in maintaining tree health. Instead, the sentence provides a specific example of one such role. Choice C is incorrect because “next” illogically signals that the information in this sentence is the next step in a process. Instead, the sentence provides a specific example to support the previous claim that resins play several important roles in maintaining tree health.","is_grid_in":false},{"source_id":"7f5715e4","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","passage":"While researching a topic, a student has taken the following notes:\nThe farm-size transition hypothesis predicts that economic pressures associated with modernization result in smaller farms amalgamating into larger-scale commercial farms.\nMasters et al. (2013): The average farm size in Asia “already has or will soon begin to rise.”\nPromkhambut et al. (2023) argue that small rice farms in Thailand have adopted modern farming methods without a significant scaling-up of farm size.\nPromkhambut et al.: “The persistence of [small] rice farms [in Thailand] does not represent a ‘failure’ to modernize...or a ‘truncated’ transition—it is a response to modernization.”","passage_html":null,"question_text":"The student wants to make and support a claim regarding the applicability of the farm-size transition hypothesis to Thailand. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Taken together, the studies by Masters et al. and Promkhambut et al. suggest that rice farms in Thailand have responded to the economic pressures associated with modernization by expanding in size."},{"label":"B","text":"Masters et al. report that the average farm size “already has or will soon begin to rise” in Asia, a finding that is consistent with the farm-size transition hypothesis."},{"label":"C","text":"The predicted shift to large-scale commercial farming may not hold true for rice farms in Thailand, where, according to Promkhambut et al., rice farms have remained small as they’ve modernized."},{"label":"D","text":"Although the farm-size transition hypothesis may be applicable to some countries in Asia, it is inconsistent with the development of rice farming in Thailand."}],"correct_answer":"C","explanation":"Choice C is the best answer. The sentence makes a claim about the applicability of the farm-size transition hypothesis—the prediction that smaller farms will amalgamate into larger-scale commercial farms as a response to the economic pressures of modernization—to Thailand, noting that the hypothesis may not hold true for Thailand. It supports the claim with the argument from Promkhambut et al. that Thailand’s rice farms have remained small despite modernizing.\nChoice A is incorrect. While the sentence makes a claim about the applicability of the farm-size transition hypothesis to Thailand, it mischaracterizes information from the notes: Promkhambut et al. argue that, despite modernizing in response to economic pressures, rice farms in Thailand have not expanded in size. Choice B is incorrect. The sentence connects a claim from Masters et al. to the farm-size transition hypothesis; it doesn’t make and support a claim about the applicability of the hypothesis to Thailand, specifically. Choice D is incorrect. While the sentence makes a claim about the applicability of the farm-size transition hypothesis to Thailand, it doesn’t support the claim.","is_grid_in":false},{"source_id":"b6d9068e","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","passage":"On a chilly spring morning in a Virginia park, as sunlight crested the treetops, Kathrin Swoboda raised her Nikon D500 camera and captured an image that would win the Grand Prize in the 2019 Audubon Photography Awards: a red-winged blackbird, exhaling what appeared to be rings of smoke. ______ the “smoke” was actually the blackbird’s breath hitting the cold morning air as the bird sang.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Furthermore,"},{"label":"B","text":"For example,"},{"label":"C","text":"Therefore,"},{"label":"D","text":"Of course,"}],"correct_answer":"D","explanation":"Choice D is the best answer. “Of course” logically signals that the information in this sentence—that the smokelike effect in the image was actually the blackbird’s breath hitting the cold morning air—is an expected or self-evident clarification of the previous description of the bird appearing to exhale rings of smoke.\nChoice A is incorrect because “furthermore” illogically signals that the information in this sentence about the smokelike effect merely adds to the previous description of the image. Instead, the sentence clarifies what produced the smokelike effect in the image. Choice B is incorrect because “for example” illogically signals that the information in this sentence about the smokelike effect provides a specific example of the previous description of the image. Instead, the sentence clarifies what produced the smokelike effect in the image. Choice C is incorrect because “therefore” illogically signals that the information in this sentence about the smokelike effect is a result or consequence of the previous description of the image. Instead, the sentence clarifies what produced the smokelike effect in the image.","is_grid_in":false},{"source_id":"0f64ded3","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","passage":"While researching a topic, a student has taken the following notes:\nAlbert Einstein’s theory of general relativity allows for potential shortcuts through spacetime.\nThese hypothetical spacetime tunnels are known as wormholes.\nFor matter to travel through a wormhole, it would need to have negative energy density.\nNegative energy density means that the matter would have less energy than empty space.\nSuch matter has not been shown to exist.","passage_html":null,"question_text":"The student wants to acknowledge a complication affecting travel through wormholes. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Einstein’s theory of general relativity allows for potential spacetime shortcuts called wormholes but does not explain how matter with negative energy density could travel through them."},{"label":"B","text":"For matter to travel through a wormhole, the matter would need to have less energy than empty space; such matter has not been shown to exist."},{"label":"C","text":"The hypothetical tunnels known as wormholes would be potential shortcuts through spacetime were it not for one complication: they have less energy than empty space."},{"label":"D","text":"For wormholes to be possible, according to Einstein’s theory of general relativity, they would have to allow for potential shortcuts through spacetime."}],"correct_answer":"B","explanation":"Choice B is the best answer. The sentence acknowledges a complication affecting travel through wormholes, noting that the matter traveling through a wormhole would need to have less energy than empty space and that such matter has not been shown to exist.\nChoice A is incorrect. The sentence notes that Einstein’s theory doesn’t explain how matter with negative energy density can travel through wormholes; it doesn’t acknowledge a complication affecting travel through wormholes. Choice C is incorrect. While the sentence acknowledges a complication affecting travel through wormholes, it misrepresents information from the notes; matter traveling through wormholes, not the wormholes themselves, would need to have negative energy density. Choice D is incorrect. The sentence presents a misleading interpretation of Einstein’s theory (confusing the definition of a wormhole with a condition a wormhole must fulfill); it doesn’t acknowledge a complication affecting travel through wormholes.","is_grid_in":false},{"source_id":"d4b07ce6","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","passage":"While researching a topic, a student has taken the following notes:\nShanawdithit (1801–1829) was a Beothuk cartographer (mapmaker).\nHer maps of Newfoundland’s Beothuk Lake outline both the lake and various points around the lake where encounters between the Indigenous Beothuk people and British colonists occurred.\nHer maps are notable for depicting the experiences the Beothuk had within the landscape.\nContemporary Potawatomi cartographer Margaret Pearce: Indigenous cartography emphasizes “experienced space, or place, as opposed to the Western convention of depicting space as universal, homogenized, and devoid of human experience.”\nPearce: “Indigenous cartographies are as diverse as Indigenous cultures, from Hawaiian performative cartographies to Navajo verbal maps and sand paintings.”","passage_html":null,"question_text":"The student wants to describe Shanawdithit’s approach and explain its significance. Which choice most effectively uses relevant information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"Shanawdithit’s maps are part of a broader tradition of Indigenous cartography that, according to Pearce, ranges from “Hawaiian performative cartographies to Navajo verbal maps and sand paintings.”"},{"label":"B","text":"Shanawdithit mapped Beothuk Lake through significant encounters that occurred there, an approach described as “depicting space as universal [and] homogenized.”"},{"label":"C","text":"According to Pearce, Indigenous cartography, such as Shanawdithit’s maps of Beothuk Lake, emphasizes “experienced space, or place,” with a variety of approaches that reflect the diversity of Indigenous cultures."},{"label":"D","text":"By depicting experiences of the Beothuk that occurred around Beothuk Lake, Shanawdithit’s maps reflect Indigenous cartography’s emphasis on “experienced space, or place” rather than the landscape alone."}],"correct_answer":"D","explanation":"Choice D is the best answer. The sentence accomplishes both parts of the goal. It describes Shanawdithit’s approach by noting that she depicted experiences of the Beothuk that occurred around Beothuk Lake, and it explains the significance of that approach by connecting it to Indigenous cartography’s emphasis on “experienced space, or place.”\nChoice A is incorrect. While the sentence places Shanawdithit’s maps within the broader tradition of Indigenous cartography, it doesn’t describe her specific approach to mapmaking or explain its significance. Choice B is incorrect. While the sentence does describe Shanawdithit’s approach to mapmaking, it misrepresents information in the notes when explaining the significance of that approach. “Depicting space as universal [and] homogenized” is described as a Western convention, not a convention of Indigenous cartography. Choice C is incorrect. While the sentence mentions Shanawdithit’s maps as an example of Indigenous cartography, it focuses primarily on the broader tradition rather than describing Shanawdithit’s specific approach and explaining its significance.","is_grid_in":false},{"source_id":"578ca79a","section":"reading_writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","passage":"Charles Demuth’s 1931 painting Chimney and Water Tower is a classic Precisionist work. The Precisionists strove for cold, machine-like perfection, with crisp lines, geometric shapes, and smooth, brushstroke-free surfaces. ______ Precisionist works often feature skyscrapers, bridges, and factories, highlighting these angular structures’ engineered symmetry.","passage_html":null,"question_text":"Which choice completes the text with the most logical transition?","question_text_html":null,"choices":[{"label":"A","text":"Accordingly,"},{"label":"B","text":"In the end,"},{"label":"C","text":"That said,"},{"label":"D","text":"However,"}],"correct_answer":"A","explanation":"Choice A is the best answer. “Accordingly” logically signals that the information in this sentence—that Precisionist works often feature angular, symmetrical structures, such as skyscrapers, bridges, and factories—is in accordance with the previous claim about the Precisionist style of “cold, machine-like perfection, with crisp lines, geometric shapes, and smooth, brushstroke-free surfaces.”\nChoice B is incorrect because “in the end” illogically signals that the information in this sentence is a final conclusion or summary of the previous claim about the Precisionist style. Instead, the sentence describes features in Precisionist works that are in accordance with that style. Choice C is incorrect because “that said” illogically signals that the information in this sentence is an exception to or qualification of the previous claim about the Precisionist style. Instead, the sentence describes features in Precisionist works that are in accordance with that style. Choice D is incorrect because “however” illogically signals that the information in this sentence contrasts with the previous claim about the Precisionist style. Instead, the sentence describes features in Precisionist works that are in accordance with that style.","is_grid_in":false},{"source_id":"bfad4508","section":"reading_writing","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","passage":"While researching a topic, a student has taken the following notes:\nBrass is a metal alloy composed primarily of zinc and copper.\nAlpha brass contains less than 35% zinc.\nIt is more malleable than beta brass and can be manipulated at room temperature.\nBeta brass contains more than 45% zinc.\nIt is harder and stronger than alpha brass but is more difficult to work with because it requires heat to manipulate.","passage_html":null,"question_text":"The student wants to specify an advantage of alpha brass. Which choice most effectively uses information from the notes to accomplish this goal?","question_text_html":null,"choices":[{"label":"A","text":"As a metal alloy composed primarily of zinc and copper, alpha brass has a notable advantage over beta brass."},{"label":"B","text":"Unlike beta brass, which requires heat to manipulate, alpha brass can be shaped at room temperature."},{"label":"C","text":"Alpha brass contains less than 35% zinc, whereas beta brass contains more than 45% zinc."},{"label":"D","text":"With its higher zinc content, alpha brass is a stronger material than beta brass."}],"correct_answer":"B","explanation":"Choice B is the best answer. The sentence specifies an advantage of alpha brass, noting that unlike beta brass, which requires heat to manipulate, alpha brass can be shaped at room temperature.\nChoice A is incorrect. While the sentence indicates that alpha brass has an advantage over beta brass, it doesn’t specify what that advantage is. Both alpha brass and beta brass are metal alloys composed primarily of zinc and copper. Choice C is incorrect. The sentence contrasts the zinc content of alpha and beta brass; it doesn’t specify an advantage of alpha brass. Choice D is incorrect. While the sentence does specify an advantage, it misrepresents information from the notes: beta brass, not alpha brass, has the higher zinc content and is the stronger material.","is_grid_in":false},{"source_id":"c3397d25","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"medium","passage":"Since the nineteenth century, Egyptologists have commonly divided ancient Egyptian history into three primary ______ Old Kingdom (2700–2200 BCE), the Middle Kingdom (2050–1800 BCE), and the New Kingdom (1550–1100 BCE). Some historians, however, criticize the names of these periods for revealing more about the culture of the mainly European Egyptologists than that of ancient Egypt itself.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"periods. The"},{"label":"B","text":"periods: the"},{"label":"C","text":"periods; the"},{"label":"D","text":"periods, the"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is punctuation use between a main clause and an enumerated series. In this choice, a colon is correctly used after the main clause (“Since...periods”) to introduce the series identifying the three primary periods of ancient Egyptian history.\nChoice A is incorrect because placing a period after “periods” results in a rhetorically unacceptable sentence fragment beginning with “the Old Kingdom.” Choice C is incorrect because a semicolon can’t be used in this way to introduce a series. A semicolon is conventionally used to join two main clauses or to separate items in a complex series, neither of which is the case here. Choice D is incorrect because a comma is not conventionally used to mark the boundary between the main clause (“Since...periods”) and an enumerated series (“the Old Kingdom...(1550–1100 BCE)”) that contains internal commas. Using a comma in this way creates ambiguity about which commas separate elements in the series and which mark other boundaries in the sentence, making the colon the best choice.","is_grid_in":false},{"source_id":"9127635a","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"Star actress Kiki Omeili, who has appeared in 47 Nollywood films, is one of numerous luminaries to be pictured in Nigerian portraitist Iké Udé’s exhibition Nollywood Portraits. ______ referred to Nollywood—Nigeria’s $3 billion film industry—as “Africa’s vivid mirror par excellence,” honors its legacy with his vivid classical portraits of Omeili and her peers.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"Udé, has"},{"label":"B","text":"Udé has"},{"label":"C","text":"Udé"},{"label":"D","text":"Udé, having"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of verb forms and punctuation within a sentence. The sentence’s subject is “Udé,” and its finite main verb is “honors.” This choice correctly uses the nonfinite participle “having referred” to form a supplementary element (“having...excellence”) describing Udé. The comma after “Udé” appropriately marks the boundary before that supplementary element.\nChoice A is incorrect because using the finite verb “has referred” creates an ungrammatical sentence. The sentence already has the finite main verb “honors,” so “has referred” can’t also function as a second main verb here without additional punctuation or conjunctions. Moreover, no punctuation is needed when a subject (“Udé”) is immediately followed by a finite verb (“has referred”). Choice B is incorrect because using the finite verb “has referred” creates an ungrammatical sentence. The sentence already has the finite main verb “honors,” so “has referred” can’t also function as a second main verb here without additional punctuation or conjunctions. Choice C is incorrect because using the finite verb “referred” creates an ungrammatical sentence. The sentence already has the finite main verb “honors,” so “referred” can’t also function as a second main verb here without additional punctuation or conjunctions.","is_grid_in":false},{"source_id":"36e89f74","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"easy","passage":"An imposing spire of igneous rock rising high above the Belle Fourche River in eastern Wyoming, Devils Tower (also known as Bear Lodge) is one of the most prominent examples of columnar jointing, a pattern of fracturing in rocks that ______ in parallel arrays of long polygonal prisms.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"resulting"},{"label":"B","text":"were resulting"},{"label":"C","text":"results"},{"label":"D","text":"to result"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. Relative clauses, such as the one beginning with “that,” require a finite (tensed) verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite present tense verb “results.” Furthermore, the simple present tense verb “results” correctly indicates that the formation of parallel arrays of long polygonal prisms is an enduring property of this fracturing pattern.\nChoice A is incorrect because it results in an ungrammatical sentence. The nonfinite participle “resulting” doesn’t supply the clause with a finite verb. Choice B is incorrect because the past progressive tense verb “were resulting” doesn’t indicate that the formation of parallel arrays of long polygonal prisms is an enduring property of this fracturing pattern. Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive “to result” doesn’t supply the clause with a finite verb.","is_grid_in":false},{"source_id":"16740ab4","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"At the Chicxulub asteroid impact crater in Mexico, the presence of many fossilized microbacteria, which seem to have thrived there despite the extreme heat that persisted after the Chicxulub impact, ______ claims that bacteria are among the planet’s most resilient organisms.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"have reinforced"},{"label":"B","text":"reinforces"},{"label":"C","text":"are reinforcing"},{"label":"D","text":"reinforce"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is subject-verb agreement. The singular verb “reinforces” agrees in number with the singular subject “the presence.”\nChoice A is incorrect because the plural verb “have reinforced” doesn’t agree in number with the singular subject “the presence.” Choice C is incorrect because the plural verb “are reinforcing” doesn’t agree in number with the singular subject “the presence.” Choice D is incorrect because the plural verb “reinforce” doesn’t agree in number with the singular subject “the presence.”","is_grid_in":false},{"source_id":"e2f77ae7","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"medium","passage":"That Chaucer’s Canterbury Tales inspired imitators is evident from the existence of three near-contemporary “continuations” of the collection: The Siege of Thebes, which purports to be a new tale told during the pilgrims’ ______ The Tale of Beryn, which depicts the pilgrims as tourists; and The Ploughman’s Tale, which features a minor character from the original work.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"return."},{"label":"B","text":"return"},{"label":"C","text":"return;"},{"label":"D","text":"return,"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the punctuation of elements in a complex series. It’s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after “return” is conventionally used to separate the first item (“The Siege of Thebes...return”) and the second item (“The Tale of Beryn...tourists”) in the series of tales. Moreover, the semicolon after “return” matches the semicolon used later to separate the second item and the third item (“and The Ploughman’s Tale...work”) in the series.\nChoice A is incorrect because placing a period after “return” results in a rhetorically unacceptable sentence fragment beginning with “The Tale of Beryn.” Choice B is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Choice D is incorrect because a comma after “return” doesn’t match the semicolon used later to separate the second and third items in the series.","is_grid_in":false},{"source_id":"74253458","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"easy","passage":"Cycads are palmlike plants with cones. ______ plants were abundant throughout the Mesozoic Era (66 to 252 million years ago).","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"These"},{"label":"B","text":"That"},{"label":"C","text":"Each"},{"label":"D","text":"This"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is the use of determiners. The plural demonstrative determiner “these” agrees in number with the plural noun “plants” that it modifies. This choice clearly indicates that the plants, referring to cycads from the previous sentence, were abundant throughout the Mesozoic Era.\nChoice B is incorrect because the singular demonstrative determiner “that” doesn’t agree in number with the plural noun “plants.” Choice C is incorrect because the singular determiner “each” doesn’t agree in number with the plural noun “plants.” Choice D is incorrect because the singular demonstrative determiner “this” doesn’t agree in number with the plural noun “plants.”","is_grid_in":false},{"source_id":"353890a1","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"easy","passage":"Water is constantly moving and changing forms on Earth and in the atmosphere. This process is called the water cycle, and it is typically thought to consist of evaporation, condensation, and precipitation. However, the National Oceanic and Atmospheric Administration seeks ______ understanding of the water cycle to include transpiration, sublimation, and other types of water movement.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"is expanding"},{"label":"B","text":"to expand"},{"label":"C","text":"has expanded"},{"label":"D","text":"expands"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite to-infinitive verb “to expand” is correctly used to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do.\nChoice A is incorrect because it results in an ungrammatical sentence. The finite verb “is expanding” can’t be used in this way to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do. Choice C is incorrect because it results in an ungrammatical sentence. The finite verb “has expanded” can’t be used in this way to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do. Choice D is incorrect because it results in an ungrammatical sentence. The finite verb “expands” can’t be used in this way to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do.","is_grid_in":false},{"source_id":"ee4aa2aa","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"During a 2022 expedition led by research zoologist Andrea Quattrini, scientists discovered a new species of black coral off the coast of Puerto Rico. Like other black corals, the newly discovered species, which they named Aphanipathes puertoricoensis, has coiled branching structures that ______ it survive in the deep sea.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"has helped"},{"label":"B","text":"helps"},{"label":"C","text":"helping"},{"label":"D","text":"help"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. The plural verb “help” provides the relative clause beginning with “that” with a finite verb and agrees in number with the plural subject “coiled branching structures.”\nChoice A is incorrect because the singular verb “has helped” doesn’t agree in number with the plural subject “coiled branching structures.” Choice B is incorrect because the singular verb “helps” doesn’t agree in number with the plural subject “coiled branching structures.” Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite participle “helping” doesn’t supply a finite verb to the relative clause beginning with “that.”","is_grid_in":false},{"source_id":"5ef9fc48","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"In biology, many initially disordered systems will naturally move toward greater order according to the principle of self-organization, a conceptual framework for pattern ______ biologists believe can be used to explain a range of organic phenomena, from population dynamics to the sociality of bees and ants.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"formation, that some"},{"label":"B","text":"formation. Some"},{"label":"C","text":"formation that some"},{"label":"D","text":"formation; some"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the use and punctuation of an integrated relative clause. In this choice, the relative pronoun “that” is used to create an integrated relative clause that modifies the preceding noun phrase “a conceptual framework for pattern formation.” No punctuation is necessary between the noun phrase and the relative clause because the relative clause is supplying essential information about the framework.\nChoice A is incorrect because no punctuation is needed between the noun phrase (“a conceptual…formation”) and the integrated relative clause beginning with “that.” Choice B is incorrect because it results in a confusing and ungrammatical sentence. Choice D is incorrect because it results in an ungrammatical sentence. A semicolon is used to join two main clauses or items in a complex series, and what follows “formation” is neither of these.","is_grid_in":false},{"source_id":"4320b4ad","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"easy","passage":"For decades after World War II, the women who had worked for the US military as wartime codebreakers ______ their vital efforts a secret.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"to keep"},{"label":"B","text":"having kept"},{"label":"C","text":"keeping"},{"label":"D","text":"kept"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject (in this case, “the women”), and this choice supplies the finite past tense verb “kept” to indicate what the women did.\nChoice A is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive “to keep” doesn’t supply the main clause with a finite verb. Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite perfect participle “having kept” doesn’t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite present participle “keeping” doesn’t supply the main clause with a finite verb.","is_grid_in":false},{"source_id":"e67f9967","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"For her film I Am Somebody (1970), a documentary about a successful months-long strike held by Black female hospital workers in Charleston, South Carolina, director Madeline Anderson chose a narrator who had participated in the ______ by allowing the narrative to be shaped by one of their own, amplified the agency and power the workers possessed.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"protest. A decision that"},{"label":"B","text":"protest; a decision that,"},{"label":"C","text":"protest, a decision that,"},{"label":"D","text":"protest a decision that,"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma after “protest” to mark the boundary between the main clause (“For...protest”) and the supplementary appositive (“a decision...possessed”) that provides additional information about Anderson’s choice of narrator. Furthermore, the comma after “that” pairs with the comma after “own” to separate the supplementary adverbial phrase “by allowing...own” from the rest of the appositive. This adverbial phrase functions to explain how Anderson’s choice of a narrator amplified the agency and power the hospital workers possessed, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence.\nChoice A is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “a decision.” Choice B is incorrect because a semicolon can’t be used in this way to join the main clause (“For...protest”) and the supplementary appositive (“a decision...possessed”). A semicolon is conventionally used to join two main clauses, and “a decision...possessed” isn’t a main clause. Choice D is incorrect because it fails to mark the boundary between the main clause (“For...protest”) and the supplementary appositive (“a decision...possessed”) with appropriate punctuation.","is_grid_in":false},{"source_id":"0560b2b8","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"easy","passage":"“What stories like this do for us is make the world just a smidge bigger,” writes Stephen Graham Jones in the foreword to Never Whistle at Night: An Indigenous Dark Fiction Anthology. For Jones, dark fiction does more than entertain readers: ______ horror tropes to challenge familiar ways of knowing, blurring the “borders of the real.”","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"one uses"},{"label":"B","text":"we use"},{"label":"C","text":"they use"},{"label":"D","text":"it uses"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun “it” agrees in number with the singular antecedent “dark fiction” and clearly indicates that dark fiction uses horror tropes to challenge familiar ways of knowing.\nChoice A is incorrect because the singular pronoun “one” is ambiguous in this context; the resulting sentence leaves unclear who or what uses horror tropes to challenge familiar ways of knowing. Choice B is incorrect because the first person plural pronoun “we” isn’t conventional as a substitute for “dark fiction.” It suggests that the readers, rather than dark fiction, use horror tropes to challenge familiar ways of knowing. Choice C is incorrect because the plural pronoun “they” doesn’t agree in number with the singular antecedent “dark fiction.”","is_grid_in":false},{"source_id":"ffea47e1","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"easy","passage":"The Kaiparowits Formation is a fossil-rich layer of sedimentary rock in the Grand Staircase, a colossal sequence of rock layers stretching from Utah’s Bryce Canyon to Arizona’s Grand Canyon. The sandstones and mudstones of the Kaiparowits Formation were deposited ______ the Late Cretaceous, preserving many species from that time.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"during:"},{"label":"B","text":"during;"},{"label":"C","text":"during,"},{"label":"D","text":"during"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is punctuation use between a preposition and its complement. No punctuation is needed between the preposition “during” and its complement “the Late Cretaceous.” The complement completes the meaning of the preposition in the phrase “deposited during the Late Cretaceous,” and any punctuation between the two results in an ungrammatical sentence.\nChoice A is incorrect because no punctuation is needed between the preposition and its complement. Choice B is incorrect because no punctuation is needed between the preposition and its complement. Choice C is incorrect because no punctuation is needed between the preposition and its complement.","is_grid_in":false},{"source_id":"2d6f8304","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"easy","passage":"In 2019, New Zealand produced 88,465 hectograms per hectare (hg/ha) of wheat, and Portugal produced 23,298 hg/ha. This is the type of information on global food production that the United Nations’ Food and Agriculture Organization ______ since 1945.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"is collecting"},{"label":"B","text":"has collected"},{"label":"C","text":"will collect"},{"label":"D","text":"collects"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present perfect tense verb “has collected,” used in conjunction with the phrase “since 1945,” correctly indicates that the Food and Agriculture Organization has collected this type of information in the past and continues to do so in the present.\nChoice A is incorrect because the present progressive tense verb “is collecting” is inconsistent with the phrase “since 1945,” which indicates that the action occurred in the past and continues into the present. Choice C is incorrect because the future tense verb “will collect” is inconsistent with the phrase “since 1945,” which indicates that the action occurred in the past and continues into the present. Choice D is incorrect because the present tense verb “collects” is inconsistent with the phrase “since 1945,” which indicates that the action occurred in the past and continues into the present.","is_grid_in":false},{"source_id":"e41018de","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"In 1977, legendary Puerto Rican performer Rita Moreno won an Emmy Award, making her one of the rare talents to earn the highest honors in television, music, film, and stage entertainment—the Emmy, Grammy, Oscar, and Tony ______ the achievement is known as “winning the EGOT.”","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"awards, respectively;"},{"label":"B","text":"awards; respectively"},{"label":"C","text":"awards, respectively—"},{"label":"D","text":"awards, respectively,"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “respectively” from the rest of the supplementary element introduced by the dash after “entertainment” (“the Emmy...awards”), and it uses a semicolon to join the first main clause (“In...respectively”) and the second main clause (“the achievement...EGOT’”).\nChoice B is incorrect because placing the semicolon after “awards” illogically separates the supplementary adverb “respectively” from the supplementary element it belongs to (“the Emmy...awards”) and attaches it to the following main clause (“the achievement...EGOT’”), resulting in a confusing and ungrammatical sentence. Choice C is incorrect. The dash after “respectively” pairs with the dash after “entertainment” to close the supplementary element (“the Emmy...respectively”), so it can’t also serve to mark the boundary between the two main clauses (“In...respectively” and “the achievement...EGOT’”). The result fails to mark that boundary with appropriate punctuation. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, the comma after “respectively” can’t be used in this way to join the first main clause (“In...respectively”) and the second main clause (“the achievement...EGOT’”).","is_grid_in":false},{"source_id":"6181924a","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"Fernando Palma Rodríguez creates robotic sculptures that combine mechanical elements with materials like feathers, soil, and seeds. The artist is from a rural farming community outside Mexico City, and he studied engineering in college. The natural and mechanical ______ highlight these two aspects of his background.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"materials that Palma Rodríguez uses in his art,"},{"label":"B","text":"materials that Palma Rodríguez uses in his art"},{"label":"C","text":"materials, that Palma Rodríguez uses in his art,"},{"label":"D","text":"materials, that Palma Rodríguez uses in his art"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is the punctuation of an integrated relative clause within a sentence. No punctuation is needed between the noun phrase (“The natural and mechanical materials”) and the integrated relative clause (“that Palma Rodríguez uses in his art”). The integrated relative clause provides essential information about the materials, so no punctuation should separate it from the noun phrase it modifies. Additionally, no punctuation is needed between the sentence’s subject (“The natural and mechanical materials that Palma Rodríguez uses in his art”) and its main verb (“highlight”).\nChoice A is incorrect because no punctuation is needed between the sentence’s subject (“The natural...art”) and its main verb (“highlight”). Choice C is incorrect because no punctuation is needed between the noun phrase (“The natural...materials”) and the integrated relative clause (“that...art”) that modifies it. Additionally, no punctuation is needed between the sentence’s subject (“The natural...art”) and its main verb (“highlight”). Choice D is incorrect because no punctuation is needed between the noun phrase (“The natural...materials”) and the integrated relative clause (“that...art”) that modifies it.","is_grid_in":false},{"source_id":"c7cb5186","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"In a US national election, one might expect major-party campaigns to focus on the most populous states. However, if polls and past voting data suggest that the outcome in a given state is a foregone conclusion, a campaign will not invest its resources there. Ultimately, a state’s voting record and polling data, not its population size, ______ its importance to campaigns.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"determines"},{"label":"B","text":"determining"},{"label":"C","text":"has determined"},{"label":"D","text":"determine"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of verb forms in a sentence. The plural verb “determine” supplies the main clause with a finite main verb and agrees in number with the plural subject “a state’s voting record and polling data.”\nChoice A is incorrect because the singular verb “determines” doesn’t agree in number with the plural subject “a state’s voting record and polling data.” Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle “determining” doesn’t supply the main clause with a finite plural verb. Choice C is incorrect because the singular verb “has determined” doesn’t agree in number with the plural subject “a state’s voting record and polling data.”","is_grid_in":false},{"source_id":"235c8338","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"That the expansionist appetites of colonial European powers had their sights set on his country was evident to Siam’s King ______ deterring those ambitions through international diplomacy and domestic reform was perhaps his foremost achievement. Though his reign ended roughly twenty years before Siam became known by its modern name of Thailand, King Chulalongkorn is often credited with ushering the nation into modernity.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"Chulalongkorn;"},{"label":"B","text":"Chulalongkorn that"},{"label":"C","text":"Chulalongkorn,"},{"label":"D","text":"Chulalongkorn"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (“That...Chulalongkorn”) and the second main clause (“deterring...achievement”).\nChoice B is incorrect. Using the conjunction “that” to introduce “deterring...achievement” as a subordinate element of the main clause (“That...Chulalongkorn”) results in a confusing and ungrammatical sentence. Choice C is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Choice D is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.","is_grid_in":false},{"source_id":"b771d175","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"Scala is referred to as a compiled programming language because it typically incorporates a compiler—a tool that translates lines of code into executable commands. Compiling isn’t exclusive to certain programming ______ any language can incorporate this tool.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"languages. However,"},{"label":"B","text":"languages; however,"},{"label":"C","text":"languages, however,"},{"label":"D","text":"languages, however;"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “however” from the preceding main clause (“Compiling...languages”) and uses a semicolon to join the next main clause (“any...tool”) to the rest of the sentence. Further, placing the semicolon after “however” indicates that the information in the preceding main clause (“compiling isn’t exclusive to certain programming languages”) is contrary to what might be assumed from the information in the previous sentence (Scala’s status as a compiled programming language might suggest that compiling is unique to certain languages).\nChoice A is incorrect because placing a period after “languages” and starting a new sentence with “however” illogically indicates that the information in the next sentence (any language can incorporate a compiler) is contrary to the information in the previous sentence (“compiling isn’t exclusive to certain programming languages”). Instead, the information following “however” supports the previous claim. Choice B is incorrect because placing the semicolon after “languages” illogically indicates that the information in the next main clause (any language can incorporate a compiler) is contrary to the information in the previous clause (“compiling isn’t exclusive to certain programming languages”). Instead, the information following “however” supports the previous claim. Choice C is incorrect because it results in a comma splice. Commas can’t be used in this way to punctuate a supplementary word or phrase between two main clauses.","is_grid_in":false},{"source_id":"05a14e18","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"While the ancient Celts—Iron Age peoples who inhabited parts of western and central Europe—weren’t a single unified group, their art often featured common elements. These included intricate patterns of interlocking spiral lines, which often held symbolic ______ of birds, horses, and other animals; and inlaid enamel accents.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"significance; depictions"},{"label":"B","text":"significance, depictions"},{"label":"C","text":"significance: depictions"},{"label":"D","text":"significance. Depictions"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is the punctuation of elements in a complex series. It’s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after “significance” is conventionally used to separate the first item (“intricate...significance”) and the second item (“depictions...animals”) in the series of common elements found in Celtic art. Moreover, the semicolon after “significance” matches the semicolon used later to separate the second item (“depictions...animals”) and the third item (“and...accents”) in the series.\nChoice B is incorrect because a comma after “significance” doesn’t match the semicolon used later to separate the second and third items in the series (“depictions...animals” and “and...accents”). Choice C is incorrect because a colon can’t be used in this way to separate items in a complex series. Choice D is incorrect because placing a period after “significance” results in a rhetorically unacceptable sentence fragment beginning with “depictions.”","is_grid_in":false},{"source_id":"43b88827","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"medium","passage":"In October of 1648, representatives from 96 different parties convened to sign the final treaties of the Peace of Westphalia. The treaties, which brought an end to the Thirty Years’ War, ______ signed in the cities of Osnabrück and Münster, both located in the Holy Roman Empire–controlled region of Westphalia.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"were"},{"label":"B","text":"is"},{"label":"C","text":"was"},{"label":"D","text":"has been"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is subject-verb agreement. The plural verb “were signed” agrees in number with the plural subject “the treaties.”\nChoice B is incorrect because the singular verb “is signed” doesn’t agree in number with the plural subject “the treaties.” Choice C is incorrect because the singular verb “was signed” doesn’t agree in number with the plural subject “the treaties.” Choice D is incorrect because the singular verb “has been signed” doesn’t agree in number with the plural subject “the treaties.”","is_grid_in":false},{"source_id":"99dedf36","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"When a given term—“self-fulfilling prophecies” and “role models” are two well-known examples—is generally accepted and frequently used, ______ susceptible to obliteration by incorporation (OBI). In cases of OBI, widely used terms are rarely, if at all, attributed to the individuals who coined them.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"they often become"},{"label":"B","text":"these often become"},{"label":"C","text":"this often becomes"},{"label":"D","text":"it often becomes"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun “it” agrees in number with the singular antecedent “a given term” and clearly indicates that the term becomes susceptible to obliteration by incorporation.\nChoice A is incorrect because the plural pronoun “they” neither agrees in number with the singular antecedent “a given term” nor clearly indicates that the given term—not another plural noun in the sentence, such as “examples”—becomes susceptible to obliteration by incorporation. Choice B is incorrect because the plural pronoun “these” neither agrees in number with the singular antecedent “a given term” nor clearly indicates that the given term—not another plural noun in the sentence, such as “examples”—becomes susceptible to obliteration by incorporation. Choice C is incorrect because the singular pronoun “this” is ambiguous in this context, leaving unclear what exactly becomes susceptible to obliteration by incorporation.","is_grid_in":false},{"source_id":"2cb1ee22","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"In premodern Europe, one could sail from the east coast of England to the Netherlands or France faster than one could travel by land to England’s capital, London. In that era, historian Michael Pye argues in his 2015 book The Edge of the World: A Cultural History of the North Sea and the Transformation of Europe, the North Sea did more to link the various peoples, cultures, and economies on ______ shores than to divide them.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"its"},{"label":"B","text":"it’s"},{"label":"C","text":"they’re"},{"label":"D","text":"their"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is the use of possessive determiners. The singular possessive determiner “its” agrees in number with the singular noun “the North Sea” and thus indicates that the shores are those of the North Sea.\nChoice B is incorrect because “it’s” is the contraction for “it is” or “it has,” not a possessive determiner. Choice C is incorrect because “they’re” is the contraction for “they are,” not a possessive determiner. Choice D is incorrect because the plural possessive determiner “their” doesn’t agree in number with the singular noun “the North Sea.”","is_grid_in":false},{"source_id":"e7afd0a1","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"The radial velocity method, a means of indirect planetary discovery, has detected previously unknown exoplanets at vast distances from ______ the gas giant 55 Cancri d; at 60 light-years away, the Neptune-like planet Pi Mensae d; and, as of 2023, over 1,000 other exoplanets that are too far away and dim to be observed directly.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"Earth at 41 light-years away:"},{"label":"B","text":"Earth: at 41 light-years away,"},{"label":"C","text":"Earth, at 41 light-years away,"},{"label":"D","text":"Earth at 41 light-years away,"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. In this choice, a colon is correctly used after the main clause (“The radial...Earth”) to introduce the complex series that follows. Furthermore, the comma after “away” is conventionally used to separate the supplementary phrase “at 41 light-years away” from the noun phrase it describes (“the gas giant 55 Cancri d”), the first item in the series.\nChoice A is incorrect because placing a colon after “away” illogically separates the supplementary phrase “at 41 light-years away” from the noun phrase it describes (“the gas giant 55 Cancri d”) and attaches it to the main clause (“The radial...away”), resulting in a confusing and illogical sentence. Choice C is incorrect because a comma cannot be used in this way to mark the boundary between a main clause (“The radial...Earth”) and a complex series. Choice D is incorrect because it fails to mark the boundary between the main clause (“The radial...Earth”) and the complex series that follows with appropriate punctuation.","is_grid_in":false},{"source_id":"952fd392","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"Alberto Gabriele, author of Reading Popular Culture in Victorian Print, tracks the transnational dissemination of works by author Mary Elizabeth Braddon via the magazine ______ from 1866 to 1899 and distributed throughout the Australian cities of Melbourne, Adelaide, and Hobart; the continental European cities of Brussels, Paris, and Turin; and cities in Turkey, India, and Jamaica, this magazine helped make Braddon’s serialized novels globally available.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"Belgravia; published"},{"label":"B","text":"Belgravia. Published"},{"label":"C","text":"Belgravia published"},{"label":"D","text":"Belgravia, published"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between the first sentence (“Alberto...Belgravia”) and the second (“Published...available”). The participial phrase beginning with “published” contains a complex series punctuated with commas and semicolons (“the Australian cities of Melbourne, Adelaide, and Hobart; the continental European cities of Brussels, Paris, and Turin; and cities in Turkey, India, and Jamaica”), and this participial phrase modifies the subject of the second sentence, “this magazine.”\nChoice A is incorrect. Using a semicolon to join two main clauses in this way in combination with the semicolons that separate the items in the complex series would result in an ambiguous and confusing sentence. Choice C is incorrect because it results in a comma splice. With no punctuation after “Belgravia,” the participial phrase “published...Jamaica” reads as an integrated modifier within the noun phrase “the magazine Belgravia,” and the first main clause (“Alberto...Jamaica”) is then joined to a second main clause (“this...available”) using only a comma. A comma can’t be used in this way to join two main clauses. Choice D is incorrect because it results in a comma splice. A comma can’t be used in this way to join two main clauses.","is_grid_in":false},{"source_id":"72b3db98","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"easy","passage":"Mia Heavener’s 2019 novel Under Nushagak Bluff, which takes place in a mid-twentieth-century rural Alaskan fishing ______ the story of three Yup’ik women who grapple with the rise of commercial fisheries and other changes affecting their community.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"village. Tells"},{"label":"B","text":"village tells"},{"label":"C","text":"village: tells"},{"label":"D","text":"village, tells"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after “village” pairs with the comma after “Under Nushagak Bluff” to separate the supplementary relative clause (“which...village”) from the rest of the sentence. This supplementary relative clause functions to provide additional information about the setting of Heavener’s novel, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence.\nChoice A is incorrect because it results in two rhetorically unacceptable sentence fragments, one beginning with “Mia” and the other beginning with “tells.” Choice B is incorrect because it fails to use appropriate punctuation to separate the supplementary relative clause (“which...village”) from the rest of the sentence. Choice C is incorrect because a colon can’t be paired with a comma in this way to separate the supplementary relative clause (“which...village”) from the rest of the sentence. A colon can be used between two main clauses or a main clause and supplement, but here there is no main clause on either side of the colon.","is_grid_in":false},{"source_id":"c88d6301","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"easy","passage":"In the 1980s, Latino filmmakers Luis Valdez, Gregory Nava, and Ramón Menéndez helped expand on-screen representation of Latino Americans with the films Zoot Suit ______ and Stand and Deliver (1988), respectively.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"(1981) El Norte (1983),"},{"label":"B","text":"(1981)—El Norte (1983)—"},{"label":"C","text":"(1981), El Norte (1983),"},{"label":"D","text":"(1981) El Norte (1983)"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the punctuation of items in a series. The comma after “(1981)” is used conventionally to separate the first and second items in the series, and the comma after “(1983)” is used conventionally to separate the second and third items in the series.\nChoice A is incorrect because it fails to use appropriate punctuation to separate the first and second items in the series. Choice B is incorrect because dashes can’t be used in this way to separate items in a simple series. Choice D is incorrect because it fails to use appropriate punctuation to separate the items in the series.","is_grid_in":false},{"source_id":"aacddbd8","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"As jazz singer Sarah Vaughan honed her vocal abilities—acquiring a sophisticated timbre and precise control over pitch, dynamics, and ______ she earned comparisons to opera icon Leontyne Price, one of her personal heroes. The comparisons highlight how Vaughan, a jazz star, had transcended genre boundaries with her singing prowess.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"vibrato:"},{"label":"B","text":"vibrato,"},{"label":"C","text":"vibrato—"},{"label":"D","text":"vibrato"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. The dash after “vibrato” pairs with the dash after “abilities” to separate the supplementary element (“acquiring...vibrato”) from the rest of the sentence. This supplementary element functions to describe the vocal abilities Vaughan developed, and the pair of dashes indicates that this element could be removed without affecting the grammatical coherence of the sentence.\nChoice A is incorrect because a colon can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a comma can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence.","is_grid_in":false},{"source_id":"261f4ca6","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"easy","passage":"The capital city of the Aztec empire, Tenochtitlan, was built on an island in a lake. Because of the marshy conditions, the Aztec people ______ floating farms called “chinampas.”","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"created"},{"label":"B","text":"created:"},{"label":"C","text":"created,"},{"label":"D","text":"created;"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is punctuation use between a verb and its object. No punctuation is needed between the verb “created” and its object “floating farms called ‘chinampas.’” The object helps complete the idea of the verb—in this case, it explains what the Aztec people created—and any punctuation between the two results in an ungrammatical sentence.\nChoice B is incorrect because no punctuation is needed between the verb and its object. Choice C is incorrect because no punctuation is needed between the verb and its object. Choice D is incorrect because no punctuation is needed between the verb and its object.","is_grid_in":false},{"source_id":"5cc69ee1","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"Dong Lai and Diego J. Muñoz’s work on circumbinary disk accretion—a process in which, due to gravity, material from an orbiting disk spirals inward and accumulates onto two stars or black holes—relies heavily on simulations. Lai and Muñoz recognize the need for direct ______ recommending evolving binary star systems as a promising avenue for future study.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"observation; however,"},{"label":"B","text":"observation, however,"},{"label":"C","text":"observation. However,"},{"label":"D","text":"observation, however;"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after “observation” pairs with the comma after “however” to separate the supplementary adverb “however” from the rest of the sentence, which consists of a main clause (“Lai...observation”) followed by a participial phrase (“recommending...study”).\nChoice A is incorrect because a semicolon can’t be used in this way to join the main clause (“Lai...observation”) and the participial phrase (“recommending...study”) that follows the supplementary adverb “however.” A semicolon is conventionally used to join two main clauses, and “recommending...study” isn’t a main clause. Choice C is incorrect because placing a period after “observation” results in a rhetorically unacceptable sentence fragment beginning with “however.” Choice D is incorrect because a semicolon can’t be used in this way to join the main clause (“Lai...however”) and the participial phrase (“recommending...study”) that follows. A semicolon is conventionally used to join two main clauses, and “recommending...study” isn’t a main clause.","is_grid_in":false},{"source_id":"8999c0c5","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"medium","passage":"Choreographers George Balanchine and Martha Graham both contributed sections to the dance piece Episodes, which premiered at New York’s City Center of Music and Drama in 1959. This cross-genre collaboration brought together the distinct features of Balanchine’s neoclassical ballet and Graham’s modern ______ the stylistic diversity and creative innovation within the dance world.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"dance, it showcased"},{"label":"B","text":"dance. Which showcased"},{"label":"C","text":"dance, showcasing"},{"label":"D","text":"dance. Showcasing"}],"correct_answer":"C","explanation":"Choice C is the best answer. The conventions being tested are the use of punctuation and verb forms within a sentence. This choice correctly uses a comma to mark the boundary between the main clause (“This...dance”) and the supplementary element (“showcasing...world”) that provides additional information about what the collaboration accomplished. Moreover, the nonfinite present participle “showcasing” is used correctly to form a supplementary element that modifies the main clause (“this...dance”), describing what the collaboration demonstrated about stylistic diversity and creative innovation in the dance world.\nChoice A is incorrect because it results in a comma splice. Adding the subject “it” and the finite verb “showcased” results in a second main clause (“it...world”), and a comma can’t be used in this way to join two main clauses. Choice B is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “which.” Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “showcasing.”","is_grid_in":false},{"source_id":"c9a677e9","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"In his 2011 book, historian Sebouh David Aslanian quantifies the reading patterns of early modern Armenian merchants from New Julfa. Aslanian’s macroanalysis ______ nearly 1,000 book titles published between 1512 and 1800 shows not only the steady popularity of religious texts but also a broadening interest in secular books, especially those on history and geography.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"examined"},{"label":"B","text":"examines"},{"label":"C","text":"had examined"},{"label":"D","text":"examining"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. The sentence’s subject is “Aslanian’s macroanalysis,” and its finite main verb is “shows.” This choice correctly uses the nonfinite present participle “examining” to form an integrated participial phrase (“examining...1800”) that describes the macroanalysis, indicating what it examined.\nChoice A is incorrect because using the finite verb “examined” creates an ungrammatical sentence. The sentence already has the finite main verb “shows,” so “examined” can’t also function as a second main verb here without additional punctuation or conjunctions. Choice B is incorrect because using the finite verb “examines” creates an ungrammatical sentence. The sentence already has the finite main verb “shows,” so “examines” can’t also function as a second main verb here without additional punctuation or conjunctions. Choice C is incorrect because using the finite verb “had examined” creates an ungrammatical sentence. The sentence already has the finite main verb “shows,” so “had examined” can’t also function as a second main verb here without additional punctuation or conjunctions.","is_grid_in":false},{"source_id":"6205f7e4","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"medium","passage":"A worker cooperative is a business that is owned and operated by its workers. This model stands in contrast to traditional models in which a smaller group of owners controls a company. Because the profits made by a cooperative are shared by all workers—who are also owners—the workers ______ directly from its success.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"benefit"},{"label":"B","text":"benefited"},{"label":"C","text":"were benefiting"},{"label":"D","text":"had benefited"}],"correct_answer":"A","explanation":"Choice A is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb “benefit” is consistent with the other present tense verbs (“is,” “stands,” and “are shared”) used to describe worker cooperatives and how they function.\nChoice B is incorrect because the past tense verb “benefited” isn’t consistent with the other present tense verbs used to describe worker cooperatives and how they function. Choice C is incorrect because the past progressive tense verb “were benefiting” isn’t consistent with the other present tense verbs used to describe worker cooperatives and how they function. Choice D is incorrect because the past perfect tense verb “had benefited” isn’t consistent with the other present tense verbs used to describe worker cooperatives and how they function.","is_grid_in":false},{"source_id":"8d00cd7c","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"Within Earth’s biomes, there are four main types of desert: arid, semiarid, coastal, and cold. The roughly ______ is classified as an arid desert.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"200,000 km2 Puntland Desert,"},{"label":"B","text":"200,000 km2, Puntland Desert"},{"label":"C","text":"200,000 km2 Puntland Desert"},{"label":"D","text":"200,000 km2, Puntland Desert,"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the use of punctuation between a modifier and a noun and also between a subject and a verb. No punctuation is needed when, as in this case, a modifying phrase (“roughly 200,000 km2”) precedes the noun phrase it modifies (“Puntland Desert”) to form the subject of the sentence. Additionally, no punctuation is needed between the subject (“The roughly...Desert”) and the main verb (“is classified”).\nChoice A is incorrect because no punctuation is needed between the subject and the main verb. Choice B is incorrect because no punctuation is needed between the modifier and the noun phrase. Choice D is incorrect because no punctuation is needed between the modifier and the noun phrase, nor is it needed between the subject and the main verb.","is_grid_in":false},{"source_id":"505054e3","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","passage":"In the eastern Chinese city of Suzhou, known as a hub for silk manufacturing, a unique tradition of embroidery ______ back over two thousand years—one that includes iconic double-sided stitching with different images on each side—remains popular with modern audiences, preserving the city’s cultural heritage.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"dates"},{"label":"B","text":"date"},{"label":"C","text":"dating"},{"label":"D","text":"has dated"}],"correct_answer":"C","explanation":"Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. The sentence’s subject is “a unique tradition of embroidery,” and its finite main verb is “remains.” This choice correctly uses the nonfinite present participle “dating” to form an integrated participial phrase (“dating...years”) that modifies the subject, providing additional information about how far back the tradition goes.\nChoice A is incorrect because it results in an ungrammatical sentence. Using the finite present tense verb “dates” creates a second finite verb in the main clause, which already has the finite verb “remains” as its main verb. Choice B is incorrect because it results in an ungrammatical sentence. Using the finite present tense verb “date” creates a second finite verb in the main clause, which already has the finite verb “remains” as its main verb. Furthermore, the plural verb “date” doesn’t agree in number with the singular subject, “a unique tradition of embroidery.” Choice D is incorrect because it results in an ungrammatical sentence. Using the finite present perfect tense verb “has dated” creates a second finite verb in the main clause, which already has the finite verb “remains” as its main verb.","is_grid_in":false},{"source_id":"92f309b2","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"Arms outstretched, right wrist over left with both hands dangling, South Korean musician Psy galloped from one foot to the other in the iconic dance of his 2012 international hit song “Gangnam Style.” Later, a statue depicting Psy’s arm-positioning during the dance was erected in the place that inspired the song’s ______ Gangnam District in Seoul, South Korea.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"name;"},{"label":"B","text":"name."},{"label":"C","text":"name"},{"label":"D","text":"name—"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a dash after the main clause (“Later...name”) to introduce the supplementary element (“Gangnam...Korea”) that identifies the place that inspired the song’s name.\nChoice A is incorrect because a semicolon can’t be used in this way to join the main clause (“Later...name”) and the supplementary element (“Gangnam...Korea”). A semicolon is conventionally used to join two main clauses. Choice B is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “Gangnam.” Choice C is incorrect because it fails to mark the boundary between the main clause and the supplementary element with appropriate punctuation.","is_grid_in":false},{"source_id":"4b424102","section":"reading_writing","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","passage":"The Balkan nation of Bosnia and Herzegovina does not have one president but ______ as members of the office of the presidency, one representing the nation’s Bosniaks, one its Serbs, and one its Croats, these elected officials take turns serving as the office’s chairperson.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"three, known"},{"label":"B","text":"three. Known"},{"label":"C","text":"three who are known"},{"label":"D","text":"three, who are known"}],"correct_answer":"B","explanation":"Choice B is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (“The Balkan...three”) and another (“Known...chairperson”). While the supplementary element (“known...Croats”) could logically be attached to either the first main clause (“The Balkan...three”) or the second main clause (“these elected...chairperson”), end-of-sentence punctuation is needed to indicate to which sentence the supplementary element belongs.\nChoice A is incorrect because it results in a comma splice. In this choice, the first sentence, consisting of a main clause (“The Balkan...three”) and supplementary element (“known...Croats”), is incorrectly joined with a second main clause (“these elected...chairperson”) using a comma. A comma can’t be used in this way to join two sentences. Choice C is incorrect because it results in a comma splice. In this choice, the first sentence, consisting of a main clause (“The Balkan...three”) and a relative clause (“who are...Croats”), is incorrectly joined with a second main clause (“these elected...chairperson”) using a comma. A comma can’t be used in this way to join two sentences. Additionally, this choice omits the comma needed after “three” to mark the beginning of the supplementary relative clause (“who are known...Croats”). Choice D is incorrect because it results in a comma splice. In this choice, the first sentence, consisting of a main clause (“The Balkan...three”) and a supplementary relative clause (“who are...Croats”), is incorrectly joined with a second main clause (“these elected...chairperson”) using a comma. A comma can’t be used in this way to join two sentences.","is_grid_in":false},{"source_id":"f570cece","section":"reading_writing","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"medium","passage":"Both Arteaga, in the state of Coahuila, and Lagos de Moreno, in the state of Jalisco, have been designated by Mexico as pueblos mágicos (magical villages) to celebrate these ______ natural beauty and unique cultural traditions.","passage_html":null,"question_text":"Which choice completes the text so that it conforms to the conventions of Standard English?","question_text_html":null,"choices":[{"label":"A","text":"town"},{"label":"B","text":"town’s"},{"label":"C","text":"towns"},{"label":"D","text":"towns’"}],"correct_answer":"D","explanation":"Choice D is the best answer. The convention being tested is the use of possessive nouns. The plural possessive noun “towns’” correctly indicates that the natural beauty and unique cultural traditions belong to both Arteaga and Lagos de Moreno.\nChoice A is incorrect because the context requires the plural possessive noun “towns’,” not the singular noun “town.” Choice B is incorrect because the context requires the plural possessive noun “towns’,” not the singular possessive noun “town’s.” Choice C is incorrect because the context requires the plural possessive noun “towns’,” not the plural noun “towns.”","is_grid_in":false}]$msdc_questions$::jsonb
) as item(
  source_id text,
  section text,
  domain text,
  skill text,
  difficulty text,
  passage text,
  passage_html text,
  question_text text,
  question_text_html text,
  choices jsonb,
  correct_answer text,
  explanation text,
  is_grid_in boolean
);

do $$
declare
  row_count integer;
  id_count integer;
begin
  select count(*), count(distinct source_id)
    into row_count, id_count
    from _sathack_msdc_questions_20260921;
  if row_count <> 270 or id_count <> 270 then
    raise exception 'MSDC import validation failed: expected 270 unique questions, got % rows and % ids', row_count, id_count;
  end if;
  if exists (
    select 1 from _sathack_msdc_questions_20260921
    where source_id is null or question_text is null or correct_answer is null
  ) then
    raise exception 'MSDC import validation failed: a required field is null';
  end if;
end $$;

-- Repair a partial or older copy without changing the row id, so saved items
-- and practice history keep their foreign-key relationships.
update public.questions as existing
set section = incoming.section::public.question_section,
    domain = incoming.domain,
    skill = incoming.skill,
    difficulty = incoming.difficulty::public.question_difficulty,
    passage = incoming.passage,
    passage_html = incoming.passage_html,
    question_text = incoming.question_text,
    question_text_html = incoming.question_text_html,
    choices = incoming.choices,
    correct_answer = incoming.correct_answer,
    explanation = incoming.explanation,
    is_grid_in = incoming.is_grid_in,
    is_official = true,
    usable = true
from _sathack_msdc_questions_20260921 as incoming
where existing.source_id = incoming.source_id;

insert into public.questions (
  section, domain, skill, difficulty, passage, passage_html, question_text,
  question_text_html, choices, correct_answer, explanation, source_id,
  is_grid_in, is_official, usable
)
select
  incoming.section::public.question_section,
  incoming.domain,
  incoming.skill,
  incoming.difficulty::public.question_difficulty,
  incoming.passage,
  incoming.passage_html,
  incoming.question_text,
  incoming.question_text_html,
  incoming.choices,
  incoming.correct_answer,
  incoming.explanation,
  incoming.source_id,
  incoming.is_grid_in,
  true,
  true
from _sathack_msdc_questions_20260921 as incoming
where not exists (
  select 1 from public.questions as existing
  where existing.source_id = incoming.source_id
);

do $$
declare
  imported_count integer;
begin
  select count(distinct existing.source_id)
    into imported_count
    from public.questions as existing
    join _sathack_msdc_questions_20260921 as incoming
      on incoming.source_id = existing.source_id
   where existing.is_official = true and existing.usable = true;
  if imported_count <> 270 then
    raise exception 'MSDC import verification failed: expected 270, found %', imported_count;
  end if;
end $$;

commit;
